  ui_story_5037_50370201_12_dialog_content = "Dê-me mais alguns minutos, e eu irei.",
  ui_story_5037_50370201_13_dialog_content = "<size=45>Mestre-!</size>",
  ui_story_5037_50370201_14_dialog_content = "Como você está tão relaxado em um momento como este?!",
  ui_story_5037_50370201_15_dialog_content = "Goldie e PlayerName já ensaiou um monte.",
  ui_story_5037_50370201_16_dialog_content = "Bem, se eles já fizeram isso, acho que não precisamos.",
  ui_story_5037_50370201_17_dialog_content = "É perda de tempo todo mundo fazer a mesma coisa.",
  ui_story_5037_50370201_18_dialog_content = "*Inspira* Você está vomitando bobagens de novo?",
  ui_story_5037_50370201_19_dialog_content = "Uma coisa é durante o treino, mas agora temos que levar a sério!",
  ui_story_5037_50370201_20_dialog_content = "Não receberemos o bônus se perdermos para PlayerName!",
  ui_story_5037_50370201_21_dialog_content = "Eu sei! Vamos colocar Shira no meu lugar!",
  ui_story_5037_50370201_22_dialog_content = "NÃO NÃO!",
  ui_story_5037_50370201_23_dialog_content = "Não entendo... Por que você insiste em dificultar a vida do seu antigo patrão?",
  ui_story_5037_50370201_24_dialog_content = "Hmm, eu me pergunto quem se gabou de quase se tornar um ídolo.",
  ui_story_5037_50370201_25_dialog_content = "Quando foi que me gabei, Fia? Foi um fato!",
  ui_story_5037_50370201_26_dialog_content = "Bem, lá vai você.",
  ui_story_5037_50370201_27_dialog_content = "Você tem a chance de ser um ídolo hoje! Você não deveria estar feliz?",
  ui_story_5037_50370201_28_dialog_content = "Só no nome está bom. Eu não quero ser um ídolo de verdade.",
  ui_story_5037_50370201_29_dialog_content = "Se o fizesse, seria um treinador de ídolos para bestas maravilhosas!",
  ui_story_5037_50370201_30_dialog_content = "Mais uma razão para você ganhar algum dinheiro para poder cuidar das criaturas que você tem!",
  ui_story_5037_50370201_31_dialog_content = "O pagamento por estar no programa só pode sustentar suas próprias necessidades de vida.",
  ui_story_5037_50370201_32_dialog_content = "você precisa bater PlayerName então temos os meios para melhorar a vida das feras maravilhosas!",
  ui_story_5037_50370201_33_dialog_content = "Mas eu trabalhei duro e fiz trabalhos paralelos...",
  ui_story_5037_50370201_34_dialog_content = "O pagamento combinado desses trabalhos nem chega a esse show.",
  ui_story_5037_50370201_35_dialog_content = "Os pobres animais vão morrer de fome se você continuar com esses trabalhos paralelos.",
  ui_story_5037_50370201_36_dialog_content = "Eu tenho que manter você na coleira desta vez e ganhar esse bônus!",
  ui_story_5037_50370201_37_dialog_content = "(não ouvi bem o que eles disseram...)",
  ui_story_5037_50370201_38_dialog_content = "(Mas Fia parecia determinado e impressionante. Em comparação, sinto...)",
  ui_story_5037_50370201_39_dialog_content = "Uau, essa pastilha para tosse é realmente menta e legal!",
  ui_story_5037_50370201_40_dialog_content = "Você é tão atencioso em pensar nisso, Produtor PlayerName!",
  ui_story_5037_50370201_41_dialog_content = "...",
  ui_story_5037_50370201_42_dialog_content = "O que está em sua mente?",
  ui_story_5037_50370201_43_dialog_content = "Nada. Estou feliz que você goste.",
  ui_story_5037_50370201_44_dialog_content = "No futuro, prepararei mais sabores de rebuçados para a tosse calmantes e saborosos para acalmar a sua garganta!",
  ui_story_5037_50370201_45_dialog_content = "Ei, parece que você está pronto para ir.",
  ui_story_5037_50370201_46_dialog_content = "Sim! Vou garantir que você ame o resultado!",
  ui_story_5037_50370201_47_dialog_content = "Amo sua confiança, querida. Estou ansioso por isso.",
  ui_story_5037_50370201_48_dialog_content = "Ué, Senhora Sheol?",
  ui_story_5037_50370201_49_dialog_content = "Sim, PlayerName?",
  ui_story_5037_50370201_50_dialog_content = "Vic estará se apresentando com Goldie no palco?",
  ui_story_5037_50370201_51_dialog_content = "Com o que você está preocupado?",
  ui_story_5037_50370201_52_dialog_content = "Oh, eu estava apenas verificando.",
  ui_story_5037_50370201_53_dialog_content = "Apenas prossiga com o que você planejou.",
  ui_story_5037_50370201_54_dialog_content = "O concerto do Vic não é aqui. Está em um palco vizinho.",
  ui_story_5037_50370201_55_dialog_content = "Goldie e Vic farão seus shows simultaneamente.",
  ui_story_5037_50370201_56_dialog_content = "Outra fase? Não é de admirar que eu não tenha visto Vic nos bastidores.",
  ui_story_5037_50370201_57_dialog_content = "Eu vejo. Então você antecipou esse caminho quando construiu a sala de concertos, hein?",
  ui_story_5037_50370201_58_dialog_content = "É por isso que você configura dois estágios lado a lado.",
  ui_story_5037_50370201_59_dialog_content = "Dois palcos lado a lado?",
  ui_story_5037_50370201_60_dialog_content = "Você deveria estar surpreso, querido. Esta é uma das minhas melhores obras-primas.",
  ui_story_5037_50370201_61_dialog_content = "Apenas um corredor separa os dois palcos.",
  ui_story_5037_50370201_62_dialog_content = "Após o início dos shows, o público pode seguir suas preferências e circular livremente entre os palcos.",
  ui_story_5037_50370201_63_dialog_content = "Ao final, a etapa que conseguir reunir maior público será declarada vencedora.",
  ui_story_5037_50370201_64_dialog_content = "A experiência será inédita e renderá publicidade também para o reality show.",
  ui_story_5037_50370201_65_dialog_content = "Certifique-se de editar a última linha da transmissão, Lilica.",
  ui_story_5037_50370201_66_dialog_content = "Sem problemas!",
  ui_story_5037_50370201_67_dialog_content = "(Me acostumei tanto com a Lilica e sua câmera que esqueci que ela estava com a gente!)",
  ui_story_5037_50370201_68_dialog_content = "Bem, então, boa sorte, querida!",
  ui_story_5037_50370201_69_dialog_content = "Por que não fomos informados sobre isso?",
  ui_story_5037_50370201_70_dialog_content = "Agora preciso reformular o programa do show para torná-lo mais atraente!",
  ui_story_5037_50370201_71_dialog_content = "Ah! Ainda não verifiquei o som e a iluminação...",
  ui_story_5037_50370201_72_dialog_content = "Você verificou, PlayerName.",
  ui_story_5037_50370201_73_dialog_content = "O que? Eu fiz?",
  ui_story_5037_50370201_74_dialog_content = "Qual é o problema com a minha memória...",
  ui_story_5037_50370201_75_dialog_content = "Você está nervoso, PlayerName?",
  ui_story_5037_50370201_76_dialog_content = "Relaxe, nós nos esforçamos bastante em nossa preparação!",
  ui_story_5037_50370201_77_dialog_content = "Não precisamos pensar no que vai acontecer.",
  ui_story_5037_50370201_78_dialog_content = "Contanto que façamos um show como ensaiamos e deixemos a multidão feliz, podemos contar com isso como uma vitória!",
  ui_story_5037_50370201_79_dialog_content = "Sim, sim, tens razão, Goldie.",
  ui_story_5037_50370201_80_dialog_content = "Só precisamos mostrar a eles o que temos praticado!",
  ui_story_5037_50370201_81_dialog_content = "<color=#793f76>Cinco minutos</color> para o show!",
  ui_story_5037_50370201_82_dialog_content = "Ahhhh!",
  ui_story_5037_50370201_83_dialog_content = "Não não não! Parece que ainda tenho um monte de coisas para fazer!",
  ui_story_5037_50370201_84_dialog_content = "Relaxar. Agora é só esperar o show começar!",
  ui_story_5037_50370201_85_dialog_content = "Tem certeza que?",
  ui_story_5037_50370201_86_dialog_content = "Desculpe. Espero que minha ansiedade não esteja afetando você.",
  ui_story_5037_50370201_87_dialog_content = "Eu realmente não sou um produtor competente.",
  ui_story_5037_50370201_88_dialog_content = "Isso não é verdade!",
  ui_story_5037_50370201_89_dialog_content = "Esta é apenas a sua primeira vez!",
  ui_story_5037_50370201_90_dialog_content = "Você está mostrando mil vezes mais compostura agora do que quando subi no palco pela primeira vez.",
  ui_story_5037_50370201_91_dialog_content = "Sua primeira vez em um palco?",
  ui_story_5037_50370201_92_dialog_content = "Sim. Ninguém queria me dar uma chance naquela época.",
  ui_story_5037_50370201_93_dialog_content = "Eu tive que lutar por uma oportunidade de estar no palco.",
  ui_story_5037_50370201_94_dialog_content = "Em seguida, Goldie nos trará uma música alegre!",
  ui_story_5037_50370201_95_dialog_content = "H...Olá a todos!",
  ui_story_5037_50370201_96_dialog_content = "Quem está aí?",
  ui_story_5037_50370201_97_dialog_content = "Não sei, não me importo.",
  ui_story_5037_50370201_98_dialog_content = "Deixa para lá. É uma boa hora para correr para o banheiro.",
  ui_story_5037_50370201_99_dialog_content = "Suspirar...",
  ui_story_5037_50370201_100_dialog_content = "(Como é que tantos deles acabaram de sair?)",
  ui_story_5037_50370201_101_dialog_content = "(Todo mundo está apenas olhando.)",
  ui_story_5037_50370201_102_dialog_content = "(Falando nisso, por que estou aqui?)",
  ui_story_5037_50370201_103_dialog_content = "(O que estou fazendo aqui...?)",
  ui_story_5037_50370201_104_dialog_content = "Você vai fazer alguma coisa ou apenas ficar aí parado?",
  ui_story_5037_50370201_105_dialog_content = "Saia do palco se você não sabe cantar!",
  ui_story_5037_50370201_106_dialog_content = "Ué, eu...",
  ui_story_5037_50370201_107_dialog_content = "Eles vaiaram você para fora do palco?",
  ui_story_5037_50370201_108_dialog_content = "Desculpe, eu não queria lembrá-lo de uma memória tão ruim.",
  ui_story_5037_50370201_109_dialog_content = "Ah, não se preocupe. Isso não me incomoda mais.",
  ui_story_5037_50370201_110_dialog_content = "Hã?",
  ui_story_5037_50370201_111_dialog_content = "Eu disse a mim mesmo naquela época que o começo de toda jornada é difícil.",
  ui_story_5037_50370201_112_dialog_content = "Tudo bem errar, só não cometa os mesmos erros duas vezes!",
  ui_story_5037_50370201_113_dialog_content = "Depois disso, nunca mais fiquei tão nervoso a ponto de esquecer minhas letras de novo.",
  ui_story_5037_50370201_114_dialog_content = "Mas se eu não tivesse superado meu medo do palco da primeira vez e tivesse chafurdado na minha miséria...",
  ui_story_5037_50370201_115_dialog_content = "Eu não teria me tornado quem eu sou hoje.",
  ui_story_5037_50370201_116_dialog_content = "Muito inspirador!",
  ui_story_5037_50370201_117_dialog_content = "Na verdade, ainda fico um pouco nervoso agora.",
  ui_story_5037_50370201_118_dialog_content = "Mas um pouco de estresse melhorará seu foco e fará você se sair melhor.",
  ui_story_5037_50370201_119_dialog_content = "Eu não posso dizer que você está nervoso!",
  ui_story_5037_50370201_120_dialog_content = "Sério? É provavelmente porque você está muito nervoso, então pareço relaxado em comparação.",
  ui_story_5037_50370201_121_dialog_content = "Mas enfim, meu ponto é...",
  ui_story_5037_50370201_122_dialog_content = "Por favor, confie em mim.",
  ui_story_5037_50370201_123_dialog_content = "Afinal, sou um ídolo veterano endurecido pelo palco.",
  ui_story_5037_50370201_124_dialog_content = "Sem falar que agora tenho um excelente produtor que escolheu músicas, figurinos e adereços fantásticos para mim.",
  ui_story_5037_50370201_125_dialog_content = "Ah, sim, e as melhores pastilhas para tosse que já tomei também!",
  ui_story_5037_50370201_126_dialog_content = "Então não vou te decepcionar!",
  ui_story_5037_50370201_127_dialog_content = "Douradinho...",
  ui_story_5037_50370201_128_dialog_content = "Então eu também não deveria decepcioná-lo!",
  ui_story_5037_50370201_129_dialog_content = "Dez segundos para o concerto começar!",
  ui_story_5037_50370201_130_dialog_content = "Dez... nove... oito... sete...",
  ui_story_5037_50370201_131_dialog_content = "Hora de subir ao palco, Produtor!",
  ui_story_5037_50370201_132_dialog_content = "Quebre uma perna, Goldie!",
  ui_story_5037_50370201_133_dialog_content = "Obrigada!",
  ui_story_5037_50370301_1_dialog_content = "Onde quer que Goldie vá, os Goldilocks seguem!",
  ui_story_5037_50370301_2_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370301_3_dialog_content = "A multidão está bombada!",
  ui_story_5037_50370301_4_dialog_content = "O show acabou, mas eles ainda estão gritando o nome de Goldie.",
  ui_story_5037_50370301_5_dialog_content = "Voltei, PlayerName!",
  ui_story_5037_50370301_6_dialog_content = "Muito bem, Goldie!",
  ui_story_5037_50370301_7_dialog_content = "Ei, o que há de errado? Por que você parece que está prestes a chorar?",
  ui_story_5037_50370301_8_dialog_content = "Conseguimos... Conseguimos!",
  ui_story_5037_50370301_9_dialog_content = "Correu incrivelmente bem. Todos se moviam a cada nota sua.",
  ui_story_5037_50370301_10_dialog_content = "Pois é, eu senti lá fora também, era como se eu fosse um com o palco!",
  ui_story_5037_50370301_11_dialog_content = "Suas baladas levaram muitos deles às lágrimas.",
  ui_story_5037_50370301_12_dialog_content = "E as músicas rápidas fizeram todo mundo pular no ritmo!",
  ui_story_5037_50370301_13_dialog_content = "Você apresentou uma performance impecável hoje!",
  ui_story_5037_50370301_14_dialog_content = "Tudo graças ao meu grande produtor, é claro.",
  ui_story_5037_50370301_15_dialog_content = "Eu nunca percebi que poderia dominar músicas assim antes!",
  ui_story_5037_50370301_16_dialog_content = "Só foi possível por causa da iluminação e cenografia.",
  ui_story_5037_50370301_17_dialog_content = "Não importa o público, até eu gostei da performance.",
  ui_story_5037_50370301_18_dialog_content = "Você não parece nada novato, sabe.",
  ui_story_5037_50370301_19_dialog_content = "Em vez disso, você é como um produtor de ídolos versátil, capaz de lidar com qualquer coisa!",
  ui_story_5037_50370301_20_dialog_content = "Haha, você me lisonjeia... Ainda tenho muito o que melhorar.",
  ui_story_5037_50370301_21_dialog_content = "Quase cometi um erro e não tirei um dos adereços a tempo.",
  ui_story_5037_50370301_22_dialog_content = "Levou sua experiência para evitar um desastre.",
  ui_story_5037_50370301_23_dialog_content = "Mas você não vai cometer o mesmo erro da próxima vez, certo?",
  ui_story_5037_50370301_24_dialog_content = "A-Absolutamente não!",
  ui_story_5037_50370301_25_dialog_content = "Haha!",
  ui_story_5037_50370301_26_dialog_content = "Oh, Lady Sheol disse que vai anunciar os resultados na agência.",
  ui_story_5037_50370301_27_dialog_content = "OK, vamos lá.",
  ui_story_5037_50370301_28_dialog_content = "Qual é o problema com você, Mestre? Você não foi com tudo no palco!",
  ui_story_5037_50370301_29_dialog_content = "Mas, surpreendentemente, eles adoraram ver você ser o seu eu preguiçoso de sempre.",
  ui_story_5037_50370301_30_dialog_content = "Eles pensaram que era uma parte deliberada do seu ato!",
  ui_story_5037_50370301_31_dialog_content = "Eu acho que você tem um talento especial para ser um ídolo...",
  ui_story_5037_50370301_32_dialog_content = "Eu não disse que quase me tornei um?",
  ui_story_5037_50370301_33_dialog_content = "Então por que você não debutou com sucesso até hoje?",
  ui_story_5037_50370301_34_dialog_content = "Hum? Eu me pergunto...",
  ui_story_5037_50370301_35_dialog_content = "Porque tenho acompanhado de perto o seu treino!",
  ui_story_5037_50370301_36_dialog_content = "Vic e Fia com certeza estão se divertindo.",
  ui_story_5037_50370301_37_dialog_content = "Parece que o show deles também foi um sucesso.",
  ui_story_5037_50370301_38_dialog_content = "...",
  ui_story_5037_50370301_39_dialog_content = "Não pareça tão estressado! Vic e eu somos ídolos da Starlit Agency.",
  ui_story_5037_50370301_40_dialog_content = "É uma notícia fabulosa que nós dois tivemos uma estreia de sucesso!",
  ui_story_5037_50370301_41_dialog_content = "Sim você está certo!",
  ui_story_5037_50370301_42_dialog_content = "Vejo que todos chegaram.",
  ui_story_5037_50370301_43_dialog_content = "Bom trabalho ao redor. Agora deixe-me ir direto ao ponto.",
  ui_story_5037_50370301_44_dialog_content = "O resultado do concerto é o seguinte:",
  ui_story_5037_50370301_45_dialog_content = "...",
  ui_story_5037_50370301_46_dialog_content = "Prossiga...",
  ui_story_5037_50370301_47_dialog_content = "Uma gravata!",
  ui_story_5037_50370301_48_dialog_content = "O quê?",
  ui_story_5037_50370301_49_dialog_content = "Nosso estreante se manteve firme contra o ídolo experiente, empatando.",
  ui_story_5037_50370301_50_dialog_content = "Nosso show de variedades é cheio de reviravoltas.",
  ui_story_5037_50370301_51_dialog_content = "Eu não deveria ter que me preocupar com as avaliações de agora em diante!",
  ui_story_5037_50370301_52_dialog_content = "Permitam-me lembrá-los, meus queridos.",
  ui_story_5037_50370301_53_dialog_content = "Ambos os ídolos receberam quantidades iguais de apoio neste concerto...",
  ui_story_5037_50370301_54_dialog_content = "mas ainda temos <color=#793f76>dois</color> mais concertos para ir.",
  ui_story_5037_50370301_55_dialog_content = "É o <color=#793f76>suporte de ventilador cumulativo</color> você ganha depois de todos os três concertos que estou considerando.",
  ui_story_5037_50370301_56_dialog_content = "Portanto, independentemente de como você se sentiu sobre esse desempenho,",
  ui_story_5037_50370301_57_dialog_content = "esteja preparado para o próximo concerto de avaliação!",
  ui_story_5037_50370301_58_dialog_content = "Devo ser realmente talentoso para dar um impasse na Srta. Goldie!",
  ui_story_5037_50370301_59_dialog_content = "Mas não acho que meus velhos ossos aguentem mais prática, então posso ir para casa agora...",
  ui_story_5037_50370301_60_dialog_content = "Você está brincando comigo?! Os resultados comprovam...",
  ui_story_5037_50370301_61_dialog_content = "que se você não tivesse retido nada e realmente realizado seu potencial, teríamos derrotado Goldie e PlayerName!",
  ui_story_5037_50370301_62_dialog_content = "Agora temos que começar do zero novamente.",
  ui_story_5037_50370301_63_dialog_content = "Nem pense em relaxar da próxima vez, Mestre!",
  ui_story_5037_50370301_64_dialog_content = "Oi, Fia! Onde você está indo?",
  ui_story_5037_50370301_65_dialog_content = "A sala de ensaio para treinar, duh!",
  ui_story_5037_50370301_66_dialog_content = "Oh, pelo amor de... Quando posso fazer uma pausa?",
  ui_story_5037_50370301_67_dialog_content = "Kyllo! Arraste ele até aqui!",
  ui_story_5037_50370301_68_dialog_content = "Lo!",
  ui_story_5037_50370301_69_dialog_content = "Seja gentil! Kyllo...",
  ui_story_5037_50370301_70_dialog_content = "Vic foi tão impressionante?",
  ui_story_5037_50370301_71_dialog_content = "Sim, eu sabia que ele tinha potencial para ser popular no momento em que pus os olhos nele.",
  ui_story_5037_50370301_72_dialog_content = "Além disso, Fia realmente está trabalhando duro como seu produtor.",
  ui_story_5037_50370301_73_dialog_content = "Ouvi dizer que ela assiste Vic treinar até meia-noite todos os dias.",
  ui_story_5037_50370301_74_dialog_content = "Na verdade, eu mesmo vi algumas vezes.",
  ui_story_5037_50370301_75_dialog_content = "Sempre que Vic relaxava, Fia dizia a Kyllo para morder seu tornozelo!",
  ui_story_5037_50370301_76_dialog_content = "Essa criatura é realmente um motivador tão potente?",
  ui_story_5037_50370301_77_dialog_content = "Devo encontrar meu próprio Kyllo para morder meu tornozelo?",
  ui_story_5037_50370301_78_dialog_content = "Não acho que isso seja necessário.",
  ui_story_5037_50370301_79_dialog_content = "Você já trabalha duro sem esse tipo de empurrão externo!",
  ui_story_5037_50370301_80_dialog_content = "Sou eu quem realmente precisa de um Kyllo.",
  ui_story_5037_50370301_81_dialog_content = "Um novato só alcançou um ídolo notável como você porque eu não trabalhei duro o suficiente.",
  ui_story_5037_50370301_82_dialog_content = "Você não precisa ver dessa forma, PlayerName.",
  ui_story_5037_50370301_83_dialog_content = "A popularidade nunca é uma ciência exata.",
  ui_story_5037_50370301_84_dialog_content = "Pelo menos eu gostei do show hoje e não deixei nenhum arrependimento. Isso é o suficiente para mim!",
  ui_story_5037_50370301_85_dialog_content = "Obrigada...",
  ui_story_5037_50370301_86_dialog_content = "Você pode me consolar, mas eu não posso me consolar!",
  ui_story_5037_50370301_87_dialog_content = "Hã?",
  ui_story_5037_50370301_88_dialog_content = "Vou continuar trabalhando duro para entender as nuances de ser um produtor",
  ui_story_5037_50370301_89_dialog_content = "para que eu possa planejar um cronograma de treinamento melhor para você.",
  ui_story_5037_50370301_90_dialog_content = "Então faremos um show de arrepiar a terra!",
  ui_story_5037_50370301_91_dialog_content = "PlayerName...",
  ui_story_5037_50370301_92_dialog_content = "Apenas um não vai fazer. Ainda temos mais dois shows pela frente... E muitos mais no futuro!",
  ui_story_5037_50370301_93_dialog_content = "Certo, deixe-me reformular isso!",
  ui_story_5037_50370301_94_dialog_content = "Todos os nossos concertos serão avassaladores a partir de agora!",
  ui_story_5037_50370301_95_dialog_content = "Sim!",
  ui_story_5037_50370301_96_dialog_content = "Estou ansioso para trabalhar com você!",
  ui_story_5037_50370301_97_dialog_content = "Entrevista de amigos pós-concerto...",
  ui_story_5037_50370301_98_dialog_content = "Ação!",
  ui_story_5037_50370301_99_dialog_content = "Em uma escala de um a dez, como você avaliaria o show?",
  ui_story_5037_50370301_100_dialog_content = "O máximo dez, é claro!",
  ui_story_5037_50370301_101_dialog_content = "Eu diria oito. Ainda há espaço para melhorias.",
  ui_story_5037_50370301_102_dialog_content = "O que esses dois podem alcançar juntos?",
  ui_story_5037_50370301_103_dialog_content = "O que? Oh, sim, eu não assisti ao show.",
  ui_story_5037_50370301_104_dialog_content = "A resposta foi muito positiva, você disse?",
  ui_story_5037_50370301_105_dialog_content = "Como você avaliaria o desempenho adversário?",
  ui_story_5037_50370301_106_dialog_content = "Uh... Provavelmente dez também, já que vimos o esforço que Vic e Fia fizeram.",
  ui_story_5037_50370301_107_dialog_content = "Mais oito. Ainda há espaço para melhorias.",
  ui_story_5037_50370301_108_dialog_content = "Devo responder?",
  ui_story_5037_50370301_109_dialog_content = "Como seu amigo mudou recentemente?",
  ui_story_5037_50370301_110_dialog_content = "PlayerName está muito mais disciplinado agora e não dorme mais demais.",
  ui_story_5037_50370301_111_dialog_content = "Ele aprende muito mais rápido do que eu esperava e realmente se adaptou ao papel de produtor rapidamente.",
  ui_story_5037_50370301_112_dialog_content = "Não sei, eles me parecem iguais.",
  ui_story_5037_50370301_113_dialog_content = "E isso é um embrulho para as entrevistas pós-concerto!",
  ui_story_5037_50370301_114_dialog_content = "O que? Já começaram a praticar?",
  ui_story_5037_50370301_115_dialog_content = "Eu tenho que ir filmar isso!",
  ui_story_5037_50370401_1_dialog_content = "Para onde esse suporte maior deve ir, produtor?",
  ui_story_5037_50370401_2_dialog_content = "Por favor, mova-o para o centro do palco e certifique-se de que esteja perfeitamente centralizado.",
  ui_story_5037_50370401_3_dialog_content = "Como está essa iluminação, Produtor?",
  ui_story_5037_50370401_4_dialog_content = "Muito brilhoso. Abaixe um pouco, por favor.",
  ui_story_5037_50370401_5_dialog_content = "Importa-se de verificar isso, produtor?",
  ui_story_5037_50370401_6_dialog_content = "E esse problema aqui, Produtor?",
  ui_story_5037_50370401_7_dialog_content = "Produtor! Produtor!",
  ui_story_5037_50370401_8_dialog_content = "Um de cada vez, um de cada vez...!",
  ui_story_5037_50370401_9_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50370401_10_dialog_content = "Ufa, que bom que acabou.",
  ui_story_5037_50370401_11_dialog_content = "Bom trabalho.",
  ui_story_5037_50370401_12_dialog_content = "Está tudo pronto, Goldie?",
  ui_story_5037_50370401_13_dialog_content = "Tudo pronto!",
  ui_story_5037_50370401_14_dialog_content = "O mesmo de antes. Sem novidades?",
  ui_story_5037_50370401_15_dialog_content = "O mesmo de antes. Sem novidades!",
  ui_story_5037_50370401_16_dialog_content = "Aqui.",
  ui_story_5037_50370401_17_dialog_content = "Obrigada!",
  ui_story_5037_50370401_18_dialog_content = "Espere, o que é \"mesma velha, mesma velha\"? Você está falando em código?",
  ui_story_5037_50370401_19_dialog_content = "O que você acabou de dar a Goldie, PlayerName? Minha câmera não capturou.",
  ui_story_5037_50370401_20_dialog_content = "Oh, é uma coisa especial que temos.",
  ui_story_5037_50370401_21_dialog_content = "Sabendo que gosto de rebuçados de menta para a tosse, o meu produtor carrega-os consigo o tempo todo.",
  ui_story_5037_50370401_22_dialog_content = "Ele apenas me deu um pedaço, só isso.",
  ui_story_5037_50370401_23_dialog_content = "Quando vocês dois desenvolveram essa química?",
  ui_story_5037_50370401_24_dialog_content = "Hum, nos últimos dias.",
  ui_story_5037_50370401_25_dialog_content = "Já trabalhamos juntos há tanto tempo que podemos saber o que o outro está pensando só de olhar.",
  ui_story_5037_50370401_26_dialog_content = "Inacreditável...",
  ui_story_5037_50370401_27_dialog_content = "Espera!",
  ui_story_5037_50370401_28_dialog_content = "O que devo filmar se vocês nem falam?",
  ui_story_5037_50370401_29_dialog_content = "Você er, quer que eu vá ter uma conversa com ele agora?",
  ui_story_5037_50370401_30_dialog_content = "Isso seria muito falso.",
  ui_story_5037_50370401_31_dialog_content = "Eu sei!",
  ui_story_5037_50370401_32_dialog_content = "Posso entrevistá-lo como fiz com seus amigos!",
  ui_story_5037_50370401_33_dialog_content = "Ehehe, eu sou um gênio!",
  ui_story_5037_50370401_34_dialog_content = "Você entrevistou meus amigos? Quando?",
  ui_story_5037_50370401_35_dialog_content = "Você descobrirá quando o programa estrear!",
  ui_story_5037_50370401_36_dialog_content = "Agora vamos reservar um tempo para... a entrevista exclusiva pré-concerto!",
  ui_story_5037_50370401_37_dialog_content = "Equipe Exclusiva PlayerName avaliação entrevista concerto...",
  ui_story_5037_50370401_38_dialog_content = "Ação!",
  ui_story_5037_50370401_39_dialog_content = "Qual é a diferença entre um concerto de avaliação e um concerto de estreia?",
  ui_story_5037_50370401_40_dialog_content = "Um concerto de estreia apenas prova que posso assinar como um ídolo com a Starlit Agency.",
  ui_story_5037_50370401_41_dialog_content = "Para mim, o concerto de estreia é como a porta de entrada para o meu sonho.",
  ui_story_5037_50370401_42_dialog_content = "Mas o que posso fazer depois de realizar meu sonho?",
  ui_story_5037_50370401_43_dialog_content = "Realizar o melhor de minhas habilidades para provar a mim mesmo, naturalmente.",
  ui_story_5037_50370401_44_dialog_content = "O show de avaliação é um teste da agência, com o objetivo de verificar o quanto avançamos em nosso treinamento.",
  ui_story_5037_50370401_45_dialog_content = "Mas para nós, é mais como um teste de nossas habilidades dos Cachinhos Dourados.",
  ui_story_5037_50370401_46_dialog_content = "Isso mesmo. Quero provar a todos...",
  ui_story_5037_50370401_47_dialog_content = "que não importa onde eu esteja, jamais esquecerei de onde vim!",
  ui_story_5037_50370401_48_dialog_content = "Você sente alguma pressão se preparando para o show?",
  ui_story_5037_50370401_49_dialog_content = "Nenhum mesmo!",
  ui_story_5037_50370401_50_dialog_content = "Estou brincando! É normal sentir pressão.",
  ui_story_5037_50370401_51_dialog_content = "Mas estou realmente agradecido por meu produtor aqui ter tirado muito peso dos meus ombros.",
  ui_story_5037_50370401_52_dialog_content = "Consegui me concentrar no treinamento, o que facilitou muito as coisas para mim.",
  ui_story_5037_50370401_53_dialog_content = "Quanto à evolução do treinamento... você verá no palco mais tarde!",
  ui_story_5037_50370401_54_dialog_content = "Você acha que produzir é um trabalho árduo?",
  ui_story_5037_50370401_55_dialog_content = "Honestamente, no período logo antes do show de estreia, eu passei por um momento muito difícil.",
  ui_story_5037_50370401_56_dialog_content = "Cometi muitos erros na preparação que antecedeu o show.",
  ui_story_5037_50370401_57_dialog_content = "Mas agora eu praticamente me acomodei no trabalho e me familiarizei com todos os seus meandros.",
  ui_story_5037_50370401_58_dialog_content = "Eu nunca vou cometer o mesmo erro duas vezes.",
  ui_story_5037_50370401_59_dialog_content = "Sim, posso testemunhar isso!",
  ui_story_5037_50370401_60_dialog_content = "PlayerName é um produtor muito profissional agora.",
  ui_story_5037_50370401_61_dialog_content = "E ele tem estado tão ocupado. Quase não havia tempo para dormir.",
  ui_story_5037_50370401_62_dialog_content = "Produtor PlayerName realmente trabalhou muito duro para se preparar para o show!",
  ui_story_5037_50370401_63_dialog_content = "Eu estava apenas fazendo meu trabalho.",
  ui_story_5037_50370401_64_dialog_content = "Ser capaz de ajudá-lo a preparar o palco mais luxuoso para dar aos Cachinhos Dourados uma performance inesquecível fez tudo valer a pena para mim.",
  ui_story_5037_50370401_65_dialog_content = "Para ser sincero, nem parece trabalho para mim!",
  ui_story_5037_50370401_66_dialog_content = "Você poderia nos dar uma pequena dica sobre o que você planejou para nós?",
  ui_story_5037_50370401_67_dialog_content = "É um segredo.",
  ui_story_5037_50370401_68_dialog_content = "Nosso programa desta vez é totalmente novo, nunca antes visto.",
  ui_story_5037_50370401_69_dialog_content = "Na verdade, podemos divulgar o tema do nosso concerto.",
  ui_story_5037_50370401_70_dialog_content = "Oh, certo.",
  ui_story_5037_50370401_71_dialog_content = "PlayerName surgiu com três temas diferentes para os três concertos.",
  ui_story_5037_50370401_72_dialog_content = "O tema do concerto de estreia foi <color=#793f76>Novo começo</color>. Espero que o público tenha captado o significado por trás disso.",
  ui_story_5037_50370401_73_dialog_content = "O tema do próximo show é <color=#793f76>flor em botão</color>!",
  ui_story_5037_50370401_74_dialog_content = "Para isso, coreografei toda uma nova rotina com a ajuda do produtor.",
  ui_story_5037_50370401_75_dialog_content = "Você definitivamente não gastará dinheiro para ver um show antigo!",
  ui_story_5037_50370401_76_dialog_content = "Eu apenas cuidei da logística. Goldie deve receber a maior parte do crédito.",
  ui_story_5037_50370401_77_dialog_content = "No começo, eu faria com que ela repetisse algumas músicas antigas.",
  ui_story_5037_50370401_78_dialog_content = "Mas ela escreveu várias canções originais apenas para o show.",
  ui_story_5037_50370401_79_dialog_content = "Isso porque um dia, de repente, fiquei inspirado durante o treinamento.",
  ui_story_5037_50370401_80_dialog_content = "Desde que decidi me tornar um ídolo, a vida tem sido uma batalha difícil que sempre lutei sozinha.",
  ui_story_5037_50370401_81_dialog_content = "Agora, não só tenho Produtor PlayerName para me ajudar...",
  ui_story_5037_50370401_82_dialog_content = "mas também tenho um oponente que busca o mesmo objetivo.",
  ui_story_5037_50370401_83_dialog_content = "Não, ao invés de um adversário, acho que Vic é mais parecido com um camarada nesta jornada rumo ao estrelato.",
  ui_story_5037_50370401_84_dialog_content = "Todos esses novos sentimentos me inspiraram a escrever muitas novas canções.",
  ui_story_5037_50370401_85_dialog_content = "Eu os ouvi muitas vezes durante nossos ensaios, mas toda vez que os ouço...",
  ui_story_5037_50370401_86_dialog_content = "eles ainda me movem até o âmago.",
  ui_story_5037_50370401_87_dialog_content = "Acredito que todos acharão nosso programa sincero emocionalmente gratificante!",
  ui_story_5037_50370401_88_dialog_content = "Ouvi dizer que o produtor distribui panfletos todos os dias para ajudar Goldie?",
  ui_story_5037_50370401_89_dialog_content = "Sério? Isso é verdade?",
  ui_story_5037_50370401_90_dialog_content = "Esta é a primeira vez que ouço isso... Como é que você nunca me disse, PlayerName?",
  ui_story_5037_50370401_91_dialog_content = "Eu estava apenas fazendo meu trabalho.",
  ui_story_5037_50370401_92_dialog_content = "Eu me lembro agora!",
  ui_story_5037_50370401_93_dialog_content = "Houve momentos em que você disse que estava pegando comida ou lanches...",
  ui_story_5037_50370401_94_dialog_content = "Em vez disso, você estava distribuindo panfletos?",
  ui_story_5037_50370401_95_dialog_content = "Sim. Desculpe, não queria distraí-la, Goldie. Por isso não te contei.",
  ui_story_5037_50370401_96_dialog_content = "Você sempre diz que resultados não são importantes, e que o que importa é viver a jornada sem arrependimentos...",
  ui_story_5037_50370401_97_dialog_content = "mas ainda quero ajudá-lo a obter mais apoio.",
  ui_story_5037_50370401_98_dialog_content = "Essa é a melhor maneira de garantir que não haja arrependimentos, eu acho.",
  ui_story_5037_50370401_99_dialog_content = "PlayerName...",
  ui_story_5037_50370401_100_dialog_content = "Leve-me com você na próxima vez! Uma performance de rua seria definitivamente mais atraente!",
  ui_story_5037_50370401_101_dialog_content = "Não se esqueça que somos uma equipe!",
  ui_story_5037_50370401_102_dialog_content = "Uma equipa... Sim, somos uma equipa!",
  ui_story_5037_50370401_103_dialog_content = "Você se sente confiante sobre o concerto?",
  ui_story_5037_50370401_104_dialog_content = "Você está confiante em mim, PlayerName?",
  ui_story_5037_50370401_105_dialog_content = "Eu vi os ensaios de Goldie. Eles são perfeitos, praticamente impecáveis.",
  ui_story_5037_50370401_106_dialog_content = "Hoje nada mais é do que um novo local, então estou muito confiante em Goldie!",
  ui_story_5037_50370401_107_dialog_content = "Que coincidência, também confio muito em você!",
  ui_story_5037_50370401_108_dialog_content = "O mesmo de antes. Sem novidades?",
  ui_story_5037_50370401_109_dialog_content = "O mesmo de antes. Sem novidades!",
  ui_story_5037_50370401_110_dialog_content = "Vai! Vai! Vai!",
  ui_story_5037_50370401_111_dialog_content = "Para onde vai esse adereço, produtor?",
  ui_story_5037_50370401_112_dialog_content = "Onde está o produtor?",
  ui_story_5037_50370401_113_dialog_content = "Produtor! Produtor!",
  ui_story_5037_50370401_114_dialog_content = "Ah, eu preciso ir cuidar das coisas!",
  ui_story_5037_50370401_115_dialog_content = "Ufa...",
  ui_story_5037_50370401_116_dialog_content = "O concerto seria impossível sem PlayerName.",
  ui_story_5037_50370401_117_dialog_content = "É hora de me preparar para o palco agora!",
  ui_story_5037_50370501_1_dialog_content = "Em seguida, anunciarei nossos resultados.",
  ui_story_5037_50370501_2_dialog_content = "Eles são muito chocantes desta vez.",
  ui_story_5037_50370501_3_dialog_content = "(O que chocaria até mesmo Lady Sheol?)",
  ui_story_5037_50370501_4_dialog_content = "(Vic ganhou...?)",
  ui_story_5037_50370501_5_dialog_content = "O vencedor aguentou a pressão do primeiro show para ganhar ainda mais apoio do público desta vez.",
  ui_story_5037_50370501_6_dialog_content = "Este foi o fruto do trabalho árduo do ídolo.",
  ui_story_5037_50370501_7_dialog_content = "Bem como a do produtor, é claro.",
  ui_story_5037_50370501_8_dialog_content = "(Trabalho duro em ambas as partes... Isso é o Mestre e eu, não é?)",
  ui_story_5037_50370501_9_dialog_content = "(Sim, o Mestre finalmente derrotou Goldie!)",
  ui_story_5037_50370501_10_dialog_content = "E o vencedor é...",
  ui_story_5037_50370501_11_dialog_content = "...",
  ui_story_5037_50370501_12_dialog_content = "Ele Ele!",
  ui_story_5037_50370501_13_dialog_content = "<size=45>Goldie e PlayerName!</size>",
  ui_story_5037_50370501_14_dialog_content = "Você ouviu isso, PlayerName? Nós ganhamos!",
  ui_story_5037_50370501_15_dialog_content = "N-nós ganhamos?",
  ui_story_5037_50370501_16_dialog_content = "O que é? Como isso pode ser?",
  ui_story_5037_50370501_17_dialog_content = "Finalmente, mais um passo mais perto de casa.",
  ui_story_5037_50370501_18_dialog_content = "Os fatos são duros, mas os números não mentem, e mais pessoas apoiaram Goldie do que Vic desta vez.",
  ui_story_5037_50370501_19_dialog_content = "Mas o desempenho do Mestre foi obviamente melhor do que da última vez, então como é que Goldie venceu?",
  ui_story_5037_50370501_20_dialog_content = "Bem, Goldie realmente teve uma performance fantástica desta vez.",
  ui_story_5037_50370501_21_dialog_content = "O show em si foi criativo, mas a iluminação e o design do palco também foram imaculados.",
  ui_story_5037_50370501_22_dialog_content = "O mais importante é que seu show converteu muitos na platéia em seus fãs.",
  ui_story_5037_50370501_23_dialog_content = "Eles correram para a Cloudrover Guild e compraram sua mercadoria.",
  ui_story_5037_50370501_24_dialog_content = "Eles até compraram produtos que não tinham nada a ver com Goldie.",
  ui_story_5037_50370501_25_dialog_content = "Através do boca a boca dos Cachinhos Dourados...",
  ui_story_5037_50370501_26_dialog_content = "Assistir a um show do Goldie agora é uma das dez atividades obrigatórias em Umbraton.",
  ui_story_5037_50370501_27_dialog_content = "Todos estão ansiosos pelo próximo show da Starlit Agency.",
  ui_story_5037_50370501_28_dialog_content = "Os ingressos já estão esgotados! Você consegue imaginar isso?",
  ui_story_5037_50370501_29_dialog_content = "Quer dizer que não preciso implorar para as pessoas comprarem os ingressos agora?",
  ui_story_5037_50370501_30_dialog_content = "Nunca pensei que recuperaria meu investimento antes mesmo do reality show ir ao ar.",
  ui_story_5037_50370501_31_dialog_content = "Você não precisa mais fazer promoções extras para conseguir novos fãs.",
  ui_story_5037_50370501_32_dialog_content = "Concentre-se na sua performance e abrace o concerto final!",
  ui_story_5037_50370501_33_dialog_content = "Obrigado, Senhora Sheol.",
  ui_story_5037_50370501_34_dialog_content = "Vamos nos esforçar para melhorar e recompensar você e os fãs com melhores performances!",
  ui_story_5037_50370501_35_dialog_content = "Acho que ainda não ouvi falar de você, Vic?",
  ui_story_5037_50370501_36_dialog_content = "Por que simplesmente não esquecemos?",
  ui_story_5037_50370501_37_dialog_content = "Já que perdi, você pode muito bem me deixar ir para casa agora!",
  ui_story_5037_50370501_38_dialog_content = "Eu não compro, simplesmente não compro.",
  ui_story_5037_50370501_39_dialog_content = "Acho que todos vocês conspiraram contra o Mestre e eu.",
  ui_story_5037_50370501_40_dialog_content = "Diga-me, Senhora Sheol!",
  ui_story_5037_50370501_41_dialog_content = "Foi assim que você escreveu o roteiro, certo?",
  ui_story_5037_50370501_42_dialog_content = "Um roteiro para um reality show?",
  ui_story_5037_50370501_43_dialog_content = "Você é um gênio, Fia.",
  ui_story_5037_50370501_44_dialog_content = "Claro que sou! Ele Ele.",
  ui_story_5037_50370501_45_dialog_content = "Espere um segundo, o que te fez dizer isso?",
  ui_story_5037_50370501_46_dialog_content = "Como é que eu não pensei em algo tão criativo quanto escrever um roteiro para o reality show?",
  ui_story_5037_50370501_47_dialog_content = "Eu provavelmente recuperaria meu dinheiro mais rápido.",
  ui_story_5037_50370501_48_dialog_content = "No entanto, Fia, os resultados desta rodada são genuínos.",
  ui_story_5037_50370501_49_dialog_content = "Se ainda tiver dúvidas, fique à vontade para assistir ao replay do show.",
  ui_story_5037_50370501_50_dialog_content = "Venha falar comigo a qualquer momento se tiver dúvidas depois.",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50370501_52_dialog_content = "Como eles fizeram isso? Como eles conseguiram o truque?!",
  ui_story_5037_50370501_53_dialog_content = "Goldie mudou de roupa em apenas um segundo!?",
  ui_story_5037_50370501_54_dialog_content = "E apareceu do nada na platéia, então voou de volta para o palco?",
  ui_story_5037_50370501_55_dialog_content = "Em contraste, nosso show foi mais do que um pouco curto.",
  ui_story_5037_50370501_56_dialog_content = "Não é de admirar que você nunca tenha conseguido antes...",
  ui_story_5037_50370501_57_dialog_content = "Ahn, aham.",
  ui_story_5037_50370501_58_dialog_content = "Então você finalmente entendeu agora? Apesar do meu grande talento, não consigo me igualar a um ídolo profissional.",
  ui_story_5037_50370501_59_dialog_content = "Não é muito cedo para ceder agora. Eu vou fazer as malas.",
  ui_story_5037_50370501_60_dialog_content = "Para!",
  ui_story_5037_50370501_61_dialog_content = "Eu sei mesmo sem você dizer...",
  ui_story_5037_50370501_62_dialog_content = "que não é sua culpa que perdemos.",
  ui_story_5037_50370501_63_dialog_content = "Eu sou o produtor, mas estava tão concentrado no seu treinamento que negligenciei quase todos os outros aspectos do show e do palco.",
  ui_story_5037_50370501_64_dialog_content = "Eu pensei que você era a chave para o sucesso esse tempo todo...",
  ui_story_5037_50370501_65_dialog_content = "Até que acabei de assistir ao show de Goldie e percebi quanto outro potencial um show pode ter!",
  ui_story_5037_50370501_66_dialog_content = "Seu desempenho foi excelente.",
  ui_story_5037_50370501_67_dialog_content = "Mas falhei em lhe dar o palco perfeito.",
  ui_story_5037_50370501_68_dialog_content = "Honestamente, apenas terminar o show foi bom o suficiente para mim, então não se preocupe com isso e vamos para casa...",
  ui_story_5037_50370501_69_dialog_content = "De jeito nenhum, eu não posso ir ainda!",
  ui_story_5037_50370501_70_dialog_content = "Temos um último show para fazer. Ainda podemos mudar as coisas.",
  ui_story_5037_50370501_71_dialog_content = "Desta vez, eu prometo que você será capaz de alcançar seu sonho de ídolo e não terá nenhum arrependimento!",
  ui_story_5037_50370501_72_dialog_content = "O quê...?",
  ui_story_5037_50370501_73_dialog_content = "Acabei de assistir ao replay do show do Vic.",
  ui_story_5037_50370501_74_dialog_content = "Seu desempenho foi como o de um ídolo profissional, Vic.",
  ui_story_5037_50370501_75_dialog_content = "Havia apenas algumas danças que não mostravam adequadamente o seu charme.",
  ui_story_5037_50370501_76_dialog_content = "Sério? Quais?",
  ui_story_5037_50370501_77_dialog_content = "Depois faço uma resenha e mostro pra você, Fia.",
  ui_story_5037_50370501_78_dialog_content = "A propósito, escrevi uma nova balada que acho que combinaria bem com Vic.",
  ui_story_5037_50370501_79_dialog_content = "Darei isso a você também quando terminar a revisão!",
  ui_story_5037_50370501_80_dialog_content = "Maravilha!",
  ui_story_5037_50370501_81_dialog_content = "Mas é... isso é apropriado?",
  ui_story_5037_50370501_82_dialog_content = "Você é nosso concorrente, então por que está nos ajudando?",
  ui_story_5037_50370501_83_dialog_content = "Os ídolos devem trazer esperança e bondade para as pessoas.",
  ui_story_5037_50370501_84_dialog_content = "Como posso ser chamado de ídolo se não consigo nem mesmo trazer bondade para as pessoas ao meu redor?",
  ui_story_5037_50370501_85_dialog_content = "Lembro-me do que você disse antes em uma entrevista...",
  ui_story_5037_50370501_86_dialog_content = "Ao invés de um oponente, acho que Vic é mais parecido com um camarada nesta jornada rumo ao estrelato.",
  ui_story_5037_50370501_87_dialog_content = "Foi realmente genial...",
  ui_story_5037_50370501_88_dialog_content = "Incrível!!",
  ui_story_5037_50370501_89_dialog_content = "Então é assim que um ídolo deve agir?",
  ui_story_5037_50370501_90_dialog_content = "Essa não!",
  ui_story_5037_50370501_91_dialog_content = "As pessoas vão pensar que o Mestre é uma piada por dizer o que eu disse para ele dizer na entrevista!",
  ui_story_5037_50370501_92_dialog_content = "(Eu me pergunto o que eles disseram na entrevista...)",
  ui_story_5037_50370501_93_dialog_content = "Você se importaria de deletar a entrevista que fizemos e gravar outra, Lilica?",
  ui_story_5037_50370501_94_dialog_content = "Receio que isso não seja possível.",
  ui_story_5037_50370501_95_dialog_content = "Este é um reality show, você sabe!",
  ui_story_5037_50370501_96_dialog_content = "Vem cá, Kyllo!",
  ui_story_5037_50370501_97_dialog_content = "Lo!",
  ui_story_5037_50370501_98_dialog_content = "Ei, o que você pensa que está fazendo?",
  ui_story_5037_50370501_99_dialog_content = "Sem refazer, mesmo se você fizer Kyllo morder meu tornozelo!",
  ui_story_5037_50370501_100_dialog_content = "Espere, não fuja!",
  ui_story_5037_50370501_101_dialog_content = "Se você concorda, pode jogar com Kyllo!",
  ui_story_5037_50370501_102_dialog_content = "Hmm, acho que a Fia se esqueceu de mim...",
  ui_story_5037_50370501_103_dialog_content = "Finalmente posso ter meu sono de beleza!",
  ui_story_5037_50370501_104_dialog_content = "Vejo todos vocês mais tarde!",
  ui_story_5037_50370501_105_dialog_content = "O show de avaliação finalmente acabou, Produtor!",
  ui_story_5037_50370501_106_dialog_content = "Você trabalhou muito para isso, Goldie.",
  ui_story_5037_50370501_107_dialog_content = "E que show espetacular foi esse... Atrevo-me a chamá-lo de o maior de todos os tempos?",
  ui_story_5037_50370501_108_dialog_content = "Não sejamos imprudentes, PlayerName.",
  ui_story_5037_50370501_109_dialog_content = "Não temos mais um para ir?",
  ui_story_5037_50370501_110_dialog_content = "Verdadeiro. O melhor show é sempre o próximo!",
  ui_story_5037_50370501_111_dialog_content = "Haha, essa linha é ótima!",
  ui_story_5037_50370501_112_dialog_content = "Já decidiu o tema do último concerto?",
  ui_story_5037_50370501_113_dialog_content = "Oh, isso mesmo, eu ainda preciso dar corpo a isso.",
  ui_story_5037_50370501_114_dialog_content = "Não se preocupe comigo, descanse um pouco!",
  ui_story_5037_50370501_115_dialog_content = "Tudo bem! Você também faz o mesmo, PlayerName!",
  ui_story_5037_50370501_116_dialog_content = "Marshmallow.",
  ui_story_5037_50370501_117_dialog_content = "Au!",
  ui_story_5037_50370501_118_dialog_content = "Tinha um ladrão roubando coisas no show.",
  ui_story_5037_50370501_119_dialog_content = "Você também percebeu?",
  ui_story_5037_50370501_120_dialog_content = "Au!",
  ui_story_5037_50370501_121_dialog_content = "Não acredito que alguém ousaria fazer isso no meu show...",
  ui_story_5037_50370501_122_dialog_content = "Você está pronto, Marshmallow?",
  ui_story_5037_50370501_123_dialog_content = "Faremos justiça rápida esta noite!",
  ui_story_5037_50370501_124_dialog_content = "Au!",
  ui_story_5037_50370501_125_dialog_content = "Entrevista de amigos pós-concerto...",
  ui_story_5037_50370501_126_dialog_content = "Ação!",
  ui_story_5037_50370501_127_dialog_content = "Em uma escala de um a dez, como você avaliaria o show?",
  ui_story_5037_50370501_128_dialog_content = "Doze com certeza!",
  ui_story_5037_50370501_129_dialog_content = "Perto de um dez.",
  ui_story_5037_50370501_130_dialog_content = "Pfft, não acredito que aquele cara estava realmente cantando e dançando no palco...",
  ui_story_5037_50370501_131_dialog_content = "Mas não quero dar nota.",
  ui_story_5037_50370501_132_dialog_content = "Por quê? Porque não quero que esses dois pensem muito bem de si mesmos.",
  ui_story_5037_50370501_133_dialog_content = "Como você se sente sobre o show do adversário?",
  ui_story_5037_50370501_134_dialog_content = "Dez!",
  ui_story_5037_50370501_135_dialog_content = "Foi impecável, mas o show de Goldie foi obviamente muito mais envolvente.",
  ui_story_5037_50370501_136_dialog_content = "Nove.",
  ui_story_5037_50370501_137_dialog_content = "Eu não assisti, mas provavelmente não tão bom quanto Fia e Vic.",
  ui_story_5037_50370501_138_dialog_content = "Há algo que você quer dizer ao seu amigo?",
  ui_story_5037_50370501_139_dialog_content = "Seja você mesmo e vá buscá-los, PlayerName!",
  ui_story_5037_50370501_140_dialog_content = "O esforço produz resultados.",
  ui_story_5037_50370501_141_dialog_content = "Ouvi dizer que há prêmio em dinheiro?",
  ui_story_5037_50370501_142_dialog_content = "É melhor vocês trazerem para casa!",
  ui_story_5037_50370501_143_dialog_content = "Se não...!",
  ui_story_5037_50370501_144_dialog_content = "Por favor, não enrole tentáculos em volta da câmera!",
  ui_story_5037_50370601_1_dialog_content = "Equipe Exclusiva PlayerName entrevista pré-final do show...",
  ui_story_5037_50370601_2_dialog_content = "Ação!",
  ui_story_5037_50370601_3_dialog_content = "Qual é o tema que você escolheu para o concerto final?",
  ui_story_5037_50370601_4_dialog_content = "Nosso tema desta vez é \"Juventude desenfreada\".",
  ui_story_5037_50370601_5_dialog_content = "Ah, por falar nisso...",
  ui_story_5037_50370601_6_dialog_content = "O concerto é definitivo apenas no nome. Goldie não está deixando a Starlit Agency.",
  ui_story_5037_50370601_7_dialog_content = "Isso mesmo, de \"New Beginning\" a \"Budding Flower\" a \"Unbridled Youth\"...",
  ui_story_5037_50370601_8_dialog_content = "Todas as três performances pretendem apresentar o microcosmo da metamorfose de um ídolo ao longo do reality show.",
  ui_story_5037_50370601_9_dialog_content = "Goldie permanecerá ativo mesmo após o término do programa.",
  ui_story_5037_50370601_10_dialog_content = "Isso é verdade. Terei mais shows por vir!",
  ui_story_5037_50370601_11_dialog_content = "Embora eu não seja mais o produtor de Goldie até então...",
  ui_story_5037_50370601_12_dialog_content = "...",
  ui_story_5037_50370601_13_dialog_content = "Bem, é muito difícil se tornar um produtor da Starlit Agency.",
  ui_story_5037_50370601_14_dialog_content = "Você tem que enviar um currículo e passar em todos os tipos de testes.",
  ui_story_5037_50370601_15_dialog_content = "Mesmo um excelente produtor como PlayerName teria dúvidas.",
  ui_story_5037_50370601_16_dialog_content = "Se não fosse pelo reality show, eu provavelmente teria me perdido na confusão entre os talentos de Umbraton.",
  ui_story_5037_50370601_17_dialog_content = "Depois que o programa acabar, não acho que vou conseguir derrotar outras pessoas para me tornar um produtor de verdade.",
  ui_story_5037_50370601_18_dialog_content = "Mas estou satisfeito apenas com a chance de ver Goldie nesta parte de sua carreira.",
  ui_story_5037_50370601_19_dialog_content = "PlayerName...",
  ui_story_5037_50370601_20_dialog_content = "É muito cedo para ficar todo sentimental!",
  ui_story_5037_50370601_21_dialog_content = "Você escreveu novas músicas para este show, Goldie?",
  ui_story_5037_50370601_22_dialog_content = "De nada.",
  ui_story_5037_50370601_23_dialog_content = "depois de aprender PlayerName escolheu \"Juventude Descontrolada\" para o tema...",
  ui_story_5037_50370601_24_dialog_content = "Eu me perguntei: \"O que exatamente é a juventude??\"",
  ui_story_5037_50370601_25_dialog_content = "Imediatamente, as imagens encheram minha cabeça.",
  ui_story_5037_50370601_26_dialog_content = "É perseguir um ao outro, despreocupado, pelas ruas de Umbraton?",
  ui_story_5037_50370601_27_dialog_content = "É ouvir uma palestra em uma sala de aula com olhos sonolentos?",
  ui_story_5037_50370601_28_dialog_content = "Ou está suando no trabalho para ganhar a vida?",
  ui_story_5037_50370601_29_dialog_content = "Então eu me lembrei, a juventude não é rígida e imutável.",
  ui_story_5037_50370601_30_dialog_content = "Toda forma de juventude merece ser celebrada!",
  ui_story_5037_50370601_31_dialog_content = "A partir dessas imagens, compus as músicas que desejava interpretar.",
  ui_story_5037_50370601_32_dialog_content = "Como você se sente sobre as novas músicas de Goldie desta vez, PlayerName?",
  ui_story_5037_50370601_33_dialog_content = "Oh, você nunca pode errar com as músicas dela!",
  ui_story_5037_50370601_34_dialog_content = "As que ela escreveu para \"Unbridled Youth\" são particularmente cativantes.",
  ui_story_5037_50370601_35_dialog_content = "Especialmente a música sobre caminhos separados...",
  ui_story_5037_50370601_36_dialog_content = "Lady Sheol já o pegou para a música tema de encerramento do reality show.",
  ui_story_5037_50370601_37_dialog_content = "É verdade que nada é para sempre e a separação é inevitável...",
  ui_story_5037_50370601_38_dialog_content = "mas continuarei trabalhando duro, permanecerei relevante e crescerei ao lado de todos.",
  ui_story_5037_50370601_39_dialog_content = "Portanto, fique de olho nos desenvolvimentos de minha carreira!",
  ui_story_5037_50370601_40_dialog_content = "Algo que você gostaria de dizer ao seu produtor, Goldie?",
  ui_story_5037_50370601_41_dialog_content = "O que? Você está perguntando isso antes do show?",
  ui_story_5037_50370601_42_dialog_content = "Está bem.",
  ui_story_5037_50370601_43_dialog_content = "Eu posso estar muito emocionado para falar depois do show de qualquer maneira!",
  ui_story_5037_50370601_44_dialog_content = "Hã?",
  ui_story_5037_50370601_45_dialog_content = "Ahem, o que eu gostaria de dizer ao meu produtor é:",
  ui_story_5037_50370601_46_dialog_content = "Obrigado por ficar comigo todo esse tempo.",
  ui_story_5037_50370601_47_dialog_content = "Para ser sincero, sempre trabalhei sozinho nesse ramo, então não estou acostumado a ter um produtor.",
  ui_story_5037_50370601_48_dialog_content = "É apenas para o reality show que concordei em contratá-lo como meu produtor.",
  ui_story_5037_50370601_49_dialog_content = "Mas desde então, você passou de um novato total para um profissional consumado.",
  ui_story_5037_50370601_50_dialog_content = "Você não apenas cuidou da minha agenda, mas também lidou com os paparazzi e resolveu os detalhes do show...",
  ui_story_5037_50370601_51_dialog_content = "Sua presença me permitiu criar e ensaiar com facilidade.",
  ui_story_5037_50370601_52_dialog_content = "Na verdade, acho cada vez mais difícil imaginar fazer isso sem você.",
  ui_story_5037_50370601_53_dialog_content = "Talvez você nunca mais seja um produtor, mas eu ainda quero que você saiba...",
  ui_story_5037_50370601_54_dialog_content = "você é o melhor produtor para mim...",
  ui_story_5037_50370601_55_dialog_content = "... até aqui.",
  ui_story_5037_50370601_56_dialog_content = "Mas eu sou o único produtor que você já teve.",
  ui_story_5037_50370601_57_dialog_content = "Eu ainda não terminei. Você tem meu apoio no futuro, não importa onde você vá ou o que você faça!",
  ui_story_5037_50370601_58_dialog_content = "Tenho certeza de que você se destacará em tudo o que escolher fazer.",
  ui_story_5037_50370601_59_dialog_content = "E quando chegar essa hora...",
  ui_story_5037_50370601_60_dialog_content = "Eu também vou...",
  ui_story_5037_50370601_61_dialog_content = "Goldie?",
  ui_story_5037_50370601_62_dialog_content = "Tosse...",
  ui_story_5037_50370601_63_dialog_content = "<size=30>Por favor, edite isso, Lilica, e deixe-me começar de novo!</size>",
  ui_story_5037_50370601_64_dialog_content = "Você tem meu apoio no futuro, não importa onde você vá ou o que você faça!",
  ui_story_5037_50370601_65_dialog_content = "Tenho certeza de que você se destacará em tudo o que escolher fazer.",
  ui_story_5037_50370601_66_dialog_content = "Enquanto você estiver fazendo isso, ainda estarei me esforçando no caminho que escolhi, construindo sobre as bases que você preparou para mim!",
  ui_story_5037_50370601_67_dialog_content = "Algo que você gostaria de dizer a Goldie, produtor?",
  ui_story_5037_50370601_68_dialog_content = "Também quero agradecer a Goldie.",
  ui_story_5037_50370601_69_dialog_content = "Graças ao seu encorajamento, fiz tantas coisas com as quais nem ousaria sonhar.",
  ui_story_5037_50370601_70_dialog_content = "Chegamos até aqui só porque você já é uma estrela brilhante!",
  ui_story_5037_50370601_71_dialog_content = "Todas as habilidades que aprendi e desenvolvi durante esse tempo...",
  ui_story_5037_50370601_72_dialog_content = "Cada pedaço é um reflexo do brilho que é Goldie!",
  ui_story_5037_50370601_73_dialog_content = "Você também é brilhante, PlayerName!",
  ui_story_5037_50370601_74_dialog_content = "Mesmo quando não estiver mais ao seu lado, Goldie...",
  ui_story_5037_50370601_75_dialog_content = "Você sempre será uma estrela brilhante.",
  ui_story_5037_50370601_76_dialog_content = "Um dia, você será um ídolo lendário em Astra!",
  ui_story_5037_50370601_77_dialog_content = "E você sempre terá meus cumprimentos e bênçãos.",
  ui_story_5037_50370601_78_dialog_content = "Equipe Exclusiva PlayerName entrevista pré-final do show...",
  ui_story_5037_50370601_79_dialog_content = "é um embrulho!",
  ui_story_5037_50370601_80_dialog_content = "...",
  ui_story_5037_50370601_81_dialog_content = "...",
  ui_story_5037_50370601_82_dialog_content = "Uh, o que há com o silêncio constrangedor?",
  ui_story_5037_50370601_83_dialog_content = "Eu não deveria ter feito essas perguntas?",
  ui_story_5037_50370601_84_dialog_content = "Esse tipo de entrevista prejudica a atmosfera do programa?",
  ui_story_5037_50370601_85_dialog_content = "Por favor, me diga que isso não afetará sua próxima apresentação...",
  ui_story_5037_50370601_86_dialog_content = "Tudo bem, Lílica.",
  ui_story_5037_50370601_87_dialog_content = "Veja, eu estou totalmente bem!",
  ui_story_5037_50370601_88_dialog_content = "Maravilhoso, esse é o sorriso Goldie que conhecemos!",
  ui_story_5037_50370601_89_dialog_content = "Produtor PlayerName!",
  ui_story_5037_50370601_90_dialog_content = "Sim, aqui.",
  ui_story_5037_50370601_91_dialog_content = "Obrigada!",
  ui_story_5037_50370601_92_dialog_content = "Espere, eu perdi alguma coisa de novo?",
  ui_story_5037_50370601_93_dialog_content = "Ah!",
  ui_story_5037_50370601_94_dialog_content = "Essas balas realmente me acalmam.",
  ui_story_5037_50370601_95_dialog_content = "Com licença, que caminho para o show de Goldie?",
  ui_story_5037_50370601_96_dialog_content = "Como um membro da platéia conseguiu ficar nos bastidores?",
  ui_story_5037_50370601_97_dialog_content = "Basta seguir esta passagem e virar à esquerda!",
  ui_story_5037_50370601_98_dialog_content = "Nossa, não acredito nessa sorte! Esta não é a própria Goldie?",
  ui_story_5037_50370601_99_dialog_content = "Sim é! Você pode autografar minha camisa, Goldie?!",
  ui_story_5037_50370601_100_dialog_content = "Eu vim de Northland!",
  ui_story_5037_50370601_101_dialog_content = "Também sou fã! Eu sou da Chave Rediesel!",
  ui_story_5037_50370601_102_dialog_content = "Eu sou da Ilha das Nuvens!",
  ui_story_5037_50370601_103_dialog_content = "Eu sou da Euforia!",
  ui_story_5037_50370601_104_dialog_content = "Todos, todos!",
  ui_story_5037_50370601_105_dialog_content = "Goldie terá tempo para autografar e tirar fotos com todos após o show.",
  ui_story_5037_50370601_106_dialog_content = "Você deve ir para o local agora, porque o show vai começar em breve.",
  ui_story_5037_50370601_107_dialog_content = "Autógrafos e fotos depois do show?",
  ui_story_5037_50370601_108_dialog_content = "Vou primeiro ao concerto, então!",
  ui_story_5037_50370601_109_dialog_content = "Pressa! Aposto que os que chegarem primeiro serão os primeiros na fila para os autógrafos!",
  ui_story_5037_50370601_110_dialog_content = "Não precisa correr. Todos terão uma chance!",
  ui_story_5037_50370601_111_dialog_content = "Eles fugiram tão rápido que acho que não pegaram nada do que eu disse.",
  ui_story_5037_50370601_112_dialog_content = "Há tantas pessoas desta vez, de todos os lugares!",
  ui_story_5037_50370601_113_dialog_content = "É um bom sinal para a futura turnê Astra de Goldie!",
  ui_story_5037_50370601_114_dialog_content = "O que há de errado, Goldie?",
  ui_story_5037_50370601_115_dialog_content = "De repente estou tão nervoso.",
  ui_story_5037_50370601_116_dialog_content = "Parece que estou subindo no palco pela primeira vez...",
  ui_story_5037_50370601_117_dialog_content = "Olhe para o público lá fora, Goldie.",
  ui_story_5037_50370601_118_dialog_content = "Eles vieram porque te amam!",
  ui_story_5037_50370601_119_dialog_content = "E você merece ser amado.",
  ui_story_5037_50370601_120_dialog_content = "PlayerName...",
  ui_story_5037_50370601_121_dialog_content = "Tem razão!",
  ui_story_5037_50370601_122_dialog_content = "Não sou a pessoa que costumava ser.",
  ui_story_5037_50370601_123_dialog_content = "Você apenas assiste!",
  ui_story_5037_50370601_124_dialog_content = "vou atuar...",
  ui_story_5037_50370601_125_dialog_content = "para o melhor de minhas habilidades!",
  ui_story_5037_50370701_1_dialog_content = "O concerto de formatura foi um sucesso.",
  ui_story_5037_50370701_2_dialog_content = "A iluminação e os adereços foram todos perfeitos, e o desempenho de Goldie também.",
  ui_story_5037_50370701_3_dialog_content = "Apresentamos tudo o que queríamos nos mínimos detalhes.",
  ui_story_5037_50370701_4_dialog_content = "A multidão gritou o nome de Goldie e ficou por um longo tempo.",
  ui_story_5037_50370701_5_dialog_content = "Não havia nada além de emoção e alegria em todo o palco.",
  ui_story_5037_50370701_6_dialog_content = "Mas então...",
  ui_story_5037_50370701_7_dialog_content = "por que de repente me sinto triste?",
  ui_story_5037_50370701_8_dialog_content = "Oh!",
  ui_story_5037_50370701_9_dialog_content = "Eu quase esqueci, Lady Sheol deveria anunciar os resultados finais agora mesmo!",
  ui_story_5037_50370701_10_dialog_content = "Estou atrasado!",
  ui_story_5037_50370701_11_dialog_content = "Aff... aff...",
  ui_story_5037_50370701_12_dialog_content = "Desculpe por estar atrasado!",
  ui_story_5037_50370701_13_dialog_content = "Mais tempo e eu acho que você decidiu desistir, Produtor PlayerName.",
  ui_story_5037_50370701_14_dialog_content = "Onde está Goldie? Como você veio sozinho?",
  ui_story_5037_50370701_15_dialog_content = "Goldie está amarrado, se misturando com os fãs.",
  ui_story_5037_50370701_16_dialog_content = "Hmph! Meu mestre está sendo invadido por fãs querendo fotos também!",
  ui_story_5037_50370701_17_dialog_content = "Meus queridos ídolos com certeza são populares.",
  ui_story_5037_50370701_18_dialog_content = "Isso é bom. Um sinal muito bom!",
  ui_story_5037_50370701_19_dialog_content = "Adoraria esperar que terminassem para poder parabenizá-los pessoalmente.",
  ui_story_5037_50370701_20_dialog_content = "Mas tenho um encontro marcado com um executivo de estúdio de cinema mais tarde.",
  ui_story_5037_50370701_21_dialog_content = "Você parece mais ocupado do que nós.",
  ui_story_5037_50370701_22_dialog_content = "Está tudo bem, conte-nos o resultado, Lady Sheol.",
  ui_story_5037_50370701_23_dialog_content = "Você mal pode esperar, não é, Fia?",
  ui_story_5037_50370701_24_dialog_content = "Mas isso não é uma coisa ruim. Ficou evidente no show de Vic...",
  ui_story_5037_50370701_25_dialog_content = "que você aprendeu a planejar um show em um período de tempo muito curto.",
  ui_story_5037_50370701_26_dialog_content = "O concerto de formatura de Vic mostrou melhorias significativas na apresentação.",
  ui_story_5037_50370701_27_dialog_content = "Claro que me esforcei muito!",
  ui_story_5037_50370701_28_dialog_content = "Quanto a Goldie, seu show já era quase insuperável.",
  ui_story_5037_50370701_29_dialog_content = "Mas PlayerName ainda conseguiu inserir surpresas no palco para o público curtir.",
  ui_story_5037_50370701_30_dialog_content = "Juntamente com as novas canções de Goldie, foi tocante e comovente.",
  ui_story_5037_50370701_31_dialog_content = "O que? Achei que só eu receberia todos os elogios.",
  ui_story_5037_50370701_32_dialog_content = "Agora, quanto aos resultados, Team Fia—",
  ui_story_5037_50370701_33_dialog_content = "O quê o quê o quê?",
  ui_story_5037_50370701_34_dialog_content = "Eu venci?!",
  ui_story_5037_50370701_35_dialog_content = "Deixe-me terminar, querida.",
  ui_story_5037_50370701_36_dialog_content = "Infelizmente, o Team Fia perdeu para o Team PlayerName por uma margem muito estreita.",
  ui_story_5037_50370701_37_dialog_content = "Eles ganharam por apenas 10 bilhetes.",
  ui_story_5037_50370701_38_dialog_content = "Hã?",
  ui_story_5037_50370701_39_dialog_content = "Depois de somar os resultados dos três concertos, a vitória vai para...",
  ui_story_5037_50370701_40_dialog_content = "<size=45>PlayerName e Goldie!</size>",
  ui_story_5037_50370701_41_dialog_content = "...",
  ui_story_5037_50370701_42_dialog_content = "Uau...!",
  ui_story_5037_50370701_43_dialog_content = "Eu w-trabalhei tanto...",
  ui_story_5037_50370701_44_dialog_content = "Passei tanto tempo mantendo meu mestre indisciplinado na coleira, mas também tive que ficar acordado a noite toda aprendendo a encenar um show...",
  ui_story_5037_50370701_45_dialog_content = "Fia, você vai perder meu próximo anúncio se não se acalmar.",
  ui_story_5037_50370701_46_dialog_content = "O quê?",
  ui_story_5037_50370701_47_dialog_content = "Fia e Vic conseguiram angariar muitos fãs durante esse período por meio de seus esforços e contribuíram para muitas vendas de mercadorias da Cloudrover Guild.",
  ui_story_5037_50370701_48_dialog_content = "Diante do seu excelente desempenho...",
  ui_story_5037_50370701_49_dialog_content = "Você também receberá um bônus!",
  ui_story_5037_50370701_50_dialog_content = "Um bônus...",
  ui_story_5037_50370701_51_dialog_content = "Prêmio em dinheiro?!",
  ui_story_5037_50370701_52_dialog_content = "Eu sabia. Mestre e eu não sofremos à toa! O trabalho duro pode realmente levar a bons resultados! *Soluço*",
  ui_story_5037_50370701_53_dialog_content = "Aham, tem mais!",
  ui_story_5037_50370701_54_dialog_content = "O vencedor do Hardest Working Idol em nosso reality show é...",
  ui_story_5037_50370701_55_dialog_content = "Vic!",
  ui_story_5037_50370701_56_dialog_content = "Mestre? Mestre ganhou alguma coisa?",
  ui_story_5037_50370701_57_dialog_content = "E o ídolo mais trabalhador de todas as coisas?",
  ui_story_5037_50370701_58_dialog_content = "Mestre venceu Goldie e recebeu o apoio de todos!",
  ui_story_5037_50370701_59_dialog_content = "Estou tão orgulhoso do meu mestre!",
  ui_story_5037_50370701_60_dialog_content = "Hehe, isso também é um aceno para Kyllo e meus esforços!",
  ui_story_5037_50370701_61_dialog_content = "Lo!",
  ui_story_5037_50370701_62_dialog_content = "Perdoe-nos, PlayerName, mas esse é nosso!",
  ui_story_5037_50370701_63_dialog_content = "Vic trabalhou muito, de fato, então sinto que ele merece.",
  ui_story_5037_50370701_64_dialog_content = "A seguir, o Melhor Produtor vai para...",
  ui_story_5037_50370701_65_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_66_dialog_content = "O quê?",
  ui_story_5037_50370701_67_dialog_content = "Eu, melhor produtor?",
  ui_story_5037_50370701_68_dialog_content = "...!",
  ui_story_5037_50370701_69_dialog_content = "Hmph, tudo bem.",
  ui_story_5037_50370701_70_dialog_content = "eu admito PlayerName dominou as habilidades de um produtor mais rápido e melhor do que eu.",
  ui_story_5037_50370701_71_dialog_content = "Mas ele também é mais velho do que eu!",
  ui_story_5037_50370701_72_dialog_content = "Espere até eu ter a idade dele. Eu vou ser mais incrível com certeza!",
  ui_story_5037_50370701_73_dialog_content = "Fia?",
  ui_story_5037_50370701_74_dialog_content = "Ela simplesmente saiu assim.",
  ui_story_5037_50370701_75_dialog_content = "Está tudo bem, ela provavelmente está voltando para seu mestre.",
  ui_story_5037_50370701_76_dialog_content = "Ela pode ter uma língua afiada, mas seu coração está no lugar certo.",
  ui_story_5037_50370701_77_dialog_content = "Como você tem essa visão da Fia?",
  ui_story_5037_50370701_78_dialog_content = "Embora eu não seja um celestita e não tenha habilidades psíquicas...",
  ui_story_5037_50370701_79_dialog_content = "Eu sou mais perspicaz com as pessoas do que você.",
  ui_story_5037_50370701_80_dialog_content = "De que outra forma você acha que comecei do zero e construí o Cloudrover Guild até onde está agora?",
  ui_story_5037_50370701_81_dialog_content = "...",
  ui_story_5037_50370701_82_dialog_content = "Lilica.",
  ui_story_5037_50370701_83_dialog_content = "Estou aqui, Senhora Sheol!",
  ui_story_5037_50370701_84_dialog_content = "Eu amo todas as filmagens B-roll que você fez para o show.",
  ui_story_5037_50370701_85_dialog_content = "Com a edição adequada, será um reality show de qualidade.",
  ui_story_5037_50370701_86_dialog_content = "Até então, muitas novas oportunidades de direção estarão esperando por você.",
  ui_story_5037_50370701_87_dialog_content = "Eu vou ter certeza de editar o melhor show de todos!",
  ui_story_5037_50370701_88_dialog_content = "E, por favor, sinta-se à vontade para me pedir qualquer coisa no futuro, Lady Sheol!",
  ui_story_5037_50370701_89_dialog_content = "Claro. Espero que histórias interessantes surjam depois do show também.",
  ui_story_5037_50370701_90_dialog_content = "Fique de olho neles para não perder nada.",
  ui_story_5037_50370701_91_dialog_content = "Beleza!",
  ui_story_5037_50370701_92_dialog_content = "Deixa comigo!",
  ui_story_5037_50370701_93_dialog_content = "Você é bem-vindo para ficar e ser um produtor, PlayerName.",
  ui_story_5037_50370701_94_dialog_content = "Apenas lembre-se de enviar seu currículo para o meu escritório.",
  ui_story_5037_50370701_95_dialog_content = "Beleza!",
  ui_story_5037_50370701_96_dialog_content = "E estou sem tempo. Eu tenho que ir lidar com assuntos de negócios agora.",
  ui_story_5037_50370701_97_dialog_content = "Aguardo boas notícias de todos vocês!",
  ui_story_5037_50370701_98_dialog_content = "Tchau, Senhora Sheol!",
  ui_story_5037_50370701_99_dialog_content = "Hmm, este é o fim da minha carreira de produtor?",
  ui_story_5037_50370701_100_dialog_content = "...",
  ui_story_5037_50370701_101_dialog_content = "Mas que... O que você está fazendo com essa câmera na minha cara, Lilica?",
  ui_story_5037_50370701_102_dialog_content = "O reality show ainda não acabou.",
  ui_story_5037_50370701_103_dialog_content = "Eu tenho que continuar trabalhando.",
  ui_story_5037_50370701_104_dialog_content = "Mas o concerto acabou, e não há mais nada a fazer...",
  ui_story_5037_50370701_105_dialog_content = "O que mais há para você filmar?",
  ui_story_5037_50370701_106_dialog_content = "Você com certeza.",
  ui_story_5037_50370701_107_dialog_content = "Melhor Produtor!",
  ui_story_5037_50370701_108_dialog_content = "Uh, há algo que eu preciso fazer?",
  ui_story_5037_50370701_109_dialog_content = "Pergunte a si mesmo.",
  ui_story_5037_50370701_110_dialog_content = "Pergunto a mim mesmo?",
  ui_story_5037_50370701_111_dialog_content = "Pois é, por exemplo... quem você mais quer ver no momento?",
  ui_story_5037_50370701_112_dialog_content = "Quem eu quero ver?",
  ui_story_5037_50370701_113_dialog_content = "Isso mesmo, o dia ainda não acabou!",
  ui_story_5037_50370701_114_dialog_content = "gostaria de ir ver...",
  ui_story_5037_50370701_115_option_content = "Goldie",
  ui_story_5037_50370701_116_dialog_content = "Tenho que ir dizer a ela que ganhamos!",
  ui_story_5037_50370701_117_option_content = "Vic e Fia",
  ui_story_5037_50370701_118_dialog_content = "Eu tenho que ir parabenizar Vic!",
  ui_story_5037_50370701_119_option_content = "Vice e Carleen",
  ui_story_5037_50370701_120_dialog_content = "Quero agradecer a ambos...",
  ui_story_5037_50370701_121_dialog_content = "Quero dizer a Goldie que vencemos o mais rápido possível!",
  ui_story_5037_50370701_122_dialog_content = "Então eu vou dizer a ela o que eu queria dizer a ela...",
  ui_story_5037_50370701_123_dialog_content = "Segure!",
  ui_story_5037_50370701_124_dialog_content = "Mas eu já disse essas coisas!",
  ui_story_5037_50370701_125_dialog_content = "Acho que devo falar sobre o prêmio em dinheiro?",
  ui_story_5037_50370701_126_dialog_content = "\"Goldie, com esse dinheiro você vai poder comprar mais vestidos!\"",
  ui_story_5037_50370701_127_dialog_content = "Isso soa estranho...",
  ui_story_5037_50370701_128_dialog_content = "\"Ganhamos o dinheiro graças a você, Goldie!\"",
  ui_story_5037_50370701_129_dialog_content = "Não, isso me faz parecer que estou puxando o saco dela.",
  ui_story_5037_50370701_130_dialog_content = "\"Bom trabalho, Goldie!\"",
  ui_story_5037_50370701_131_dialog_content = "Isso soa como um eufemismo demais...",
  ui_story_5037_50370701_132_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370701_133_dialog_content = "Obrigado a todos pelo apoio!",
  ui_story_5037_50370701_134_dialog_content = "Por favor, alinhe um de cada vez, não tropece!",
  ui_story_5037_50370701_135_dialog_content = "O show acabou há muito tempo, mas ela ainda tem tantos fãs ao seu redor!",
  ui_story_5037_50370701_136_dialog_content = "Ela parece estar se divertindo com eles.",
  ui_story_5037_50370701_137_dialog_content = "Eu não deveria me intrometer.",
  ui_story_5037_50370701_138_dialog_content = "Posso usar esse tempo para descobrir o que vou dizer a ela mais tarde!",
  ui_story_5037_50370701_139_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_140_dialog_content = "Aquele Goldie estava chamando por mim?",
  ui_story_5037_50370701_141_dialog_content = "<size=50>PlayerName, venha aqui rápido!</size>",
  ui_story_5037_50370701_142_dialog_content = "Ela quer que eu fale com os fãs também?",
  ui_story_5037_50370701_143_dialog_content = "Acho que não devo ir. Eles são todos fãs dela e não estariam interessados em mim.",
  ui_story_5037_50370701_144_dialog_content = "Por favor me dê um minuto, eu já volto!",
  ui_story_5037_50370701_145_dialog_content = "Onde quer que Goldie vá, os Goldilocks seguem!",
  ui_story_5037_50370701_146_dialog_content = "Espere...",
  ui_story_5037_50370701_147_dialog_content = "Por que ela está vindo para cá?",
  ui_story_5037_50370701_148_dialog_content = "O que você está fazendo parado aqui, produtor?",
  ui_story_5037_50370701_149_dialog_content = "Ah, eu só vim te dizer...",
  ui_story_5037_50370701_150_dialog_content = "Vencemos!",
  ui_story_5037_50370701_151_dialog_content = "Já era hora de você descobrir, PlayerName.",
  ui_story_5037_50370701_152_dialog_content = "Você já sabia?",
  ui_story_5037_50370701_153_dialog_content = "Sim, logo depois que terminei a última música.",
  ui_story_5037_50370701_154_dialog_content = "Fizemos o nosso melhor em todas as apresentações e não deixamos nenhum arrependimento no palco.",
  ui_story_5037_50370701_155_dialog_content = "Já vencemos quando conquistamos a nós mesmos.",
  ui_story_5037_50370701_156_dialog_content = "Então é assim que você vê isso.",
  ui_story_5037_50370701_157_dialog_content = "Muitos fãs elogiaram os designs dos palcos. Por que você não vai se misturar com eles?",
  ui_story_5037_50370701_158_dialog_content = "Bem, eu...",
  ui_story_5037_50370701_159_dialog_content = "Não é educado que ídolos ou produtores de ídolos deixem os fãs esperando!",
  ui_story_5037_50370701_160_dialog_content = "Desculpe fazê-los esperar, meus queridos Cachinhos Dourados!",
  ui_story_5037_50370701_161_dialog_content = "Eu gostaria de apresentar alguém a todos vocês.",
  ui_story_5037_50370701_162_dialog_content = "Por favor, rufem os tambores!",
  ui_story_5037_50370701_163_dialog_content = "O-Oi, pessoal!",
  ui_story_5037_50370701_164_dialog_content = "Isso mesmo, a pessoa tímida ao meu lado é o lendário Caelestite, PlayerName!",
  ui_story_5037_50370701_165_dialog_content = "Também, PlayerName é o produtor que tem me ajudado todo esse tempo!",
  ui_story_5037_50370701_166_dialog_content = "Os shows foram tão bem graças a ele!",
  ui_story_5037_50370701_167_dialog_content = "Fico lisonjeado. Na verdade, sou muito novo no papel.",
  ui_story_5037_50370701_168_dialog_content = "O produtor de Goldie era um noob? Eu não teria adivinhado.",
  ui_story_5037_50370701_169_dialog_content = "Você sabe o que dizem, nunca julgue um livro pela capa!",
  ui_story_5037_50370701_170_dialog_content = "eu me chamaria de obstinado Goldie fã que está lá desde o primeiro dia.",
  ui_story_5037_50370701_171_dialog_content = "Goldie já era excelente em todos os aspectos, mas conseguir um produtor...",
  ui_story_5037_50370701_172_dialog_content = "realmente a ajudou a melhorar muito e a encontrar seu próprio estilo!",
  ui_story_5037_50370701_173_dialog_content = "Não entendo todo esse jargão.",
  ui_story_5037_50370701_174_dialog_content = "Tudo o que sei é que nunca estive em um show tão agradável e delicioso!",
  ui_story_5037_50370701_175_dialog_content = "É tudo graças ao produtor PlayerName!",
  ui_story_5037_50370701_176_dialog_content = "Produtor PlayerName! Produtor PlayerName! Produtor PlayerName!",
  ui_story_5037_50370701_177_dialog_content = "...",
  ui_story_5037_50370701_178_dialog_content = "(É meio embaraçoso ouvir tantas pessoas chamarem meu nome...)",
  ui_story_5037_50370701_179_dialog_content = "(Tudo o que fiz foram algumas coisas nos bastidores. Isso merece algum aplauso?)",
  ui_story_5037_50370701_180_dialog_content = "Produtor PlayerName...",
  ui_story_5037_50370701_181_dialog_content = "Claro que você merece os aplausos.",
  ui_story_5037_50370701_182_dialog_content = "Você trabalhou tão duro ultimamente!",
  ui_story_5037_50370701_183_dialog_content = "(Como Goldie sabia o que eu estava pensando?)",
  ui_story_5037_50370701_184_dialog_content = "(E ela ainda roubou minha linha!)",
  ui_story_5037_50370701_185_dialog_content = "Acho que todo mundo quer falar com você, PlayerName!",
  ui_story_5037_50370701_186_dialog_content = "Hã?",
  ui_story_5037_50370701_187_dialog_content = "Autógrafos, por favor, Produtor!",
  ui_story_5037_50370701_188_dialog_content = "Não sou um Lovegator, mas também quero o autógrafo do PlayerName!",
  ui_story_5037_50370701_189_dialog_content = "Eu também!",
  ui_story_5037_50370701_190_dialog_content = "E eu!",
  ui_story_5037_50370701_191_dialog_content = "O que está acontecendo...?!",
  ui_story_5037_50370701_192_dialog_content = "Eu teria praticado minha assinatura se soubesse que isso iria acontecer...",
  ui_story_5037_50370701_193_dialog_content = "Uau!",
  ui_story_5037_50370701_194_dialog_content = "Nunca contei tantos Nightium antes!",
  ui_story_5037_50370701_195_dialog_content = "Então é assim que se sente ser rico?",
  ui_story_5037_50370701_196_dialog_content = "Lady Sheol é muito generosa!",
  ui_story_5037_50370701_197_dialog_content = "Com quem você está falando, Fia?",
  ui_story_5037_50370701_198_dialog_content = "Não vejo mais ninguém por perto.",
  ui_story_5037_50370701_199_dialog_content = "Com quem mais eu poderia estar falando além do meu mestre?",
  ui_story_5037_50370701_200_dialog_content = "Seu mestre?",
  ui_story_5037_50370701_201_dialog_content = "O que... eu nem teria notado se você não tivesse falado sobre ele...",
  ui_story_5037_50370701_202_dialog_content = "Aquele meu mestre preguiçoso cochilou debaixo da mesa de novo!",
  ui_story_5037_50370701_203_dialog_content = "Arraste o Mestre agora, Kyllo!",
  ui_story_5037_50370701_204_dialog_content = "Lo!",
  ui_story_5037_50370701_205_dialog_content = "Hã?",
  ui_story_5037_50370701_206_dialog_content = "De qualquer forma, de onde você veio, PlayerName?",
  ui_story_5037_50370701_207_dialog_content = "Bem, a porta estava aberta, então entrei.",
  ui_story_5037_50370701_208_dialog_content = "O que?! Como pude esquecer de fechar a porta antes de contar o dinheiro?!",
  ui_story_5037_50370701_209_dialog_content = "Eu-Está bem, Fia. Eu fecho para você.",
  ui_story_5037_50370701_210_dialog_content = "Mas e se um ladrão entrar escondido?!",
  ui_story_5037_50370701_211_dialog_content = "Ugh, não, eu tenho que contar todo o Nightium novamente!",
  ui_story_5037_50370701_212_dialog_content = "Lo-lo!",
  ui_story_5037_50370701_213_dialog_content = "Nnng... Chega de treino, por favor...",
  ui_story_5037_50370701_214_dialog_content = "Vic?",
  ui_story_5037_50370701_215_dialog_content = "Vamos correr, Bola de Pelos! Ruuuun!",
  ui_story_5037_50370701_216_dialog_content = "Ele está... falando durante o sono?",
  ui_story_5037_50370701_217_dialog_content = "Oitenta e três, oitenta e quatro, oitenta e cinco...",
  ui_story_5037_50370701_218_dialog_content = "Fia, não vai sobrar, não importa quantas vezes você conte.",
  ui_story_5037_50370701_219_dialog_content = "Além disso, você não acha que deveria verificar o seu mestre? Basta olhar para ele.",
  ui_story_5037_50370701_220_dialog_content = "Kyllo o arrastou para fora da mesa, mas ele ainda não acordou!",
  ui_story_5037_50370701_221_dialog_content = "Só um segundo! Eu vou chegar até você assim que eu contar até cem...",
  ui_story_5037_50370701_222_dialog_content = "Noventa e oito, noventa e nove... Cem!",
  ui_story_5037_50370701_223_dialog_content = "Tudo bem, agora, o que você estava dizendo agora?",
  ui_story_5037_50370701_224_dialog_content = "Uh, talvez você devesse verificar seu mestre.",
  ui_story_5037_50370701_225_dialog_content = "Ele está completamente indiferente.",
  ui_story_5037_50370701_226_dialog_content = "Oh, ele está apenas tirando uma de suas sonecas, só isso.",
  ui_story_5037_50370701_227_dialog_content = "Os últimos dias realmente mexeram com ele...",
  ui_story_5037_50370701_228_dialog_content = "Embora eu ache que isso é bastante normal para alguém que nunca trabalhou um dia na vida!",
  ui_story_5037_50370701_229_dialog_content = "Ruuuuuuuun!!!",
  ui_story_5037_50370701_230_dialog_content = "Ei, Vick? Você está acordado agora?",
  ui_story_5037_50370701_231_dialog_content = "PlayerName? O que você está fazendo aqui?!",
  ui_story_5037_50370701_232_dialog_content = "C-corram! Kyllo entrou em frenesi! Fica me obrigando a treinar!",
  ui_story_5037_50370701_233_dialog_content = "Uh, você tem certeza que não estava apenas sonhando?",
  ui_story_5037_50370701_234_dialog_content = "Ha? Uh, Fia está aqui também...?",
  ui_story_5037_50370701_235_dialog_content = "Espere, de onde veio todo aquele Nightium?!",
  ui_story_5037_50370701_236_dialog_content = "Com certeza estou sonhando agora!",
  ui_story_5037_50370701_237_dialog_content = "Embora eu deva dizer, este sonho parece muito melhor do que o último.",
  ui_story_5037_50370701_238_dialog_content = "Ué, Fia? Como convencemos Vic de que ele não está sonhando?",
  ui_story_5037_50370701_239_dialog_content = "Heheheh. Parece que é hora de Kyllo voltar a brilhar! Pegue-o!",
  ui_story_5037_50370701_240_dialog_content = "!!!",
  ui_story_5037_50370701_241_dialog_content = "N-Agora espere um segundo, Fia! Seu mestre está bem acordado agora, eu juro!",
  ui_story_5037_50370701_242_dialog_content = "Pobre Vic. Imagine ter tanto medo de Kyllo.",
  ui_story_5037_50370701_243_dialog_content = "Hmm, parece que este Nightium é o verdadeiro negócio.",
  ui_story_5037_50370701_244_dialog_content = "Lady Sheol realmente é uma pessoa generosa, hein?",
  ui_story_5037_50370701_245_dialog_content = "Tudo o que fizemos foi participar de seu reality show por alguns dias, e ela nos pagou tanto Nightium em troca...",
  ui_story_5037_50370701_246_dialog_content = "Eu me pergunto quanto ganha um ídolo de verdade?",
  ui_story_5037_50370701_247_dialog_content = "Por que você se importa com quanto as outras pessoas ganham, Fia? Devemos nos contentar com o que já temos, não acha?",
  ui_story_5037_50370701_248_dialog_content = "Suspiro... Acho que você está certo.",
  ui_story_5037_50370701_249_dialog_content = "É raro você ouvir você dizer algo sério pela primeira vez...",
  ui_story_5037_50370701_250_dialog_content = "Bobagem, eu sou sempre assim! Agora, com licença, há uma mesa em um novo bufê Umbraton com meu nome!",
  ui_story_5037_50370701_251_dialog_content = "... Nos seus sonhos!",
  ui_story_5037_50370701_252_dialog_content = "O que? Por que não?!",
  ui_story_5037_50370701_253_dialog_content = "Nos últimos dias, não fiz nada além de ouvir suas exigências ridículas!",
  ui_story_5037_50370701_254_dialog_content = "Se não estou treinando, estou cuidando do meu peso. Nem me lembro da última vez que fiz uma refeição decente!",
  ui_story_5037_50370701_255_dialog_content = "Não ganhamos esse tipo de dinheiro diariamente, sabe? Devemos nos tratar quando temos a chance!",
  ui_story_5037_50370701_256_dialog_content = "Parece que você ainda não entendeu muito bem nossa situação, mestre.",
  ui_story_5037_50370701_257_dialog_content = "Isso pode parecer muito dinheiro à primeira vista.",
  ui_story_5037_50370701_258_dialog_content = "Mas uma vez que você considera seus lanches Drakolion, nossas despesas habituais com comida, reparos na casa e meu salário de trabalho...",
  ui_story_5037_50370701_259_dialog_content = "Isso gasta mais da metade do dinheiro!",
  ui_story_5037_50370701_260_dialog_content = "E quando consideramos o quão pouco confiável você será como fonte de renda...",
  ui_story_5037_50370701_261_dialog_content = "Não faço ideia de quanto tempo esse dinheiro vai durar para nós!",
  ui_story_5037_50370701_262_dialog_content = "Espere, o que você quer dizer com a renda dele?",
  ui_story_5037_50370701_263_dialog_content = "Vic tem tanto potencial como ídolo! Por que ele não continuaria fazendo isso?",
  ui_story_5037_50370701_264_dialog_content = "Me poupe, PlayerName.",
  ui_story_5037_50370701_265_dialog_content = "Para mim, ter durado tantos dias foi nada menos que um milagre, e você quer que eu faça isso pelo resto da minha vida?",
  ui_story_5037_50370701_266_dialog_content = "Só de pensar nisso me dá pesadelos.",
  ui_story_5037_50370701_267_dialog_content = "PlayerName está absolutamente certo, Mestre!",
  ui_story_5037_50370701_268_dialog_content = "Você passa o tempo todo em casa em vez de procurar trabalho, e nem cuida bem das feras maravilhosas...",
  ui_story_5037_50370701_269_dialog_content = "Você também pode usar a si mesmo como um ídolo.",
  ui_story_5037_50370701_270_dialog_content = "E quem sabe? Assim que o reality show for ao ar, você poderá ter ainda mais fãs do que antes, Mestre!",
  ui_story_5037_50370701_271_dialog_content = "Oh, minha querida, pequena Fia...",
  ui_story_5037_50370701_272_dialog_content = "Dê uma folga ao seu mestre, sim?!",
  ui_story_5037_50370701_273_dialog_content = "Não! Você vai ser um grande ídolo de sucesso e vai gostar!",
  ui_story_5037_50370701_274_dialog_content = "Wha-?!",
  ui_story_5037_50370701_275_dialog_content = "Oh, olha, ainda temos tempo suficiente para encaixar mais alguns treinos! Vamos, Mestre!",
  ui_story_5037_50370701_276_dialog_content = "M-Mas eu não quero continuar treinando... estou totalmente exausto...",
  ui_story_5037_50370701_277_dialog_content = "Ah, Kyllo? Acho que nosso mestre precisa de um pouco de motivação.",
  ui_story_5037_50370701_278_dialog_content = "Nããão—!",
  ui_story_5037_50370701_279_dialog_content = "Suspiro... Nunca vi o Mestre correr tão rápido na minha vida.",
  ui_story_5037_50370701_280_dialog_content = "Tanto para estar \"totalmente exausto\", hein? Ei! Se você tiver energia suficiente para fugir, ainda terá energia suficiente para treinar!",
  ui_story_5037_50370701_281_dialog_content = "Vic...",
  ui_story_5037_50370701_282_dialog_content = "Mantenha-se firme!",
  ui_story_5037_50370701_283_dialog_content = "\"Melhor Produtor\", hein...?",
  ui_story_5037_50370701_284_dialog_content = "Heehee... Eu sei que não devo deixar o prêmio de Lady Sheol subir à minha cabeça.",
  ui_story_5037_50370701_285_dialog_content = "Pensando no dia em que cheguei à Agência Starlit, eu realmente não tinha ideia do que estava fazendo. Eu me preocupava em tornar a vida de Goldie mais difícil do que já era.",
  ui_story_5037_50370701_286_dialog_content = "Mas consegui ajudar Goldie com todos os seus três shows e até consegui que Lady Sheol me reconhecesse!",
  ui_story_5037_50370701_287_dialog_content = "Cara, mal posso esperar para surpreender Vice e Carleen com isso.",
  ui_story_5037_50370701_288_dialog_content = "Eles devem estar em algum lugar próximo, certo?",
  ui_story_5037_50370701_289_dialog_content = "Eu me pergunto se eles estão nesta sala?",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>TOC Toc!</color>",
  ui_story_5037_50370701_291_dialog_content = "Perdoe a intromissão!",
  ui_story_5037_50370701_292_dialog_content = "Engraçado... As luzes desta sala geralmente estão acesas. Por que está tão escuro aqui hoje?",
  ui_story_5037_50370701_293_dialog_content = "Vício? Carleen? Huh, acho que eles não estão aqui depois de tudo.",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>Bater!</color>",
  ui_story_5037_50370701_295_dialog_content = "Hã?!",
  ui_story_5037_50370701_296_dialog_content = "Surpresa!!!",
  ui_story_5037_50370701_297_dialog_content = "Parabéns por hospedar um concerto de formatura perfeito!",
  ui_story_5037_50370701_298_dialog_content = "E parabéns por completar suas missões, PlayerName.",
  ui_story_5037_50370701_299_dialog_content = "O-O que é tudo isso...?",
  ui_story_5037_50370701_300_dialog_content = "Uma seleção das melhores comidas e bebidas de um novo bufê sofisticado aberto recentemente em Umbraton.",
  ui_story_5037_50370701_301_dialog_content = "E também - este bolo enorme! Parece gostoso, né?",
  ui_story_5037_50370701_302_dialog_content = "Desde que você começou a treinar para ser produtor, você não tem se alimentado bem.",
  ui_story_5037_50370701_303_dialog_content = "Entããão... Decidimos fazer uma festinha comemorativa só para você, PlayerName! Ver? Tem todos os seus favoritos!",
  ui_story_5037_50370701_304_dialog_content = "Vice, Carleen...",
  ui_story_5037_50370701_305_dialog_content = "Há quanto tempo vocês dois estão planejando isso?",
  ui_story_5037_50370701_306_dialog_content = "Eu não fazia ideia!",
  ui_story_5037_50370701_307_dialog_content = "Heehee! Na verdade, tivemos a ideia há algum tempo.",
  ui_story_5037_50370701_308_dialog_content = "E com o quão ocupado você esteve hoje, tivemos muito tempo para nos preparar.",
  ui_story_5037_50370701_309_dialog_content = "Isso significa que vocês dois sabem os resultados do show de hoje?",
  ui_story_5037_50370701_310_dialog_content = "Não! Esperávamos que você nos contasse.",
  ui_story_5037_50370701_311_dialog_content = "Er... O que você faria se perdêssemos? Ainda teríamos motivos para comemorar?",
  ui_story_5037_50370701_312_dialog_content = "Vice e eu já concordei que não importa quais fossem os resultados hoje,",
  ui_story_5037_50370701_313_dialog_content = "todo o seu trabalho árduo é motivo suficiente para comemorar.",
  ui_story_5037_50370701_314_dialog_content = "Você não apenas estudou seu coração, PlayerName. Você ficou com ele até o fim! Isso é uma grande conquista aos meus olhos!",
  ui_story_5037_50370701_315_dialog_content = "É por isso que vamos festejar, não importa o quê!",
  ui_story_5037_50370701_316_dialog_content = "V-Vocês... Arrrgh, por que vocês têm que ser tão legais?!",
  ui_story_5037_50370701_317_dialog_content = "Ver? Agora eu tenho algo no meu olho, graças a você!",
  ui_story_5037_50370701_318_dialog_content = "De qualquer forma, quem ganhou hoje?",
  ui_story_5037_50370701_319_dialog_content = "Eu pensei que você disse que não importava?!",
  ui_story_5037_50370701_320_dialog_content = "Hahaha! Isso porque confiamos em você, PlayerName!",
  ui_story_5037_50370701_321_dialog_content = "Além disso, você estava murmurando algo sobre algo que queria nos dizer quando estava lá fora. Então o que é?",
  ui_story_5037_50370701_322_dialog_content = "Heheheh. Adivinha? Goldie e ganhei hoje!",
  ui_story_5037_50370701_323_dialog_content = "E não só isso, Lady Sheol me deu o prêmio de Melhor Produtor!",
  ui_story_5037_50370701_324_dialog_content = "Uau! Eu não fazia ideia que eles ainda tinham um prêmio por isso!",
  ui_story_5037_50370701_325_dialog_content = "Parece que Lady Sheol tem um olhar perspicaz. Eu não acho que seu progresso incrível foi perdido para ela, PlayerName.",
  ui_story_5037_50370701_326_dialog_content = "Então, o prêmio veio com algum prêmio em dinheiro? Huh? Huh?!",
  ui_story_5037_50370701_327_dialog_content = "Eu, uh... Acho que não.",
  ui_story_5037_50370701_328_dialog_content = "Heheheh, faz sentido. Afinal, nenhuma quantia em dinheiro se compara à honra de receber esse prêmio, certo?",
  ui_story_5037_50370701_329_dialog_content = "Acordado. Você deve ter muito mais facilidade em encontrar trabalho no futuro com ele.",
  ui_story_5037_50370701_330_dialog_content = "Isso mesmo! Você está basicamente no mesmo nível de qualquer outro produtor profissional agora!",
  ui_story_5037_50370701_331_dialog_content = "Mas se não fosse por vocês me ajudando o tempo todo, eu nunca teria tido confiança para chegar até aqui.",
  ui_story_5037_50370701_332_dialog_content = "Carleen, Vice, obrigado por estarem sempre ao meu lado e me ensinarem tanto nestes últimos dias.",
  ui_story_5037_50370701_333_dialog_content = "Não mencione isso! Há apenas uma pequena coisa errada com sua declaração, no entanto.",
  ui_story_5037_50370701_334_dialog_content = "Hã?",
  ui_story_5037_50370701_335_dialog_content = "Não estamos apenas ajudando você nos últimos dias, certo?",
  ui_story_5037_50370701_336_dialog_content = "Ela está certa. Estamos juntos esse tempo todo, não é?",
  ui_story_5037_50370701_337_dialog_content = "Sim, você tem razão.",
  ui_story_5037_50370701_338_dialog_content = "Deixe-me tentar de novo!",
  ui_story_5037_50370701_339_dialog_content = "Oh, apenas relaxe, sim? Somos todos amigos aqui, então não há necessidade de ser tão formal!",
  ui_story_5037_50370701_340_dialog_content = "Enfim, adivinhem?",
  ui_story_5037_50370701_341_dialog_content = "Em minha última viagem de volta a Illumina, notei que toda a região havia se interessado por ídolos!",
  ui_story_5037_50370701_342_dialog_content = "Acho que a oficial Vivian está planejando algum tipo de grande evento para escolher um grupo de ídolos para representar toda a Federação Illumina!",
  ui_story_5037_50370701_343_dialog_content = "O que? Ilumina ídolos?!",
  ui_story_5037_50370701_344_dialog_content = "Vamos rugir e animar o show!",
  ui_story_5037_50370701_345_dialog_content = "Hum? O que há com a multidão terrivelmente silenciosa?",
  ui_story_5037_50370701_346_dialog_content = "Vocês ficaram tão surpresos com minha performance espetacular que se esqueceram de bater palmas?",
  ui_story_5037_50370701_347_dialog_content = "Hahahahahahaha!",
  ui_story_5037_50370701_348_dialog_content = "*Inalar*",
  ui_story_5037_50370701_349_dialog_content = "Hum? Algo está errado, PlayerName? Você parece um pouco pálido.",
  ui_story_5037_50370701_350_dialog_content = "I-Não é nada!",
  ui_story_5037_50370701_351_dialog_content = "Tenho certeza que a busca pelo maior ídolo de Illumina será uma experiência inesquecível!",
  ui_story_5037_50370701_352_dialog_content = "Esses concursos de ídolos são realmente dignos de consideração séria. Talvez eu deva sugerir um evento semelhante para Lumopolis ao meu pai?",
  ui_story_5037_50370701_353_dialog_content = "Er, você acha que os nobres de Lumopolis concordariam com esse tipo de coisa?",
  ui_story_5037_50370701_354_dialog_content = "Desconfio que não será fácil.",
  ui_story_5037_50370701_355_dialog_content = "Mas não há como negar a riqueza de conhecimento que adquiri com essa experiência.",
  ui_story_5037_50370701_356_dialog_content = "Na verdade, acredito que finalmente vejo o verdadeiro valor de exibir o charme de alguém para o mundo ver.",
  ui_story_5037_50370701_357_dialog_content = "Curiosamente, parece que de repente um peso foi tirado dos meus ombros.",
  ui_story_5037_50370701_358_dialog_content = "Ah, saquei!",
  ui_story_5037_50370701_359_dialog_content = "Acho que você está um passo mais perto de sua jornada para suceder seu pai, Carleen!",
  ui_story_5037_50370701_360_dialog_content = "Você realmente acha que isso tem algo a ver com isso?",
  ui_story_5037_50370701_361_dialog_content = "Faz se você realmente pensar sobre isso.",
  ui_story_5037_50370701_362_dialog_content = "Como assim?",
  ui_story_5037_50370701_363_dialog_content = "A comida está começando a esfriar! Vamos cavar!",
  ui_story_5037_50370701_364_dialog_content = "Você está certo. Vamos comemorar nossa vitória enquanto a comida ainda está quentinha.",
  ui_story_5037_50370701_365_dialog_content = "Para PlayerName, o Melhor Produtor!",
  ui_story_5037_50370701_366_dialog_content = "Saúde!",
  ui_story_5037_50370701_367_option_content = "Saúde!",
  ui_story_5037_50370801_1_dialog_content = "Treino de coreografia, exercícios vocais, sessão de perguntas e respostas, contato com o dono do local para o fanmeeting...",
  ui_story_5037_50370801_2_dialog_content = "?",
  ui_story_5037_50370801_3_dialog_content = "Devo entrar em contato com o proprietário em algum momento entre o almoço e o jantar, mas o repórter estará aqui esta tarde...",
  ui_story_5037_50370801_4_dialog_content = "...",
  ui_story_5037_50370801_5_dialog_content = "Também preciso reservar tempo suficiente para Goldie descansar, bem como para se trocar e se maquiar. Com tudo isso acontecendo em um dia...",
  ui_story_5037_50370801_6_dialog_content = "...?",
  ui_story_5037_50370801_7_dialog_content = "Vou ter que passar o dia inteiro trabalhando de novo!",
  ui_story_5037_50370801_8_dialog_content = "PlayerName?",
  ui_story_5037_50370801_9_dialog_content = "Bwaaaa!!!",
  ui_story_5037_50370801_10_dialog_content = "Oh, é só você, Goldie. Meu coração quase pulou do meu peito agora.",
  ui_story_5037_50370801_11_dialog_content = "Posso perguntar sobre o que você está resmungando aqui?",
  ui_story_5037_50370801_12_dialog_content = "Na verdade, parece que você está com pouca energia. Quer praticar alguns movimentos de dança comigo para levantar o ânimo?",
  ui_story_5037_50370801_13_dialog_content = "Um pouco de exercício pode ajudar muito quando se trata de se manter saudável!",
  ui_story_5037_50370801_14_dialog_content = "Afinal, um produtor saudável é essencial para o sucesso de um ídolo! De que outra forma você vai acompanhar todos os meus shows e eventos?",
  ui_story_5037_50370801_15_dialog_content = "Sim, mas ainda estou planejando o cronograma...",
  ui_story_5037_50370801_16_dialog_content = "Há tanto para fazer todos os dias que assim que termino uma coisa já me atraso para a próxima...",
  ui_story_5037_50370801_17_dialog_content = "Até mesmo tentar encaixar alguns minutos de descanso é quase impossível agora!",
  ui_story_5037_50370801_18_dialog_content = "Acho que não sou um grande produtor, afinal...",
  ui_story_5037_50370801_19_dialog_content = "Sem chance! Você é um produtor fantástico!",
  ui_story_5037_50370801_20_dialog_content = "Você é um há apenas alguns dias, mas está completamente familiarizado com as exigências diárias do trabalho! Isso não é algo que qualquer um pode fazer, você sabe!",
  ui_story_5037_50370801_21_dialog_content = "Portanto, não seja muito duro consigo mesmo, ok? Aqui, quer acariciar o Marshmallow?",
  ui_story_5037_50370801_22_dialog_content = "Sempre me sinto melhor depois de acariciar seu pelo macio e fofo!",
  ui_story_5037_50370801_23_dialog_content = "Au!",
  ui_story_5037_50370801_24_dialog_content = "Claro, por que não-",
  ui_story_5037_50370801_25_dialog_content = "Espere!",
  ui_story_5037_50370801_26_dialog_content = "O que houve?",
  ui_story_5037_50370801_27_dialog_content = "Esqueci de ligar para o jornal sobre a entrevista de amanhã! Ainda não marquei hora para isso!",
  ui_story_5037_50370801_28_dialog_content = "Desculpe, Goldie! Eu tenho que ir embora!",
  ui_story_5037_50370801_29_dialog_content = "...",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>Um momento depois</color>",
  ui_story_5037_50370801_31_dialog_content = "Ufa... Graças a Deus cheguei a tempo.",
  ui_story_5037_50370801_32_dialog_content = "Eles são um dos maiores jornais ao redor. Se eu os tivesse deixado pendurados, teria prejudicado a reputação de Goldie.",
  ui_story_5037_50370801_33_dialog_content = "Bem vindo de volta, PlayerName!",
  ui_story_5037_50370801_34_dialog_content = "Oh Olá, Goldie! Desculpe, eu estava com tanta pressa que esqueci de me despedir...",
  ui_story_5037_50370801_35_dialog_content = "Tudo bem. Eu sei que é porque você tem estado muito ocupado com o trabalho ultimamente.",
  ui_story_5037_50370801_36_dialog_content = "Ser um produtor pode ser bem difícil. Mesmo que eu esteja me adaptando lentamente ao trabalho nos últimos dias,",
  ui_story_5037_50370801_37_dialog_content = "o trabalho ainda é muito exigente!",
  ui_story_5037_50370801_38_dialog_content = "Se tudo que eu tivesse que fazer fosse planejar horários, não seria nada difícil.",
  ui_story_5037_50370801_39_dialog_content = "Mas, além de todo o planejamento, tenho que lutar contra os paparazzi a todo momento e pensar nas coisas certas a dizer todas as vezes...",
  ui_story_5037_50370801_40_dialog_content = "É cansativo...",
  ui_story_5037_50370801_41_dialog_content = "Eu sei que é um trabalho difícil.",
  ui_story_5037_50370801_42_dialog_content = "Mas não importa o quão cansado você fique, você sempre encontra uma maneira de fazer o trabalho, PlayerName!",
  ui_story_5037_50370801_43_dialog_content = "Isso é o que eu acho tão incrível em você!",
  ui_story_5037_50370801_44_dialog_content = "Obrigado, Goldy! Só de ouvir você dizer isso me faz sentir muito menos exausta!",
  ui_story_5037_50370801_45_dialog_content = "Ver? Todo mundo precisa de encorajamento de vez em quando, não importa quem seja!",
  ui_story_5037_50370801_46_dialog_content = "Agora que você mencionou... Você lidou com tudo isso sozinha antes, Goldie?",
  ui_story_5037_50370801_47_dialog_content = "Não apenas ser um ídolo, mas ser seu próprio produtor também...",
  ui_story_5037_50370801_48_dialog_content = "Treinando, planejando, evitando os paparazzi...",
  ui_story_5037_50370801_49_option_content = "Você deve ser incrível por ter feito tudo isso sozinho!",
  ui_story_5037_50370801_50_dialog_content = "Haha... Não foi nada mesmo.",
  ui_story_5037_50370801_51_option_content = "Lidar com tudo sozinho deve ter sido difícil...",
  ui_story_5037_50370801_52_dialog_content = "Foi, mas consegui no final.",
  ui_story_5037_50370801_53_dialog_content = "Mesmo para alguém como eu, lidar com dois trabalhos completamente diferentes não era fácil.",
  ui_story_5037_50370801_54_dialog_content = "Eu encontrei todos os tipos de obstáculos no passado. Houve até momentos em que eu queria desistir e desistir.",
  ui_story_5037_50370801_55_dialog_content = "Você realmente sentiu vontade de desistir antes? Não consigo nem imaginar isso.",
  ui_story_5037_50370801_56_dialog_content = "É um dos meus maiores segredos, então não saia contando para outras pessoas!",
  ui_story_5037_50370801_57_dialog_content = "Eu não sonharia com isso! Como seu produtor, eu nunca diria ou faria qualquer coisa que prejudicasse você ou sua reputação!",
  ui_story_5037_50370801_58_dialog_content = "Heehee! Fico feliz em ouvir isso!",
  ui_story_5037_50370801_59_dialog_content = "Mas respondendo a sua pergunta... Sim, eu tive que lidar com todo o trabalho sozinho quando me tornei um ídolo.",
  ui_story_5037_50370801_60_dialog_content = "Treinando, planejando e evitando os paparazzi... tudo isso.",
  ui_story_5037_50370801_61_dialog_content = "Naquela época, eu dormia apenas uma ou duas horas todos os dias!",
  ui_story_5037_50370801_62_dialog_content = "Eu tinha que acordar cedo todas as manhãs apenas para compensar qualquer treino que perdi no dia anterior.",
  ui_story_5037_50370801_63_dialog_content = "Isso é insano!",
  ui_story_5037_50370801_64_dialog_content = "Estou acostumado a ficar acordado até tarde, mas apenas uma ou duas horas de sono? Eu nem conseguiria sair da cama no dia seguinte, muito menos fazer isso todos os dias...",
  ui_story_5037_50370801_65_dialog_content = "Isso era basicamente eu.",
  ui_story_5037_50370801_66_dialog_content = "Um ou dois dias é administrável para a maioria das pessoas, mas por vários anos? Para sempre?",
  ui_story_5037_50370801_67_dialog_content = "Toda vez que eu terminava meu treinamento, eu deitava na minha cama e minha mente exausta pensava em um futuro sem fim desse tipo de estilo de vida.",
  ui_story_5037_50370801_68_dialog_content = "Mas no final, você foi capaz de enfrentar os tempos difíceis e se tornar o ídolo famoso que você é hoje!",
  ui_story_5037_50370801_69_dialog_content = "Isso mesmo!",
  ui_story_5037_50370801_70_dialog_content = "Sempre que sinto vontade de desistir, jogo minha bala da sorte no ar. Se cair apontando para baixo, significa que algo bom vai acontecer!",
  ui_story_5037_50370801_71_dialog_content = "Naquela época, minha bala da sorte sempre apontava para baixo, então eu sabia que se eu continuasse... eu me tornaria o ídolo que sempre sonhei em me tornar!",
  ui_story_5037_50370801_72_dialog_content = "Você realmente tem um espírito indomável...",
  ui_story_5037_50370801_73_dialog_content = "Heehee!",
  ui_story_5037_50370801_74_dialog_content = "Mas as coisas são um pouco diferentes agora, sabe?",
  ui_story_5037_50370801_75_dialog_content = "Eu tenho você comigo. O melhor produtor que eu poderia pedir!",
  ui_story_5037_50370801_76_dialog_content = "Graças a você, posso focar no meu treino sem me preocupar com outras coisas!",
  ui_story_5037_50370801_77_dialog_content = "Meu progresso nunca foi tão rápido!",
  ui_story_5037_50370801_78_dialog_content = "Eu... realmente fui tão útil?",
  ui_story_5037_50370801_79_dialog_content = "Com certeza!",
  ui_story_5037_50370801_80_dialog_content = "Fico feliz em ouvir isso!",
  ui_story_5037_50370801_81_dialog_content = "Eu me sentia tão inútil antes... Como se eu só estivesse criando mais problemas para você.",
  ui_story_5037_50370801_82_dialog_content = "Mas ouvir você dizer isso me deixa muito mais confiante.",
  ui_story_5037_50370801_83_dialog_content = "Como seu produtor, continuarei fazendo o melhor por você, Goldie! Apenas deixe comigo!",
  ui_story_5037_50370801_84_dialog_content = "Eu vou te segurar nisso!",
  ui_story_5037_50370901_1_dialog_content = "<color=#828282>Depois do treino matinal</color>",
  ui_story_5037_50370901_2_dialog_content = "Obrigado novamente por sua ajuda, PlayerName!",
  ui_story_5037_50370901_3_dialog_content = "Terminei meu treinamento matinal, então agora tenho tempo para descansar um pouco.",
  ui_story_5037_50370901_4_dialog_content = "Não mencione isso, Goldie. Aproveite a sua pausa!",
  ui_story_5037_50370901_5_dialog_content = "<color=#828282>Toc, toc!</color>",
  ui_story_5037_50370901_6_dialog_content = "Entre!",
  ui_story_5037_50370901_7_dialog_content = "PlayerName! Ah, e Goldie também!",
  ui_story_5037_50370901_8_dialog_content = "Olá, Gronru!",
  ui_story_5037_50370901_9_dialog_content = "Gronru? O que você está fazendo aqui?",
  ui_story_5037_50370901_10_dialog_content = "Ah, só comprando alguns materiais, só isso. Ouvi dizer que você é um grande produtor em Umbraton agora, então pensei em parar e verificar as coisas!",
  ui_story_5037_50370901_11_dialog_content = "Eu também trouxe o último jogo que criei! O que você diz? Gostaria de jogar algumas rodadas?",
  ui_story_5037_50370901_12_dialog_content = "Claro que eu-",
  ui_story_5037_50370901_13_dialog_content = "Er, quero dizer... Não agora, desculpe.",
  ui_story_5037_50370901_14_dialog_content = "Huh? Você não quer me desafiar hoje? Eu tenho que dizer, isso não é nada típico de você...",
  ui_story_5037_50370901_15_dialog_content = "Porque ainda tenho muito trabalho a fazer esta tarde. É fácil para mim perder a noção do tempo quando jogo videogame...",
  ui_story_5037_50370901_16_dialog_content = "Você tem razão, sim... Bem, talvez da próxima vez! Não vou mais incomodar vocês.",
  ui_story_5037_50370901_17_dialog_content = "Mantenha o bom trabalho, PlayerName! Você também, Goldie!",
  ui_story_5037_50370901_18_dialog_content = "Estou ansioso pelo seu concerto!",
  ui_story_5037_50370901_19_dialog_content = "Obrigado! Espero ver você lá também!",
  ui_story_5037_50370901_20_dialog_content = "Tchau tchau!",
  ui_story_5037_50370901_21_dialog_content = "Até mais!",
  ui_story_5037_50370901_22_dialog_content = "Tudo bem, hora de se preparar para as tarefas desta tarde...",
  ui_story_5037_50370901_23_dialog_content = "Espere, é hora do intervalo agora, não é? É melhor descansar, para ter energia para fazer o resto do trabalho do dia.",
  ui_story_5037_50370901_24_dialog_content = "Eu sei, eu sei... Mas o show está chegando.",
  ui_story_5037_50370901_25_dialog_content = "Estamos ficando sem tempo, mas o trabalho continua se acumulando. Às vezes, não há escolha a não ser abrir mão de um pouco do nosso tempo livre...",
  ui_story_5037_50370901_26_dialog_content = "... Você tem usado suas pausas para trabalhar no show nesses últimos dias?",
  ui_story_5037_50370901_27_dialog_content = "Uh... K-Meio que...?",
  ui_story_5037_50370901_28_dialog_content = "Isso não vai dar!",
  ui_story_5037_50370901_29_dialog_content = "Sem descanso adequado, a qualidade do seu trabalho só vai sofrer! Você não conseguirá fazer nada nesse ritmo!",
  ui_story_5037_50370901_30_dialog_content = "Para compensar todas as pausas que você passou trabalhando, você vai tirar a tarde inteira de folga!",
  ui_story_5037_50370901_31_dialog_content = "Vá dar uma caminhada, tomar um pouco de ar fresco e não volte até que esteja bem e descansado!",
  ui_story_5037_50370901_32_dialog_content = "Th-Isso realmente não é necessário...",
  ui_story_5037_50370901_33_dialog_content = "Não aceito não como resposta! Isso diz respeito tanto à sua saúde quanto à sua eficiência no trabalho.",
  ui_story_5037_50370901_34_dialog_content = "M-Mas se eu sou seu produtor, o que você vai fazer se eu não estiver por perto?",
  ui_story_5037_50370901_35_dialog_content = "Você não precisa se preocupar com isso. Eu te disse, fui meu próprio produtor por muito tempo. Isso não é grande coisa.",
  ui_story_5037_50370901_36_dialog_content = "Agora descanse um pouco e não volte ao escritório até amanhã de manhã!",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>Bater!</color>",
  ui_story_5037_50370901_38_dialog_content = "(Ela apenas me empurrou porta afora...)",
  ui_story_5037_50370901_39_dialog_content = "(Hmm... Acho que vou dar uma volta então.)",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>Alguns minutos depois em um café</color>",
  ui_story_5037_50370901_41_dialog_content = "O que posso pegar para você?",
  ui_story_5037_50370901_42_dialog_content = "Deixa eu dar uma olhada no cardápio...",
  ui_story_5037_50370901_43_dialog_content = "\"Bolo Tricolor\"?",
  ui_story_5037_50370901_44_dialog_content = "A nossa missão é realizar três concertos num determinado período de tempo.",
  ui_story_5037_50370901_45_dialog_content = "Ainda temos mais dois concertos pela frente...",
  ui_story_5037_50370901_46_dialog_content = "Por que estou pensando nisso de repente?! De volta ao cardápio!",
  ui_story_5037_50370901_47_dialog_content = "Vejamos... Bolos Gêmeos?",
  ui_story_5037_50370901_48_dialog_content = "Após o início dos shows, o público pode seguir suas preferências e circular livremente entre os palcos.",
  ui_story_5037_50370901_49_dialog_content = "Ao final, a etapa que conseguir reunir maior público será declarada vencedora.",
  ui_story_5037_50370901_50_dialog_content = "Suspiro... Eu me pergunto o que podemos fazer para manter a atenção das pessoas?",
  ui_story_5037_50370901_51_dialog_content = "Kyllo é realmente um motivador tão potente?",
  ui_story_5037_50370901_52_dialog_content = "Devo encontrar meu próprio Kyllo para morder meu tornozelo?",
  ui_story_5037_50370901_53_dialog_content = "Por que não consigo parar de me preocupar?!",
  ui_story_5037_50370901_54_dialog_content = "Desculpe, acho que ainda preciso de mais tempo para olhar o menu.",
  ui_story_5037_50370901_55_dialog_content = "Não é um problema. Só me ligue quando estiver pronto.",
  ui_story_5037_50370901_56_dialog_content = "Mesmo não estando no trabalho, não consigo parar de pensar no concerto de avaliação. Faltam poucos dias...",
  ui_story_5037_50370901_57_dialog_content = "Também não planejei a agenda de Goldie para amanhã. Não consigo deixar de me sentir desconfortável sempre que penso nisso...",
  ui_story_5037_50370901_58_dialog_content = "Suspiro... Café e bolo simplesmente não sabem tão bem quando estou tão estressado.",
  ui_story_5037_50370901_59_dialog_content = "Eu me pergunto como está indo o treinamento de Goldie...?",
  ui_story_5037_50370901_60_dialog_content = "Tudo bem se eu der uma olhada para garantir que ela está bem. Certo?",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>Fora da agência</color>",
  ui_story_5037_50370901_62_dialog_content = "Esta deve ser a sala de ensaio. Eu deveria ser capaz de olhar para dentro através da janela.",
  ui_story_5037_50370901_63_dialog_content = "eu consigo ver Goldie... Mas aquela pessoa ao lado dela...",
  ui_story_5037_50370901_64_dialog_content = "Alô, Goldie? Estou com o Daily Drivel, a fonte das fofocas mais quentes de todo Umbraton!",
  ui_story_5037_50370901_65_dialog_content = "Percebi que você bateu a porta na cara do seu produtor hoje cedo.",
  ui_story_5037_50370901_66_dialog_content = "Dizem na rua que você nunca se deu bem com ele e que o demitiu na hora! Isso é verdade?",
  ui_story_5037_50370901_67_dialog_content = "PlayerName e estou nas melhores condições, muito obrigado. Sempre fomos muito bons amigos.",
  ui_story_5037_50370901_68_dialog_content = "Então, como você explica a cena anterior?",
  ui_story_5037_50370901_69_dialog_content = "Jogar fora o seu produtor e deixá-lo parado na rua... Nunca vi coisa tão lamentável!",
  ui_story_5037_50370901_70_dialog_content = "Isso foi porque—",
  ui_story_5037_50370901_71_dialog_content = "Merda... É aquele paparazzi detestável de antes!",
  ui_story_5037_50370901_72_dialog_content = "Goldie nunca o conheceu ou lidou com ele antes... Se ele não for parado, ele vai inventar coisas de novo!",
  ui_story_5037_50370901_73_dialog_content = "Eu tenho que ajudá-la!",
  ui_story_5037_50370901_74_dialog_content = "Que triste, pequeno produtor... Jogado no mundo frio como um cachorro indesejado, sem ao menos um...",
  ui_story_5037_50370901_75_dialog_content = "Ei! O que está acontecendo aqui?",
  ui_story_5037_50370901_76_dialog_content = "PlayerName?!",
  ui_story_5037_50370901_77_dialog_content = "E-é você!",
  ui_story_5037_50370901_78_dialog_content = "Eu ouvi você dizer algo sobre Goldie e eu não estou me dando bem?",
  ui_story_5037_50370901_79_option_content = "Negar veementemente os rumores",
  ui_story_5037_50370901_80_dialog_content = "Isso é ridículo! Goldie e eu somos a melhor dupla profissional possível.",
  ui_story_5037_50370901_81_option_content = "Explique pacientemente a situação",
  ui_story_5037_50370901_82_dialog_content = "Nosso relacionamento está perfeitamente bem. Trabalhamos muito bem juntos, na verdade.",
  ui_story_5037_50370901_83_dialog_content = "*Zombam*",
  ui_story_5037_50370901_84_dialog_content = "É verdade!",
  ui_story_5037_50370901_85_dialog_content = "E nem pense em distorcer nossas palavras, senão...",
  ui_story_5037_50370901_86_dialog_content = "Ok, ok!",
  ui_story_5037_50370901_87_dialog_content = "Desculpe, mas eu deveria ir!",
  ui_story_5037_50370901_88_dialog_content = "Ufa... Graças a Deus você voltou, PlayerName.",
  ui_story_5037_50370901_89_dialog_content = "Caso contrário, não sei a que teria recorrido para fazer aquele cara ir embora.",
  ui_story_5037_50370901_90_dialog_content = "Nunca imaginei que os paparazzi pudessem ser tão dedicados ao seu trabalho...",
  ui_story_5037_50370901_91_dialog_content = "Ele desceu praticamente no minuto em que saí.",
  ui_story_5037_50370901_92_dialog_content = "Isso me lembra... Você não deveria estar de licença?",
  ui_story_5037_50370901_93_dialog_content = "O que você está fazendo no escritório?",
  ui_story_5037_50370901_94_dialog_content = "Eu, uh... Bem, porque...",
  ui_story_5037_50370901_95_dialog_content = "Suspirar. Olha, eu sei que você me disse para descansar um pouco, mas não posso fazer isso agora.",
  ui_story_5037_50370901_96_dialog_content = "Para dizer a verdade... Não consigo parar de me preocupar com o concerto de avaliação.",
  ui_story_5037_50370901_97_dialog_content = "Assim que começo a pensar nisso, perco o apetite e não consigo descansar.",
  ui_story_5037_50370901_98_dialog_content = "Entendo...",
  ui_story_5037_50370901_99_dialog_content = "Sim... É por isso que eu só quero acabar com as coisas, sabe? Acho que não vou conseguir descansar direito até o show acabar.",
  ui_story_5037_50370901_100_dialog_content = "Hum...",
  ui_story_5037_50370901_101_dialog_content = "Para ser sincero, sinto o mesmo.",
  ui_story_5037_50370901_102_dialog_content = "Eu costumava ser perfeitamente capaz de lidar com esses repórteres fofoqueiros... Nada do que eles diziam ou escreviam realmente me incomodava antes.",
  ui_story_5037_50370901_103_dialog_content = "Mas desde que começamos a trabalhar juntos... Tenho confiado cada vez mais em você para lidar com coisas como esta.",
  ui_story_5037_50370901_104_dialog_content = "Agora posso dizer que fiquei um pouco enferrujado quando se trata de repreender esses caras.",
  ui_story_5037_50370901_105_dialog_content = "Estou fazendo você perder sua vantagem?",
  ui_story_5037_50370901_106_dialog_content = "De jeito nenhum! De qualquer forma, ver você aparecer agora me fez sentir mais forte, PlayerName!",
  ui_story_5037_50370901_107_dialog_content = "Desde que você se tornou meu produtor, pude me dedicar aos treinos, aprimorando muito todas as minhas habilidades.",
  ui_story_5037_50370901_108_dialog_content = "Não sou a mesma Goldie que costumava ser. Eu sou um Super Goldie novo e melhorado!",
  ui_story_5037_50370901_109_dialog_content = "Hahahaha! Bem, estou aliviado por você não achar que estou te segurando.",
  ui_story_5037_50370901_110_dialog_content = "Um produtor fantástico como você nunca poderia fazer algo assim, PlayerName!",
  ui_story_5037_50370901_111_dialog_content = "Mas quando se trata de descansar...",
  ui_story_5037_50370901_112_dialog_content = "Não precisa mais se preocupar comigo, Goldie. Sei que estamos super ocupados agora, mas prometo que vou descansar e me exercitar de agora em diante!",
  ui_story_5037_50370901_113_dialog_content = "Então também terei a certeza de seguir todas as suas decisões.",
  ui_story_5037_50370901_114_dialog_content = "Eu acredito em você!",
  ui_story_5037_50371001_1_dialog_content = "O concerto de avaliação finalmente acabou!",
  ui_story_5037_50371001_2_dialog_content = "Finalmente vencemos nosso maior desafio! Obrigado Senhor.",
  ui_story_5037_50371001_3_dialog_content = "Assim que tenho um momento para relaxar, de repente começo a me sentir tão cansado...",
  ui_story_5037_50371001_4_dialog_content = "Então você deve comemorar descansando bastante hoje!",
  ui_story_5037_50371001_5_dialog_content = "Sim, está na hora.",
  ui_story_5037_50371001_6_dialog_content = "Então o que deveríamos fazer?",
  ui_story_5037_50371001_7_dialog_content = "Espere, eu entendi! Quer me ouvir cantar?",
  ui_story_5037_50371001_8_dialog_content = "Estou preparando uma música novinha em folha para o concerto de formatura!",
  ui_story_5037_50371001_9_dialog_content = "Ainda faltam algumas partes, mas o restante da música já está finalizado.",
  ui_story_5037_50371001_10_dialog_content = "Claro! Aposto que já soa incrível!",
  ui_story_5037_50371001_11_dialog_content = "Então sem mais delongas...",
  ui_story_5037_50371001_12_dialog_content = "♪ Embora devamos seguir caminhos separados, sei que ficaremos bem ♪",
  ui_story_5037_50371001_13_dialog_content = "♪ A mil milhas de distância, mas nossa estrela sempre brilhará ♪",
  ui_story_5037_50371001_14_dialog_content = "♪ Então, por favor, não chore; nosso futuro ainda está por vir ♪",
  ui_story_5037_50371001_15_dialog_content = "♪ Por meio dessa música, digo adeus, embora saiba que nos encontraremos novamente ♪",
  ui_story_5037_50371001_16_dialog_content = "(Incrível...)",
  ui_story_5037_50371001_17_dialog_content = "(Mas desta vez, a letra menciona despedida... E a melodia soa mais suave do que as canções anteriores.)",
  ui_story_5037_50371001_18_dialog_content = "Nós iremos, PlayerName? O que você acha?",
  ui_story_5037_50371001_19_option_content = "Foi bonito!",
  ui_story_5037_50371001_20_dialog_content = "Por que, obrigado!",
  ui_story_5037_50371001_21_option_content = "É diferente de suas músicas anteriores.",
  ui_story_5037_50371001_22_dialog_content = "Ah, então você notou.",
  ui_story_5037_50371001_23_dialog_content = "Afinal, é uma música para o concerto de formatura... Então, naturalmente, eu a escrevi com toda a gratidão do meu coração!",
  ui_story_5037_50371001_24_dialog_content = "Mas parece que há mais do que apenas gratidão.",
  ui_story_5037_50371001_25_dialog_content = "Parece meio triste e melancólico... sei lá.",
  ui_story_5037_50371001_26_dialog_content = "Porque é uma música de despedida.",
  ui_story_5037_50371001_27_dialog_content = "Mas de quem você está se despedindo, Goldie?",
  ui_story_5037_50371001_28_dialog_content = "Há algo que ainda não entendo... O que é exatamente um concerto de formatura?",
  ui_story_5037_50371001_29_dialog_content = "Concertos de formatura são realizados para ídolos que estão se demitindo e saindo.",
  ui_story_5037_50371001_30_dialog_content = "É uma chance do ídolo se despedir de seus fãs.",
  ui_story_5037_50371001_31_dialog_content = "Wha-?!",
  ui_story_5037_50371001_32_dialog_content = "Você não vai mais ser um ídolo depois desse show???",
  ui_story_5037_50371001_33_dialog_content = "O que você está falando? Eu ainda tenho muitos anos sendo um ídolo em mim.",
  ui_story_5037_50371001_34_dialog_content = "Este concerto é apenas para um vídeo promocional! Meu verdadeiro concerto de formatura não será por muito, muito tempo!",
  ui_story_5037_50371001_35_dialog_content = "Além disso... Como meu produtor, eu queria que você experimentasse como é trabalhar com um ídolo até o final de sua carreira!",
  ui_story_5037_50371001_36_dialog_content = "Eu ainda pretendo ser um ídolo depois, bobo!",
  ui_story_5037_50371001_37_dialog_content = "Você me assustou pra caralho...",
  ui_story_5037_50371001_38_dialog_content = "Por um segundo, pensei que você tinha acabado de ser um ídolo.",
  ui_story_5037_50371001_39_dialog_content = "Claro que não!",
  ui_story_5037_50371001_40_dialog_content = "Para mim, este próximo concerto é apenas a conclusão de um capítulo da minha carreira.",
  ui_story_5037_50371001_41_dialog_content = "Servirá como encerramento para todo o tempo que passamos juntos e todas as dificuldades e vitórias que compartilhamos!",
  ui_story_5037_50371001_42_dialog_content = "Entendi.",
  ui_story_5037_50371001_43_dialog_content = "Honestamente, não consigo imaginar você fazendo outra coisa na vida...",
  ui_story_5037_50371001_44_dialog_content = "Na minha opinião, você é o epítome de um ídolo.",
  ui_story_5037_50371001_45_dialog_content = "Eu não posso te dizer o quanto isso significa para mim!",
  ui_story_5037_50371001_46_dialog_content = "Se é essa a impressão que dou, significa que estou fazendo meu trabalho direito!",
  ui_story_5037_50371001_47_dialog_content = "Mas no final das contas... Sou apenas uma pessoa comum, como todo mundo.",
  ui_story_5037_50371001_48_dialog_content = "Algum dia, terei que fazer um verdadeiro concerto de formatura e dizer adeus aos meus fãs.",
  ui_story_5037_50371001_49_dialog_content = "Vamos falar de algo menos deprimente...",
  ui_story_5037_50371001_50_dialog_content = "É isso? Acho que não.",
  ui_story_5037_50371001_51_dialog_content = "Não?",
  ui_story_5037_50371001_52_dialog_content = "A formatura é apenas mais uma parte da vida de um ídolo e, inevitavelmente, acontece com todos nós, quer a aceitemos ou não.",
  ui_story_5037_50371001_53_dialog_content = "Em vez de tentar evitá-lo, quero fazer tudo o que puder para garantir que meu próprio concerto de formatura seja o melhor de todos!",
  ui_story_5037_50371001_54_dialog_content = "Aconteça o que acontecer, não quero ter nenhum arrependimento, nem para mim nem para os meus fãs.",
  ui_story_5037_50371001_55_dialog_content = "Aconteça o que acontecer, quero ter certeza de que brilharei em seus corações pelo resto de suas vidas.",
  ui_story_5037_50371001_56_dialog_content = "Por isso vou continuar fazendo o meu melhor até chegar o dia da formatura!",
  ui_story_5037_50371001_57_dialog_content = "Isso soa muito como você!",
  ui_story_5037_50371001_58_dialog_content = "Então, quando chegar a hora de parar de ser um ídolo... O que você fará então?",
  ui_story_5037_50371001_59_dialog_content = "Hmm... Eu realmente não decidi ainda!",
  ui_story_5037_50371001_60_dialog_content = "Eu tenho muitas ideias, mas agora... Minha favorita é abrir meu próprio café para animais de estimação!",
  ui_story_5037_50371001_61_dialog_content = "Dessa forma, posso trabalhar e fazer companhia ao Marshmallow ao mesmo tempo!",
  ui_story_5037_50371001_62_dialog_content = "Isso parece uma ótima ideia!",
  ui_story_5037_50371001_63_dialog_content = "Beber café e brincar com bichinhos fofos... parece um sonho.",
  ui_story_5037_50371001_64_dialog_content = "Estou bem aí com você!",
  ui_story_5037_50371001_65_dialog_content = "Sempre que me sinto cansado, acariciar o pelo macio e fofo de Marshmallow sempre me ajuda a relaxar.",
  ui_story_5037_50371001_66_dialog_content = "Como ídolo, meu trabalho é animar a todos com o poder da música e da dança.",
  ui_story_5037_50371001_67_dialog_content = "Um café para animais de estimação me ajudaria a continuar trazendo alegria para a vida de todos depois que eu me aposentar!",
  ui_story_5037_50371001_68_dialog_content = "Aconteça o que acontecer na vida, sei que ficarei bem com isso.",
  ui_story_5037_50371101_1_dialog_content = "(Encontrei uma carta de Vic no escritório hoje. Foi endereçada a mim.)",
  ui_story_5037_50371101_2_dialog_content = "(Ele disse para esperar por ele no salão de dança mais tarde hoje... Que ele queria me perguntar sobre algumas coisas em particular.)",
  ui_story_5037_50371101_3_dialog_content = "Você veio!",
  ui_story_5037_50371101_4_dialog_content = "Hum? Isso é você, Fia?",
  ui_story_5037_50371101_5_dialog_content = "Ai, ai, ai... Calma, Fia! Você vai arrancar a orelha do seu pobre patrão!",
  ui_story_5037_50371101_6_dialog_content = "O que vocês estão fazendo aqui?",
  ui_story_5037_50371101_7_dialog_content = "Eu disse que não havia razão para se preocupar com isso, Fia!",
  ui_story_5037_50371101_8_dialog_content = "Ainda que PlayerName é nosso amigo, ele ainda precisa acertar as coisas!",
  ui_story_5037_50371101_9_dialog_content = "...Alguém poderia explicar o que está acontecendo?",
  ui_story_5037_50371101_10_dialog_content = "Tudo bem, deixe-me ser direto. Qual é o problema com os paparazzi que andam por aqui todos os dias?",
  ui_story_5037_50371101_11_dialog_content = "Paparazzi?",
  ui_story_5037_50371101_12_dialog_content = "Oh, você quer dizer aquele cara de aparência esboçada com barba?",
  ui_story_5037_50371101_13_dialog_content = "Sim, é esse mesmo! Então você o conhece!",
  ui_story_5037_50371101_14_dialog_content = "Aquele idiota continua invadindo e interrompendo o treinamento do meu mestre inútil!",
  ui_story_5037_50371101_15_dialog_content = "O pior é que toda vez que eu o expulso... No dia seguinte, ele publica um artigo maldoso que calunia o Mestre e elogia Goldie!",
  ui_story_5037_50371101_16_dialog_content = "Diga a verdade! Ele está trabalhando para vocês?",
  ui_story_5037_50371101_17_dialog_content = "... Você honestamente acha que eu faria algo assim?",
  ui_story_5037_50371101_18_dialog_content = "Também somos assediados por ele todos os dias!",
  ui_story_5037_50371101_19_dialog_content = "Sério?",
  ui_story_5037_50371101_20_dialog_content = "Ver? Eu disse que não eram eles!",
  ui_story_5037_50371101_21_dialog_content = "O mesmo jornal que me caluniou também fez o mesmo com Goldie no passado.",
  ui_story_5037_50371101_22_dialog_content = "S-Sério?",
  ui_story_5037_50371101_23_dialog_content = "Acho que só tenho lido as coisas sobre o meu mestre imprestável...",
  ui_story_5037_50371101_24_dialog_content = "Mas agora que você mencionou... Acho que me lembro de ter visto artigos difamatórios sobre Vic também.",
  ui_story_5037_50371101_25_dialog_content = "Mas se vocês não o mandaram para cá, quem o mandou?",
  ui_story_5037_50371101_26_dialog_content = "Acho que ele continua voltando porque acha que este lugar está cheio de fofocas sobre as quais escrever.",
  ui_story_5037_50371101_27_dialog_content = "Mesmo que eu tranque a porta todos os dias antes de sair, ele sempre consegue entrar...",
  ui_story_5037_50371101_28_dialog_content = "Eu juro, não há como se livrar dele!",
  ui_story_5037_50371101_29_dialog_content = "Eu sei, hein! Ele está nos custando muitos fãs também!",
  ui_story_5037_50371101_30_dialog_content = "Então, acho que tudo isso foi apenas um mal-entendido...",
  ui_story_5037_50371101_31_dialog_content = "Desculpe por suspeitar de você.",
  ui_story_5037_50371101_32_dialog_content = "Não se preocupe com isso, Fia. Vocês precisam de mais alguma coisa?",
  ui_story_5037_50371101_33_dialog_content = "Não! O mestre ainda tem muito treino a fazer, então nos vemos mais tarde!",
  ui_story_5037_50371101_34_dialog_content = "Vamos todos dar o nosso melhor, ok?",
  ui_story_5037_50371101_35_dialog_content = "Claro, então—",
  ui_story_5037_50371101_36_dialog_content = "<size=45>Espere!</size>",
  ui_story_5037_50371101_37_dialog_content = "Huh? E agora?",
  ui_story_5037_50371101_38_dialog_content = "Eu tenho um pequeno pedido, PlayerName.",
  ui_story_5037_50371101_39_dialog_content = "S-Sim...?",
  ui_story_5037_50371101_40_dialog_content = "Você poderia... Você poderia me ensinar como lidar com os paparazzi? Eu estou te implorando!",
  ui_story_5037_50371101_41_dialog_content = "Ha?! M-Cuide do meu espaço pessoal!",
  ui_story_5037_50371101_42_dialog_content = "Pare de usar minha bandana para enxugar suas lágrimas!!",
  ui_story_5037_50371101_43_dialog_content = "*Sniff* Ok...",
  ui_story_5037_50371101_44_dialog_content = "Graças àquele repórter estúpido e todas as suas mentiras... Perdi mais fãs do que posso perder!",
  ui_story_5037_50371101_45_dialog_content = "A única maneira de compensar meus fãs perdidos é treinar mais do que nunca e entrar no maior número possível de eventos de ídolos.",
  ui_story_5037_50371101_46_dialog_content = "Fia também não me deixa escapar... Ela me encara como um falcão durante o treinamento, então não posso relaxar nem por um segundo!",
  ui_story_5037_50371101_47_dialog_content = "Ora, ainda no último treino, tentei recuperar o fôlego por alguns instantes... E ela fez Kyllo morder minha perna!",
  ui_story_5037_50371101_48_dialog_content = "Basta olhar para isso, PlayerName! Minha perna tem mais marcas de mordida do que um brinquedo de mastigar! Você tem que me salvar...",
  ui_story_5037_50371101_49_dialog_content = "Tudo bem! Vou te ensinar o que sei!",
  ui_story_5037_50371101_50_dialog_content = "Eu sabia que podia contar com você!",
  ui_story_5037_50371101_51_dialog_content = "Agora, por onde devemos começar...",
  ui_story_5037_50371101_52_dialog_content = "Por que não damos uma olhada na edição de hoje do Daily Drivel primeiro? Vamos ver...",
  ui_story_5037_50371101_53_dialog_content = "\"Vic uma vez se descreveu como um eterno jovem de 18 anos, mas sua idade real é muito maior do que isso\"?!",
  ui_story_5037_50371101_54_dialog_content = "Quero dizer, isso soa como uma afirmação verdadeira.",
  ui_story_5037_50371101_55_dialog_content = "Ah, eu me lembro! Acho que disse isso sobre mim, sim...",
  ui_story_5037_50371101_56_dialog_content = "Como isso é mentira, então?!",
  ui_story_5037_50371101_57_dialog_content = "Minha idade real é um segredo!",
  ui_story_5037_50371101_58_dialog_content = "Tudo bem... Acho que está tudo bem, apenas lembre-se de manter isso em segredo.",
  ui_story_5037_50371101_59_dialog_content = "O que mais ele diz? \"Vic acredita que ele é muito mais jovem e enérgico do que o sempre popular Goldie\"?!",
  ui_story_5037_50371101_60_dialog_content = "Ha? Essas foram as palavras dele, não minhas! Ele disse isso enquanto elogiava minha performance!",
  ui_story_5037_50371101_61_dialog_content = "Então... Como você respondeu?",
  ui_story_5037_50371101_62_dialog_content = "Bem, um elogio é um elogio! Por que eu negaria?",
  ui_story_5037_50371101_63_dialog_content = "Se você concorda com tudo o que ele diz, você se torna um alvo ainda mais fácil, Vic!",
  ui_story_5037_50371101_64_dialog_content = "Th-Então como eu deveria ter respondido?!",
  ui_story_5037_50371101_65_dialog_content = "A frase dele foi feita para induzi-lo a admitir que você se acha melhor do que os outros ídolos.",
  ui_story_5037_50371101_66_dialog_content = "Portanto, se você se encontrar em uma situação semelhante, tente ser mais humilde e diga que os outros são melhores do que você. Assim, ele não terá com o que trabalhar!",
  ui_story_5037_50371101_67_dialog_content = "Está bem, está bem. Vou tentar isso da próxima vez!",
  ui_story_5037_50371101_68_dialog_content = "Vamos continuar lendo...",
  ui_story_5037_50371101_69_dialog_content = "\"O produtor de Vic é conhecido por ameaçar repórteres inocentes com animais violentos e selvagens\"?!",
  ui_story_5037_50371101_70_dialog_content = "Fia... O que você fez?",
  ui_story_5037_50371101_71_dialog_content = "D-Não olhe para mim!",
  ui_story_5037_50371101_72_dialog_content = "Ele era muito chato, então fiz Kyllo jogá-lo na rua!",
  ui_story_5037_50371101_73_dialog_content = "Eu vejo... Não vamos mais fazer isso, ok?",
  ui_story_5037_50371101_74_dialog_content = "Por mais irritantes que sejam esses repórteres, recorrer à violência nunca é a maneira certa de lidar com eles.",
  ui_story_5037_50371101_75_dialog_content = "Você está apenas dando a eles mais motivos para atacá-lo com suas calúnias.",
  ui_story_5037_50371101_76_dialog_content = "Então, como devo lidar com eles?!",
  ui_story_5037_50371101_77_dialog_content = "Não posso impedi-los de entrar e não posso fazê-los sair... Eles são como um enxame de mosquitos, mas ainda mais cruéis!",
  ui_story_5037_50371101_78_dialog_content = "Quando eles o importunam assim, você pode apenas insistir educadamente que não está aceitando entrevistas e rejeitá-los.",
  ui_story_5037_50371101_79_dialog_content = "Assim, mesmo que difamem Vic em seus artigos, suas reivindicações não terão nenhuma evidência real para apoiá-las, o que as pessoas perceberão.",
  ui_story_5037_50371101_80_dialog_content = "Também, desde que Vic continua melhorando, nenhuma fofoca será capaz de ferir sua reputação.",
  ui_story_5037_50371101_81_dialog_content = "Ok, acho que entendi agora.",
  ui_story_5037_50371101_82_dialog_content = "Obrigada, PlayerName. Você realmente é um salva-vidas!",
  ui_story_5037_50371101_83_dialog_content = "Não mencione isso. Podemos ser rivais por enquanto, mas sempre seremos amigos primeiro.",
  ui_story_5037_50371101_84_dialog_content = "Eu nunca deixaria algo tão trivial como um concurso atrapalhar meus amigos!",
  ui_story_5037_50371101_85_dialog_content = "*Soluçando* Você realmente é meu herói!",
  ui_story_5037_50371101_86_dialog_content = "Muito obrigado, PlayerName!",
  ui_story_5037_50371101_87_dialog_content = "Juro pela minha honra como extrozoologista e ídolo que não vou decepcioná-lo!",
  ui_story_5037_50371101_88_dialog_content = "Quando Fia estava pesquisando sobre como se tornar uma produtora, ela encontrou alguns livros que podem ser úteis.",
  ui_story_5037_50371101_89_dialog_content = "Vá em frente e escolha um deles. Considere isso como um sinal de nossa gratidão.",
  ui_story_5037_50371101_90_dialog_content = "Espere... Esses não são meus livros? Não é à toa que não consegui encontrá-los todo esse tempo... Você os estava escondendo em suas roupas!",
  ui_story_5037_50371101_91_dialog_content = "A-De qualquer forma, eu já li os dois, então escolha o que você quiser, PlayerName.",
  ui_story_5037_50371101_92_dialog_content = "Obrigado... Vou ficar com este por enquanto—",
  ui_story_5037_50371101_93_option_content = "\"Curso Intensivo para Novos Ídolos\"",
  ui_story_5037_50371101_94_option_content = "\"Desenvolvimento profissional para produtores profissionais\"",
  ui_story_5037_50371101_95_dialog_content = "Certo! Devemos voltar ao nosso treinamento agora!",
  ui_story_5037_50371101_96_dialog_content = "Vamos, seu mestre imprestável! O dia ainda não acabou!",
  ui_story_5037_50371101_97_dialog_content = "H-Huh?! Ainda?!",
  ui_story_5037_50371101_98_dialog_content = "Isso mesmo! Perdemos muito tempo precioso conversando com PlayerName, então agora você vai inventar tudo!",
  ui_story_5037_50371101_99_dialog_content = "Alguém me salve... Por favor...",
  ui_story_5037_50371201_1_dialog_content = "Vic me pediu para esperar por ele aqui... Ele não sabe que o concurso de shows está chegando?",
  ui_story_5037_50371201_2_dialog_content = "Ele até me disse para vir aqui sozinha, e manter isso em segredo da Fia...",
  ui_story_5037_50371201_3_dialog_content = "O que diabos ele está fazendo agora?",
  ui_story_5037_50371201_4_dialog_content = "Oh o? Dentro do prazo, do jeito que eu esperava! Bom te ver, PlayerName!",
  ui_story_5037_50371201_5_dialog_content = "Tudo bem Vic, me diga o que está acontecendo...",
  ui_story_5037_50371201_6_dialog_content = "Oh, nada terrivelmente importante, realmente! Eu só queria perguntar...",
  ui_story_5037_50371201_7_dialog_content = "Você poderia me deixar me esconder aqui por um dia? Por favor?!",
  ui_story_5037_50371201_8_dialog_content = "Huh...?!",
  ui_story_5037_50371201_9_dialog_content = "Está quase na hora do show, por que você iria querer se esconder aqui em vez de treinar?",
  ui_story_5037_50371201_10_dialog_content = "Justamente por causa da minha formação! Apenas ouça, é assim que um dia normal se parece para mim...",
  ui_story_5037_50371201_11_dialog_content = "Fia me acorda todas as manhãs para treinar antes mesmo do sol nascer.",
  ui_story_5037_50371201_12_dialog_content = "Levante-se, mestre preguiçoso! É hora de treinar!",
  ui_story_5037_50371201_13_dialog_content = "Vamos começar colocando esse corpo flácido em forma! Dez voltas na floresta, pronto!",
  ui_story_5037_50371201_14_dialog_content = "Hrnnng... Mas estou com tanto sono...",
  ui_story_5037_50371201_15_dialog_content = "Só mais cinco minutos...",
  ui_story_5037_50371201_16_dialog_content = "Não está cooperando? Tudo bem por mim... Pegue-o, Kyllo!",
  ui_story_5037_50371201_17_dialog_content = "Lo—!",
  ui_story_5037_50371201_18_dialog_content = "Ai!!!",
  ui_story_5037_50371201_19_dialog_content = "S-Pare com a mordida! Estou de pé, estou de pé!!!",
  ui_story_5037_50371201_20_dialog_content = "Depois da minha corrida, tomo um banho rápido e café da manhã.",
  ui_story_5037_50371201_21_dialog_content = "O café da manhã de hoje é um pão de serragem com acompanhamento de cenoura cozida e um copo de leite!",
  ui_story_5037_50371201_22_dialog_content = "M-Mas eu como cenoura cozida há três dias seguidos... Podemos mudar um pouco as coisas?",
  ui_story_5037_50371201_23_dialog_content = "Como talvez alguns espetos de verme da areia grelhados e picantes?",
  ui_story_5037_50371201_24_dialog_content = "Você é um ídolo agora, Mestre, e os ídolos devem cuidar de sua figura o tempo todo! Se você não quer cenoura cozida, então você está sem sorte... Porque adivinha o que tem para almoço e jantar?",
  ui_story_5037_50371201_25_dialog_content = "Nãooooooo!",
  ui_story_5037_50371201_26_dialog_content = "Óh, e-",
  ui_story_5037_50371201_27_dialog_content = "Urgh... Acho que já ouvi o suficiente, Vic...",
  ui_story_5037_50371201_28_dialog_content = "É por isso que, no interesse da minha saúde e também da minha sanidade, eu imploro, PlayerName... Deixe-me esconder aqui por um dia e descansar!",
  ui_story_5037_50371201_29_dialog_content = "Apenas um dia é mais do que suficiente! Nenhum auroriano deveria ter que passar por esse tipo de inferno!",
  ui_story_5037_50371201_30_dialog_content = "Se isso continuar, o mundo perderá seu maior extrozoólogo em pouco tempo!",
  ui_story_5037_50371201_31_dialog_content = "Você... eu... Suspiro...",
  ui_story_5037_50371201_32_dialog_content = "Sei que Fia está fazendo isso apenas para ajudá-lo a passar no concurso de shows, mas o regime de treinamento dela parece um pouco... rígido.",
  ui_story_5037_50371201_33_dialog_content = "Você pode ficar aqui e descansar um pouco, mas apenas com duas condições—",
  ui_story_5037_50371201_34_dialog_content = "Um, você tem que voltar para Fia assim que estiver descansado, para que ela não se preocupe com você.",
  ui_story_5037_50371201_35_dialog_content = "E dois... Você precisa ter uma conversa séria com Fia sobre seus sentimentos em seu regime de treinamento.",
  ui_story_5037_50371201_36_dialog_content = "Não é um problema! Contanto que eu consiga perder, quer dizer, perder um pouco desse cansaço. Farei o que você quiser!",
  ui_story_5037_50371201_37_dialog_content = "Certo, então descanse um pouco, Vic. Ainda tenho que preparar a agenda de Goldie para hoje, então vou deixar você em paz.",
  ui_story_5037_50371201_38_dialog_content = "Sim, sim, vá em frente! Eu vou ficar bem sozinha!",
  ui_story_5037_50371201_39_dialog_content = "Este sofá parece terrivelmente confortável... Perfeito para uma boa e longa soneca!",
  ui_story_5037_50371201_40_dialog_content = "Tudo bem, minha Bolinha de Pêlos, vem cá que eu te abraço enquanto durmo!",
  ui_story_5037_50371201_41_dialog_content = "Piu!",
  ui_story_5037_50371201_42_dialog_content = "Roncar... Roncar...",
  ui_story_5037_50371201_43_dialog_content = "(Ele já está dormindo? Isso é Vic para você, eu acho...)",
  ui_story_5037_50371201_44_dialog_content = "(Bem, eu deveria voltar ao trabalho agora.)",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50371201_46_dialog_content = "(Tudo bem, isso deve bastar para o cronograma! Acho que estou começando a pegar o jeito dessas coisas!)",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>TOC Toc!</color>",
  ui_story_5037_50371201_48_dialog_content = "(Hmm? Tem alguém na porta...)",
  ui_story_5037_50371201_49_dialog_content = "Olá?",
  ui_story_5037_50371201_50_dialog_content = "Olá, PlayerName! Sou eu, Fia!",
  ui_story_5037_50371201_51_dialog_content = "(F-Fia?!)",
  ui_story_5037_50371201_52_dialog_content = "(Oh não... Vic ainda está aqui!)",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>TOC Toc!</color>",
  ui_story_5037_50371201_54_dialog_content = "PlayerName?",
  ui_story_5037_50371201_55_dialog_content = "J-Só um segundo!",
  ui_story_5037_50371201_56_dialog_content = "Vic! Acorda, Vik!",
  ui_story_5037_50371201_57_dialog_content = "Nnng... Haha... Pare com isso, sua Bolinha de Pêlos... Hahaha...",
  ui_story_5037_50371201_58_dialog_content = "Ele dorme ainda mais pesado do que eu!",
  ui_story_5037_50371201_59_dialog_content = "(Acho que não pode ser ajudado ... vou ter que escondê-lo por enquanto.)",
  ui_story_5037_50371201_60_dialog_content = "(Deixe-me ver... Esta pilha de revistas parece boa. Vou escondê-lo atrás dela!)",
  ui_story_5037_50371201_61_dialog_content = "Chegando, Fia!",
  ui_story_5037_50371201_62_dialog_content = "Por que demorou tanto?",
  ui_story_5037_50371201_63_dialog_content = "D-Desculpe, eu só estava, uh... Limpando o quarto!",
  ui_story_5037_50371201_64_dialog_content = "Bem, parece que o lugar precisa de uma arrumação... Essa pilha de revistas é do tamanho de uma montanha!",
  ui_story_5037_50371201_65_dialog_content = "Aha...ha... De qualquer forma, você precisa de algo, Fia?",
  ui_story_5037_50371201_66_dialog_content = "Sim, na verdade... Você tem visto Master Vic por aqui ultimamente?",
  ui_story_5037_50371201_67_dialog_content = "Uh, V-Vic? Não, não posso dizer que tenho!",
  ui_story_5037_50371201_68_dialog_content = "Você não diz...?",
  ui_story_5037_50371201_69_dialog_content = "Eu tenho limpado o dia todo hoje, assim como trabalhando na agenda de Goldie... Então não, eu não vi Vic hoje!",
  ui_story_5037_50371201_70_dialog_content = "Suspiro... Se você diz. Sinceramente, estou surpreso por ele não ter vindo correndo até você primeiro...",
  ui_story_5037_50371201_71_dialog_content = "Para onde aquele meu mestre imprestável fugiu para...?",
  ui_story_5037_50371201_72_dialog_content = "Talvez ele tenha ido a algum lugar para relaxar um pouco? Tenho certeza que ele estará de volta em breve.",
  ui_story_5037_50371201_73_dialog_content = "Faltam poucos dias para o show... Não acredito que aquele cara ainda pensa que pode trepar assim.",
  ui_story_5037_50371201_74_dialog_content = "Vou me certificar de treiná-lo com força extra quando ele voltar...",
  ui_story_5037_50371201_75_dialog_content = "É possível que seu treinamento seja o motivo da fuga, Fia?",
  ui_story_5037_50371201_76_dialog_content = "Tudo bem levar o treino a sério e tudo mais... Mas você tem que se lembrar de balancear isso com o descanso também.",
  ui_story_5037_50371201_77_dialog_content = "Você pensa?",
  ui_story_5037_50371201_78_dialog_content = "Sabe, eu estava pensando em dar a ele um dia de folga, para que ele pudesse descansar um pouco...",
  ui_story_5037_50371201_79_dialog_content = "Mas então ele de repente desapareceu de mim! Eu procurei por toda Umbraton, mas ainda não há sinal dele.",
  ui_story_5037_50371201_80_dialog_content = "(Fia estava planejando dar Vic um dia de folga o tempo todo? Então ela está organizando a agenda dele corretamente.)",
  ui_story_5037_50371201_81_dialog_content = "Não se preocupe, Fia. Vou pedir a todos que ajudem a procurá-lo.",
  ui_story_5037_50371201_82_dialog_content = "Claro, obrigado. Vou continuar pesquisando então.",
  ui_story_5037_50371201_83_dialog_content = "Espere um segundo... Isso não é...?",
  ui_story_5037_50371201_84_dialog_content = "(Merda! Ela notou a pilha de revistas sob a qual Vic está escondido!)",
  ui_story_5037_50371201_85_dialog_content = "Oh! D-Desculpe, essas são apenas algumas revistas que eu estava folheando antes! Vou limpá-los daqui a pouco...",
  ui_story_5037_50371201_86_dialog_content = "Parece meio engraçado, não é? Como se houvesse algo enterrado embaixo dela...",
  ui_story_5037_50371201_87_dialog_content = "Não, espere—!",
  ui_story_5037_50371201_88_dialog_content = "M-Mestre?!",
  ui_story_5037_50371201_89_dialog_content = "Roncar... Roncar...",
  ui_story_5037_50371201_90_dialog_content = "O-O que ele está fazendo dormindo aqui?!",
  ui_story_5037_50371201_91_dialog_content = "PlayerName... Você estava mentindo para mim?",
  ui_story_5037_50371201_92_dialog_content = "eu, eh...",
  ui_story_5037_50371201_93_option_content = "Confessar",
  ui_story_5037_50371201_94_dialog_content = "Tudo bem, eu confesso... Eu estava mentindo para você mais cedo.",
  ui_story_5037_50371201_95_dialog_content = "Sinto muito...",
  ui_story_5037_50371201_96_dialog_content = "Está bem, PlayerName. Eu sei que você não mentiria para mim de propósito.",
  ui_story_5037_50371201_97_option_content = "Faça alguma coisa",
  ui_story_5037_50371201_98_dialog_content = "E-Ele deve ter entrado aqui antes de eu chegar! Sim, deve ser isso...",
  ui_story_5037_50371201_99_dialog_content = "Eu posso dizer que você está mentindo, PlayerName... Está escrito em seu rosto.",
  ui_story_5037_50371201_100_dialog_content = "Mas acho que sei o que está acontecendo aqui.",
  ui_story_5037_50371201_101_dialog_content = "Meu mestre imprestável implorou para você deixá-lo ficar aqui, não foi?",
  ui_story_5037_50371201_102_dialog_content = "Bem, a verdade é...",
  ui_story_5037_50371201_103_dialog_content = "Vic veio me ver esta manhã e perguntou se poderia se esconder aqui e descansar durante o dia.",
  ui_story_5037_50371201_104_dialog_content = "Ele disse que seu treinamento de ídolo o deixou completamente exausto, e ele desmaiou pouco depois de chegar aqui.",
  ui_story_5037_50371201_105_dialog_content = "Mas eu não entendo! Por que ele fugiria e encontraria você em vez de falar comigo?",
  ui_story_5037_50371201_106_dialog_content = "Eu estava planejando dar a ele o dia de folga e tudo!",
  ui_story_5037_50371201_107_dialog_content = "Por que você não fala com ele assim que ele acorda?",
  ui_story_5037_50371201_108_dialog_content = "Suspiro... Esqueça. Vou deixá-lo descansar aqui por enquanto.",
  ui_story_5037_50371201_109_dialog_content = "Lembre-o de voltar para treinar assim que acordar, ok?",
  ui_story_5037_50371201_110_dialog_content = "Vou juntar algumas dicas e truques para o treinamento de ídolos para compartilhar com vocês mais tarde. Tome isso como uma forma de agradecer por ficar de olho no meu mestre imprestável.",
  ui_story_5037_50371201_111_dialog_content = "Claro, obrigado!",
  ui_story_5037_50371201_112_dialog_content = "Ah, e uma última coisa... Não diga a ele que vim aqui, entendeu?",
  ui_story_5037_50371201_113_dialog_content = "Claro, mas por quê?",
  ui_story_5037_50371201_114_dialog_content = "Porque...",
  ui_story_5037_50371201_115_dialog_content = "<size=45>Mestre é completamente indigno de confiança!</size>",
  ui_story_5037_50371201_116_dialog_content = "Hã?!",
  ui_story_5037_50371201_117_dialog_content = "Se você der a ele uma polegada, ele tomará uma milha antes que você perceba!",
  ui_story_5037_50371201_118_dialog_content = "Seja treinando ou apenas fazendo coisas em casa, ele encontrará mais desculpas para relaxar se descobrir que eu daria uma folga a ele.",
  ui_story_5037_50371201_119_dialog_content = "Para pessoas como ele, a única maneira de fazê-los cooperar é sendo impiedosamente rigoroso!",
  ui_story_5037_50371201_120_dialog_content = "T-tudo bem!",
  ui_story_5037_50371201_121_dialog_content = "Vou mandá-lo de volta para o treinamento assim que ele acordar!",
  ui_story_5037_50371301_1_dialog_content = "Por que isso tem que acontecer agora, de todos os tempos?",
  ui_story_5037_50371301_2_dialog_content = "Bem, eu realmente não vejo um problema aqui...",
  ui_story_5037_50371301_3_dialog_content = "Só um Mestre imprestável como você diria isso em um momento como este!",
  ui_story_5037_50371301_4_dialog_content = "Essa situação é muito ruim?",
  ui_story_5037_50371301_5_dialog_content = "Temo que sim...",
  ui_story_5037_50371301_6_dialog_content = "Estamos com sérios problemas agora, pessoal!",
  ui_story_5037_50371301_7_dialog_content = "Por mais que tentemos... Goldie e o progresso de Vic está começando a diminuir!",
  ui_story_5037_50371301_8_dialog_content = "Isso é o que eles chamam de temido \"platô\"!",
  ui_story_5037_50371301_9_dialog_content = "Fia e criei uma solução única para o nosso problema, para que possamos realizar todo o nosso potencial antes de nossos shows de formatura!",
  ui_story_5037_50371301_10_dialog_content = "Vamos trocar de produtores!",
  ui_story_5037_50371301_11_dialog_content = "Hã?!",
  ui_story_5037_50371301_12_dialog_content = "Isso mesmo! Você vai treinar meu mestre imprestável, PlayerName! Enquanto isso, trabalharei com Goldie em seu treinamento!",
  ui_story_5037_50371301_13_dialog_content = "Prepare-se para um programa de intercâmbio de treinamento superemocionante de um dia!",
  ui_story_5037_50371301_14_dialog_content = "Com novos produtores, novos regimes de treinamento e novos ambientes para todos os envolvidos... Tenho certeza de que encontraremos novas e emocionantes inspirações para romper nossos platôs!",
  ui_story_5037_50371301_15_dialog_content = "Então isso significa... Eu estarei encarregado de treinar Vic?",
  ui_story_5037_50371301_16_dialog_content = "Ooh! Parece-me uma boa ideia! Talvez eu finalmente consiga relaxar um pouco...",
  ui_story_5037_50371301_17_dialog_content = "Ai, ai, ai! Esse foi o meu pé, Fia!",
  ui_story_5037_50371301_18_dialog_content = "Nós pensamos nisso também, Mestre. Aqui está, PlayerName; Kyllo será seu assistente para o intercâmbio de treinamento.",
  ui_story_5037_50371301_19_dialog_content = "Lo!",
  ui_story_5037_50371301_20_dialog_content = "E não se preocupe, Kyllo sabe exatamente o que fazer se o Mestre fizer besteira ou se recusar a sair da cama... Certo, Kyllo?",
  ui_story_5037_50371301_21_dialog_content = "Você realmente pensou em tudo, Fia...",
  ui_story_5037_50371301_22_dialog_content = "Pronto, então está resolvido!",
  ui_story_5037_50371301_23_dialog_content = "Faça o seu melhor para ajudar Vic assim como você faz comigo, ok PlayerName?",
  ui_story_5037_50371301_24_dialog_content = "Eu sei que você vai se sair muito bem!",
  ui_story_5037_50371301_25_dialog_content = "Claro, deixe comigo.",
  ui_story_5037_50371301_26_dialog_content = "Iremos, então! Boa sorte, vocês dois!",
  ui_story_5037_50371301_27_dialog_content = "Agora, para uma merecida pausa—",
  ui_story_5037_50371301_28_dialog_content = "Ai!!!",
  ui_story_5037_50371301_29_dialog_content = "L-Solte, Kyllo! Minha perna não é para comer!!!",
  ui_story_5037_50371301_30_dialog_content = "Lo!",
  ui_story_5037_50371301_31_dialog_content = "Uau... Kyllo pode até dizer quando você está pensando em relaxar, Vic. Bastante impressionante.",
  ui_story_5037_50371301_32_dialog_content = "Suspiro... Fia realmente colocou você contra mim, não foi, Kyllo?",
  ui_story_5037_50371301_33_dialog_content = "Afinal eu também fiz por você! Criando você desde o nascimento, dando a você uma maneira de sobreviver no mundo...",
  ui_story_5037_50371301_34_dialog_content = "Ou—ch!!!",
  ui_story_5037_50371301_35_dialog_content = "Parece que Kyllo quer dizer negócios, Vic... Devemos começar com o treinamento.",
  ui_story_5037_50371301_36_dialog_content = "*Soluçando* Por que sempre sou eu quem se machuca...?",
  ui_story_5037_50371301_37_dialog_content = "Não se preocupe, Vik. Eu equilibro trabalho e descanso com meu treinamento, então você deve ficar bem.",
  ui_story_5037_50371301_38_dialog_content = "Em primeiro lugar na agenda de hoje estão os exercícios vocais.",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50371301_40_dialog_content = "♪ Ah, a primavera chegou e tudo voltou à vida! ♪",
  ui_story_5037_50371301_41_dialog_content = "♪ Os animais saem de suas tocas e tocas ♪",
  ui_story_5037_50371301_42_dialog_content = "♪ Na mata e nas pradarias ♪",
  ui_story_5037_50371301_43_dialog_content = "Tudo bem, você pode fazer uma pausa agora, Vic.",
  ui_story_5037_50371301_44_dialog_content = "Afinal! Finalmente é hora do intervalo!",
  ui_story_5037_50371301_45_dialog_content = "Lo...",
  ui_story_5037_50371301_46_dialog_content = "Eu não estou relaxando desta vez, Kyllo! Esta é uma pausa real e honesta!",
  ui_story_5037_50371301_47_dialog_content = "Ei, Vick? Eu queria perguntar... O que fez você querer se tornar um ídolo em primeiro lugar?",
  ui_story_5037_50371301_48_dialog_content = "Huh? Você entendeu tudo errado.",
  ui_story_5037_50371301_49_dialog_content = "Hã?",
  ui_story_5037_50371301_50_dialog_content = "Em primeiro lugar, não sou um ídolo. Eu sou, e sempre serei, um extrozoólogo!",
  ui_story_5037_50371301_51_dialog_content = "Então, o que você está fazendo na competição?!",
  ui_story_5037_50371301_52_dialog_content = "Para ganhar dinheiro, obviamente!",
  ui_story_5037_50371301_53_dialog_content = "Você só está nisso... pelo prêmio em dinheiro?",
  ui_story_5037_50371301_54_dialog_content = "Quer dizer, eu sei que Lady Sheol está oferecendo um grande prêmio, e sei que sua situação financeira costuma ser bem ruim...",
  ui_story_5037_50371301_55_dialog_content = "Mas por que é Fia envolvido também?",
  ui_story_5037_50371301_56_dialog_content = "Em primeiro lugar, foi ideia da Fia! Ela viu um cartaz do concurso e decidiu me arrastar para o esquema dela...",
  ui_story_5037_50371301_57_dialog_content = "Estávamos com pouco dinheiro para cuidar de nossas feras maravilhosas...",
  ui_story_5037_50371301_58_dialog_content = "Quão baixo?",
  ui_story_5037_50371301_59_dialog_content = "Bem... eu tive que me endividar um pouco só para comprar salgadinhos Bica e Drakolion...",
  ui_story_5037_50371301_60_dialog_content = "Tão ruim?!",
  ui_story_5037_50371301_61_dialog_content = "Espere... Você não deveria dispensar lanches para economizar dinheiro se as coisas estão tão ruins assim?",
  ui_story_5037_50371301_62_dialog_content = "Sem chance!",
  ui_story_5037_50371301_63_dialog_content = "Essas feras maravilhosas são minhas amigas; Eu não poderia viver comigo mesmo se eles tivessem que ir sem seus confortos!",
  ui_story_5037_50371301_64_dialog_content = "Geralmente, Fia e Shira ganham dinheiro fazendo biscates entre seus projetos de pesquisa, então nunca tivemos que nos preocupar com dívidas.",
  ui_story_5037_50371301_65_dialog_content = "Mas durante a última expedição de Fia, ela passou um tempo incrível investigando uma fera rara e maravilhosa, apenas para retornar sem nenhum resultado notável.",
  ui_story_5037_50371301_66_dialog_content = "E assim, nossas economias secaram e eu tive que pedir muito dinheiro emprestado!",
  ui_story_5037_50371301_67_dialog_content = "... Posso perguntar o que você estava fazendo enquanto ela estava fora?",
  ui_story_5037_50371301_68_dialog_content = "Eu? Bem, naturalmente, eu estava cuidando das feras maravilhosas e conservando minha energia com muitos cochilos...",
  ui_story_5037_50371301_69_dialog_content = "Parece que você não estava tentando ajudar!",
  ui_story_5037_50371301_70_dialog_content = "De repente, sinto que entendo Fia e a luta de Shira muito mais...",
  ui_story_5037_50371301_71_dialog_content = "Bem, estou aqui ganhando dinheiro agora, não estou? Eu até concordei com todas essas apresentações idiotas!",
  ui_story_5037_50371301_72_dialog_content = "Eu tenho trabalhado muito duro até agora!",
  ui_story_5037_50371301_73_dialog_content = "Eu sei, eu sei... Honestamente, eu esperava que você desistisse no meio do caminho e tentasse encontrar uma saída para isso.",
  ui_story_5037_50371301_74_dialog_content = "Eu nunca faria uma coisa dessas! Especialmente quando se trata de garantir que as feras maravilhosas tenham o suficiente para comer!",
  ui_story_5037_50371301_75_dialog_content = "Eu faria qualquer coisa por esses caras.",
  ui_story_5037_50371301_76_dialog_content = "E é por isso que eu emprestaria meus aprendizes com prazer, para qualquer coisa que você possa precisar! Desde que pague, claro.",
  ui_story_5037_50371301_77_dialog_content = "Esqueça, Vik! Não torne a vida ainda mais difícil para esses dois!",
  ui_story_5037_50371301_78_dialog_content = "Eu juro, às vezes parece que você se preocupa mais com sua Bolinha de Pelos do que com Fia e Shira...",
  ui_story_5037_50371301_79_dialog_content = "Você não poderia estar mais errado! Palavras não podem descrever o quanto estou orgulhoso de meus queridos aprendizes!",
  ui_story_5037_50371301_80_dialog_content = "Não só passei toda a minha experiência extrozoológica para eles... Eles também sabem como ganhar dinheiro e sobreviver no mundo!",
  ui_story_5037_50371301_81_dialog_content = "Além disso, nenhum deles tem medo de lutar contra os Eclipsites!",
  ui_story_5037_50371301_82_dialog_content = "Algum dia, poderei confiar a eles todos os meus projetos de pesquisa sobre as maravilhosas feras de Astra...",
  ui_story_5037_50371301_83_dialog_content = "O que você vai fazer então? Tirar ainda mais sonecas?",
  ui_story_5037_50371301_84_dialog_content = "Não é uma má ideia! Eu vou ter a certeza de considerá-lo!",
  ui_story_5037_50371301_85_dialog_content = "Mas antes disso, ainda tenho muito trabalho importante a fazer.",
  ui_story_5037_50371301_86_dialog_content = "Acredito que existam outros continentes como o Astra em nosso mundo.",
  ui_story_5037_50371301_87_dialog_content = "Quero vê-los todos e aprender tudo o que há para saber sobre as feras maravilhosas que habitam suas terras!",
  ui_story_5037_50371301_88_dialog_content = "Não fazia ideia que tinhas um sonho tão grandioso...",
  ui_story_5037_50371301_89_dialog_content = "Mas é claro! Afinal, eu sou—",
  ui_story_5037_50371301_90_dialog_content = "Ai!!!",
  ui_story_5037_50371301_91_dialog_content = "Qual é a grande ideia, Kyllo?!",
  ui_story_5037_50371301_92_dialog_content = "Parece que Kyllo estava te lembrando que seu intervalo acabou, Vic. De volta aos treinos!",
  ui_story_5037_50371301_93_dialog_content = "Fia realmente teve uma má influência sobre você, não foi Kyllo? Você é ainda mais duro do que ela agora!",
  ui_story_5037_50371301_94_dialog_content = "Mas desde PlayerName está encarregado do meu treinamento hoje, talvez ele possa estender meu intervalo por mais alguns minutos, o que você diz?",
  ui_story_5037_50371301_95_dialog_content = "Hum...",
  ui_story_5037_50371301_96_dialog_content = "Vamos! Vou até deixar você acariciar a Pequena Bola de Pêlos enquanto isso!",
  ui_story_5037_50371301_97_dialog_content = "Bem, quando você coloca dessa forma, suponho que podemos...",
  ui_story_5037_50371301_98_option_content = "Treine o dobro!",
  ui_story_5037_50371301_99_option_content = "Treine dez vezes mais!",
  ui_story_5037_50371301_100_dialog_content = "Desenvolvi um programa de treinamento para ajudar Goldie romper um platô potencial.",
  ui_story_5037_50371301_101_dialog_content = "Nunca coloquei em prática porque parecia muito difícil, mas vou tentar em você primeiro!",
  ui_story_5037_50371301_102_dialog_content = "O quê?!",
  ui_story_5037_50371301_103_dialog_content = "Não se preocupe, é só um pouco. Dessa forma, posso fazer alguns ajustes antes de mostrá-lo para Goldie.",
  ui_story_5037_50371301_104_dialog_content = "Naturalmente, isso também deve ajudá-lo a melhorar.",
  ui_story_5037_50371301_105_dialog_content = "Não podemos deixar que todo o trabalho duro da Fia seja em vão, então vamos treinar com o coração! Está pronto, Vic?",
  ui_story_5037_50371301_106_dialog_content = "Nããão-!!!",
  ui_story_5037_50371401_1_dialog_content = "Equipe PlayerNamereunião de emergência, pegue um! Três, dois, um... Ação!",
  ui_story_5037_50371401_2_dialog_content = "D-Nós realmente temos que filmar isso também?",
  ui_story_5037_50371401_3_dialog_content = "Duh! Um grande diretor nunca perde uma oportunidade preciosa!",
  ui_story_5037_50371401_4_dialog_content = "Se você diz...",
  ui_story_5037_50371401_5_dialog_content = "Então vamos começar nosso primeiro Workshop de Curso Intensivo para Produtores.",
  ui_story_5037_50371401_6_dialog_content = "...",
  ui_story_5037_50371401_7_dialog_content = "(Há livros espalhados por todo o escritório...)",
  ui_story_5037_50371401_8_dialog_content = "(Será que Vice e Carleen realmente trouxeram tudo isso para o workshop?)",
  ui_story_5037_50371401_9_dialog_content = "(Eles parecem muito sérios... Tenho um mau pressentimento sobre isso...)",
  ui_story_5037_50371401_10_dialog_content = "Hum, por que vocês dois parecem tão sérios...?",
  ui_story_5037_50371401_11_dialog_content = "Porque é sério, PlayerName. Isso afetará se você pode ou não se tornar um produtor de sucesso.",
  ui_story_5037_50371401_12_dialog_content = "De fato. Quando se trata do seu sucesso, não podemos nos dar ao luxo de ser descuidados.",
  ui_story_5037_50371401_13_dialog_content = "Obrigado pela preocupação, mas eu sou o único responsável por isso, não vocês dois...",
  ui_story_5037_50371401_14_dialog_content = "O que você está falando? Somos parceiros, não somos? Estaremos sempre aqui para te apoiar!",
  ui_story_5037_50371401_15_dialog_content = "E para ajudá-lo a entender sua nova profissão tanto quanto possível, Vice e eu fiz nossa própria parte da pesquisa.",
  ui_story_5037_50371401_16_dialog_content = "Isso mesmo! Tudo o que você poderia querer aprender, desde ser um ídolo até ser um produtor, está nesses livros!",
  ui_story_5037_50371401_17_dialog_content = "A partir de hoje, será aqui que acontecerá o nosso Workshop Crash Course para Produtores!",
  ui_story_5037_50371401_18_dialog_content = "Espere um minuto... Estas são todas as notas e recortes de artigos?!",
  ui_story_5037_50371401_19_dialog_content = "Sim! Carleen foi à biblioteca e fez anotações sobre todos os livros relacionados a regimes de treinamento para cantores e dançarinos.",
  ui_story_5037_50371401_20_dialog_content = "Enquanto isso, comprei um exemplar de todos os jornais impressos nos últimos anos e recortei tudo que tem a ver com ídolos e produtores!",
  ui_story_5037_50371401_21_dialog_content = "Isso é assustador impressionante...",
  ui_story_5037_50371401_22_dialog_content = "Deve ter levado dias para ler todos aqueles livros e escrever essas notas...",
  ui_story_5037_50371401_23_dialog_content = "Bem, eu tive alguma ajuda de Chloe e Keating durante minha pesquisa.",
  ui_story_5037_50371401_24_dialog_content = "Ambos sabem muito mais sobre música do que eu, então eles escreveram uma grande parte dessas notas.",
  ui_story_5037_50371401_25_dialog_content = "E eu tive alguma ajuda de Brandy!",
  ui_story_5037_50371401_26_dialog_content = "Como repórter profissional, ela está realmente familiarizada com todos os tipos de notícias e eventos!",
  ui_story_5037_50371401_27_dialog_content = "Sim, tudo isso não teria sido possível sem a ajuda de todos.",
  ui_story_5037_50371401_28_dialog_content = "Sem brincadeiras...",
  ui_story_5037_50371401_29_dialog_content = "Parece que não posso me dar ao luxo de relaxar! Todos esperam muito de mim!",
  ui_story_5037_50371401_30_dialog_content = "Então vamos começar.",
  ui_story_5037_50371401_31_dialog_content = "Nossa próxima ordem de trabalho é decidir sobre um plano de treinamento para você, PlayerName!",
  ui_story_5037_50371401_32_dialog_content = "Um plano de treinamento?",
  ui_story_5037_50371401_33_dialog_content = "Sim. Desenvolvemos dois planos de treinamento diferentes para você. Nós vamos deixar você decidir qual é o mais adequado.",
  ui_story_5037_50371401_34_dialog_content = "Este se chama \"Produtores: do iniciante ao especialista\".",
  ui_story_5037_50371401_35_dialog_content = "É tão grosso!!",
  ui_story_5037_50371401_36_dialog_content = "Ele contém conhecimentos que variam em complexidade do nível rudimentar ao nível profissional. No entanto, o material é denso e exigirá mais tempo de estudo.",
  ui_story_5037_50371401_37_dialog_content = "E o outro...?",
  ui_story_5037_50371401_38_dialog_content = "Este é chamado de \"Técnicas Avançadas de Produtor\". Inclui diferentes técnicas de gerenciamento de tempo usadas por estudiosos famosos ao longo dos tempos.",
  ui_story_5037_50371401_39_dialog_content = "No entanto, este plano requer um conhecimento básico da indústria para ser bem compreendido o suficiente para ser usado.",
  ui_story_5037_50371401_40_dialog_content = "Vá em frente, PlayerName! Escolha o plano que achar melhor para você!",
  ui_story_5037_50371401_41_dialog_content = "O plano que mais me convém...",
  ui_story_5037_50371401_42_dialog_content = "Bem, ainda sou muito inexperiente como produtor, então acho que este servirá...",
  ui_story_5037_50371401_43_option_content = "\"Produtores: do iniciante ao especialista\"",
  ui_story_5037_50371401_44_dialog_content = "Se eu quiser começar com os fundamentos, este plano deve ser minha aposta mais segura!",
  ui_story_5037_50371401_45_dialog_content = "Concordo.",
  ui_story_5037_50371401_46_dialog_content = "Então está resolvido! A partir de hoje, você usará isso para ajudá-lo a aprender como ser um produtor profissional!",
  ui_story_5037_50371401_47_dialog_content = "Vou tentar o meu melhor!",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50371401_49_dialog_content = "As principais responsabilidades de um produtor... Acompanhar o progresso, desenvolver cronogramas...",
  ui_story_5037_50371401_50_dialog_content = "O que mais? Nossa, acho que já esqueci...",
  ui_story_5037_50371401_51_dialog_content = "Por que você não faz uma pausa?",
  ui_story_5037_50371401_52_dialog_content = "Você já memorizou muito. Seu próximo passo é tentar colocar esses conceitos em prática.",
  ui_story_5037_50371401_53_option_content = "\"Técnicas Avançadas de Produção\"",
  ui_story_5037_50371401_54_dialog_content = "Eu já decidi me desafiar fazendo isso, então vamos começar com as coisas difíceis!",
  ui_story_5037_50371401_55_dialog_content = "Tem certeza?!",
  ui_story_5037_50371401_56_dialog_content = "Se é assim que você deseja proceder, faremos o possível para apoiá-lo.",
  ui_story_5037_50371401_57_dialog_content = "Eu devo estar bem!",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50371401_59_dialog_content = "É tão difícil!",
  ui_story_5037_50371401_60_dialog_content = "Concordo, parece um pouco difícil...",
  ui_story_5037_50371401_61_dialog_content = "Senti o mesmo quando estava elaborando este plano... Muitos tópicos complexos estão envolvidos, todos interligados de uma forma ou de outra.",
  ui_story_5037_50371401_62_dialog_content = "Parece que terei que seguir passo a passo se quiser aprender as coisas direito.",
  ui_story_5037_50371401_63_dialog_content = "Está ficando tarde, no entanto. Vamos parar por aqui por hoje.",
  ui_story_5037_50371401_64_dialog_content = "Bom trabalho, PlayerName!",
  ui_story_5037_50371401_65_dialog_content = "Bem feito.",
  ui_story_5037_50371401_66_dialog_content = "Eu deveria ser o único a dizer isso! Tenho certeza que não foi fácil reunir todos esses materiais...",
  ui_story_5037_50371401_67_dialog_content = "Somos tão bons amigos que não há necessidade de formalidades.",
  ui_story_5037_50371401_68_dialog_content = "Volte e descanse um pouco, ok?",
  ui_story_5037_50371401_69_dialog_content = "Sim, o mesmo para vocês dois!",
  ui_story_5037_50371401_70_dialog_content = "Ainda temos alguns assuntos para resolver antes de voltarmos, então não precisam esperar por nós.",
  ui_story_5037_50371401_71_dialog_content = "Huh? Onde você está indo?",
  ui_story_5037_50371401_72_dialog_content = "Marcamos algumas entrevistas com alguns cantores aurorianos da cidade. Queremos aprender técnicas de canto com eles.",
  ui_story_5037_50371401_73_dialog_content = "Mesmo que seus estilos e origens sejam diferentes, eles ainda devem ter alguns conselhos a oferecer.",
  ui_story_5037_50371401_74_dialog_content = "Se pudermos identificar suas técnicas e apresentá-las a Goldie, tenho certeza que será de grande utilidade para ela.",
  ui_story_5037_50371401_75_dialog_content = "Mas você já fez tanto só para me ajudar!",
  ui_story_5037_50371401_76_dialog_content = "Eu sinto que se alguém precisa de descanso, são vocês dois...",
  ui_story_5037_50371401_77_dialog_content = "Não se preocupe conosco! Eu ainda me sinto acelerado e pronto para ir!",
  ui_story_5037_50371401_78_dialog_content = "Esta é uma experiência nova e emocionante para nós dois.",
  ui_story_5037_50371401_79_dialog_content = "Talvez seja por isso que não nos sentimos cansados, apesar de todo o trabalho que temos feito.",
  ui_story_5037_50371401_80_dialog_content = "Você não se sente assim às vezes, PlayerName?",
  ui_story_5037_50371401_81_dialog_content = "eu tenho, sim...",
  ui_story_5037_50371401_82_dialog_content = "Desde que comecei a trabalhar como produtor, acho que não passou um dia sem trabalhar do amanhecer ao anoitecer.",
  ui_story_5037_50371401_83_dialog_content = "Mas por causa de todos os novos desafios que enfrento todos os dias, não me sinto tão cansado quanto deveria!",
  ui_story_5037_50371401_84_dialog_content = "Parece quando saí do underground e conheci vocês.",
  ui_story_5037_50371401_85_dialog_content = "Embora os Eclipsites estivessem nos perseguindo por dias, nunca me senti cansado ou sem esperança.",
  ui_story_5037_50371401_86_dialog_content = "Esse é o tipo de emoção que uma nova aventura traz!",
  ui_story_5037_50371401_87_dialog_content = "Sim!",
  ui_story_5037_50371401_88_dialog_content = "Mas mesmo assim, não posso ficar parado enquanto vocês dois estão tão ocupados!",
  ui_story_5037_50371401_89_dialog_content = "Hã?",
  ui_story_5037_50371401_90_dialog_content = "Por quê?",
  ui_story_5037_50371401_91_dialog_content = "Porque estamos todos juntos nisso, sempre foi assim.",
  ui_story_5037_50371401_92_dialog_content = "Não importa quão longa seja a jornada ou quão perigosa seja a aventura, nós três sempre estivemos juntos.",
  ui_story_5037_50371401_93_dialog_content = "Então é por isso que estou indo com você!",
  ui_story_5037_50371401_94_dialog_content = "Mas…",
  ui_story_5037_50371401_95_dialog_content = "Não se preocupe comigo! Faremos todos o nosso melhor, como sempre fazemos.",
  ui_story_5037_50371401_96_dialog_content = "Claro! Assim como sempre fazemos!",
  ui_story_5037_50371501_1_dialog_content = "Equipe PlayerNamereunião de última hora! Três, dois, um... Ação!",
  ui_story_5037_50371501_2_dialog_content = "Desculpe estou atrasado!",
  ui_story_5037_50371501_3_dialog_content = "Tudo bem. Pelo menos você conseguiu!",
  ui_story_5037_50371501_4_dialog_content = "Huh? Onde está Goldie?",
  ui_story_5037_50371501_5_dialog_content = "Ela foi falar com Lady Sheol sobre seus próximos planos, então ela não voltará por um tempo.",
  ui_story_5037_50371501_6_dialog_content = "Ai, sério? Que pena...",
  ui_story_5037_50371501_7_dialog_content = "Por quê?",
  ui_story_5037_50371501_8_dialog_content = "Queríamos parabenizá-los por apresentarem um concerto de estreia de sucesso.",
  ui_story_5037_50371501_9_dialog_content = "Preparamos alguns drinks e guloseimas para quando você e Goldie devolvida.",
  ui_story_5037_50371501_10_dialog_content = "Uau, obrigado! E não se preocupe, trarei alguns para Goldie.",
  ui_story_5037_50371501_11_dialog_content = "Eu só queria que ela pudesse estar aqui para apreciá-los agora...",
  ui_story_5037_50371501_12_dialog_content = "Passei tanto tempo assando esses biscoitos, então queria que todos os experimentassem enquanto estavam frescos.",
  ui_story_5037_50371501_13_dialog_content = "Foram necessárias muitas tentativas para descobrir como assá-los sem queimá-los também.",
  ui_story_5037_50371501_14_dialog_content = "Parece que você realmente colocou seu coração nisso, Vice...",
  ui_story_5037_50371501_15_dialog_content = "(Esses biscoitos deveriam ter um gosto bom se ela trabalhasse tanto neles... Certo?)",
  ui_story_5037_50371501_16_dialog_content = "O tempo voa, não é? Nem acredito que o concerto de estreia já acabou.",
  ui_story_5037_50371501_17_dialog_content = "Sim... Também realizamos muitos Workshops de Cursos Intensivos para Produtores!",
  ui_story_5037_50371501_18_dialog_content = "Quando começamos a ajudar PlayerName tornar um produtor, estávamos todos tão ocupados...",
  ui_story_5037_50371501_19_dialog_content = "Mas todos os nossos esforços estão começando a valer a pena! PlayerName conseguiu ajudar Goldie a apresentar um show de estreia espetacular!",
  ui_story_5037_50371501_20_dialog_content = "Ele se tornou um produtor bastante confiável, de fato.",
  ui_story_5037_50371501_21_dialog_content = "Sem brincadeiras! Você realmente mostrou um grande progresso!",
  ui_story_5037_50371501_22_dialog_content = "Hehehe... Vocês dois vão me fazer corar! Quem deveria agradecer sou eu!",
  ui_story_5037_50371501_23_dialog_content = "Parabéns!",
  ui_story_5037_50371501_24_dialog_content = "Parabéns, PlayerName.",
  ui_story_5037_50371501_25_dialog_content = "Obrigada!",
  ui_story_5037_50371501_26_dialog_content = "Certo, agora vamos começar a festa!",
  ui_story_5037_50371501_27_dialog_content = "Mais um pouco e o chá vai esfriar!",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>Farfalhar...</color>",
  ui_story_5037_50371501_29_dialog_content = "... Algum de vocês ouviu um barulho estranho agora?",
  ui_story_5037_50371501_30_dialog_content = "Hum? Não, eu não penso assim?",
  ui_story_5037_50371501_31_dialog_content = "<color=#828282>Sussurra, sussurra——</color>",
  ui_story_5037_50371501_32_dialog_content = "Aí está de novo. Parece que vem de perto dos instrumentos musicais.",
  ui_story_5037_50371501_33_dialog_content = "Talvez fosse apenas o vento?",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>Sussurra, sussurra——</color>",
  ui_story_5037_50371501_35_dialog_content = "...",
  ui_story_5037_50371501_36_dialog_content = "Acho que tem algo escondido atrás da bateria...",
  ui_story_5037_50371501_37_dialog_content = "Poderia ser... um Eclipsite?",
  ui_story_5037_50371501_38_dialog_content = "Vou dar uma olhada mais de perto.",
  ui_story_5037_50371501_39_dialog_content = "Gelescer—",
  ui_story_5037_50371501_40_dialog_content = "Ei! Lo, lo, lo!",
  ui_story_5037_50371501_41_dialog_content = "O que...? É Kyllo!",
  ui_story_5037_50371501_42_dialog_content = "Mas o que Kyllo está fazendo aqui? Onde está Fia?",
  ui_story_5037_50371501_43_dialog_content = "Lo ... (Tradução: Fia me enviou em uma missão ultra-secreta para espionar PlayerName e os outros...)",
  ui_story_5037_50371501_44_dialog_content = "Olha, olha! (Tradução: Mas não esperava encontrar tanta gente aqui ao mesmo tempo!)",
  ui_story_5037_50371501_45_dialog_content = "Olha... Olha! (Tradução: Parece que meu disfarce foi descoberto... Tenho que dar um jeito de sair daqui, rápido!)",
  ui_story_5037_50371501_46_dialog_content = "Você não estaria nos espionando... estaria?",
  ui_story_5037_50371501_47_dialog_content = "L-Lo, lo!!",
  ui_story_5037_50371501_48_dialog_content = "Acho que está tentando negar.",
  ui_story_5037_50371501_49_dialog_content = "Faz sentido... Dado o comportamento usual de Kyllo, meu palpite é que ele se perdeu enquanto procurava algo para comer.",
  ui_story_5037_50371501_50_dialog_content = "Talvez você tenha se esgueirado até aqui porque também não aguentou mais o treinamento de Fia, Kyllo?",
  ui_story_5037_50371501_51_dialog_content = "Lo!",
  ui_story_5037_50371501_52_dialog_content = "Tenho certeza que sim.",
  ui_story_5037_50371501_53_dialog_content = "Pobre rapaz. Manter Vic na linha durante seu treinamento todos os dias deve ser exaustivo...",
  ui_story_5037_50371501_54_dialog_content = "Lo...",
  ui_story_5037_50371501_55_dialog_content = "Ele pode descansar aqui por um tempo. Temos muitos lanches para compartilhar com ele.",
  ui_story_5037_50371501_56_dialog_content = "Sim, eu concordo! Vou levá-lo de volta para Fia assim que terminarmos.",
  ui_story_5037_50371501_57_dialog_content = "Olha! Olha! (Tradução: Ótimo, parece que eles não descobriram o verdadeiro motivo de eu estar aqui!)",
  ui_story_5037_50371501_58_dialog_content = "Olha! (Tradução: eu me pergunto de que tipo de lanches eles estavam falando?)",
  ui_story_5037_50371501_59_dialog_content = "Fia mencionou que Kyllo adorava comer bolachas de animais, não foi?",
  ui_story_5037_50371501_60_dialog_content = "Não sei se meus biscoitos são tão gostosos quanto os biscoitos que você gosta, mas...",
  ui_story_5037_50371501_61_dialog_content = "(Uh-oh... eu me lembro desse sentimento!)",
  ui_story_5037_50371501_62_dialog_content = "(É o mesmo de antes!)",
  ui_story_5037_50371501_63_dialog_content = "Olha! (Tradução: E-espere um segundo! Isso é comestível?!)",
  ui_story_5037_50371501_64_dialog_content = "Aqui, Kyllo! Experimente um dos meus biscoitos recém-assados!",
  ui_story_5037_50371501_65_dialog_content = "Sei que não ficam tão bonitos como os das pastelarias Lumopolis, mas a receita é exactamente a mesma!",
  ui_story_5037_50371501_66_dialog_content = "Olha! Olha! (Tradução: S-Fique longe de mim!)",
  ui_story_5037_50371501_67_dialog_content = "Diga, ahhh—",
  ui_story_5037_50371501_68_dialog_content = "Lo!!!",
  ui_story_5037_50371501_69_dialog_content = "Kyllo está fugindo!",
  ui_story_5037_50371501_70_dialog_content = "Está correndo em direção à nossa pilha de livros!",
  ui_story_5037_50371501_71_dialog_content = "Agarre-o antes que faça uma bagunça pegajosa com eles!",
  ui_story_5037_50371501_72_dialog_content = "Vem cá, Kyllo!",
  ui_story_5037_50371501_73_dialog_content = "Lo!!!",
  ui_story_5037_50371501_74_dialog_content = "(Merda! Kyllo está tentando mergulhar na pilha de livros!)",
  ui_story_5037_50371501_75_option_content = "Proteja os livros profissionais",
  ui_story_5037_50371501_76_option_content = "Proteja as revistas",
  ui_story_5037_50371501_77_dialog_content = "<color=#828282>Wham!</color>",
  ui_story_5037_50371501_78_dialog_content = "Oof-!",
  ui_story_5037_50371501_79_dialog_content = "<size=45>Ai!!!</size>",
  ui_story_5037_50371501_80_dialog_content = "PlayerName?!",
  ui_story_5037_50371501_81_dialog_content = "Eu estou bem... Só doeu um pouco, só isso...",
  ui_story_5037_50371501_82_dialog_content = "Lo...",
  ui_story_5037_50371501_83_dialog_content = "Lo, lo, lo!",
  ui_story_5037_50371501_84_dialog_content = "Corre tão rápido!",
  ui_story_5037_50371501_85_dialog_content = "Os livros estão bem?",
  ui_story_5037_50371501_86_dialog_content = "*Tosse* Sim... Bem, uma parte deles, de qualquer maneira...",
  ui_story_5037_50371501_87_dialog_content = "Também consegui preservar algumas de nossas anotações e recortes.",
  ui_story_5037_50371501_88_dialog_content = "O resto deles parece estar completamente encharcado...",
  ui_story_5037_50371501_89_dialog_content = "Bem, não há tempo a perder. Precisamos remover todos os livros molhados primeiro.",
  ui_story_5037_50371501_90_dialog_content = "Um dois...",
  ui_story_5037_50371501_91_dialog_content = "Acho que ainda podemos lê-los se conseguirmos secá-los primeiro.",
  ui_story_5037_50371501_92_dialog_content = "Estes, por outro lado... A tinta está completamente manchada, então não podemos fazer nada para salvá-los.",
  ui_story_5037_50371501_93_dialog_content = "Acho que tem alguns livros que pegamos emprestados de outras pessoas!",
  ui_story_5037_50371501_94_dialog_content = "Não pode ser ajudado. Temos que separá-los, devolvê-los aos seus donos e oferecer nossas desculpas, bem como uma compensação.",
  ui_story_5037_50371501_95_dialog_content = "Acho que realmente não temos escolha, né?",
  ui_story_5037_50371501_96_dialog_content = "Mas não sei se tenho Nightium suficiente para cobrir os danos...",
  ui_story_5037_50371501_97_dialog_content = "Eu posso lançar também.",
  ui_story_5037_50371501_98_dialog_content = "Assim como eu. Afinal, não fui capaz de parar Kyllo, então também sou parcialmente culpado.",
  ui_story_5037_50371501_99_dialog_content = "Não se preocupe, PlayerName! Não vamos deixar você secar!",
  ui_story_5037_50371501_100_dialog_content = "Obrigado, Vice. Obrigado, Carlene.",
  ui_story_5037_50371501_101_dialog_content = "Isso deixa apenas uma última coisa a fazer.",
  ui_story_5037_50371501_102_dialog_content = "Precisamos encontrar Fia, e certifique-se de que ela disciplina Kyllo adequadamente.",
  ui_story_5037_50371601_1_dialog_content = "Equipe PlayerNameúltima reunião! Três, dois, um... Ação!",
  ui_story_5037_50371601_2_dialog_content = "Última reunião, hein? Uau, com certeza o tempo voa...",
  ui_story_5037_50371601_3_dialog_content = "Eu sei direito? Será a hora do concerto de formatura em apenas alguns dias!",
  ui_story_5037_50371601_4_dialog_content = "Parece que foi ontem que estávamos movendo todos esses livros para cá para nos prepararmos para nosso primeiro Workshop de Curso Intensivo para Produtores.",
  ui_story_5037_50371601_5_dialog_content = "Então, qual é o plano para hoje?",
  ui_story_5037_50371601_6_dialog_content = "Só temos uma tarefa importante para hoje... que é limpar o lugar!",
  ui_story_5037_50371601_7_dialog_content = "Depois de terminar cada parte do seu plano de treinamento, você se tornou um produtor talentoso e respeitável, PlayerName!",
  ui_story_5037_50371601_8_dialog_content = "O que significa que nosso Workshop de Curso Intensivo para Produtores chegou oficialmente ao fim!",
  ui_story_5037_50371601_9_dialog_content = "Na verdade, devemos reunir todos os nossos livros e materiais e devolvê-los aos seus devidos lugares hoje.",
  ui_story_5037_50371601_10_dialog_content = "Dessa forma, também podemos devolver todos os materiais que pegamos emprestados de outras pessoas para a oficina.",
  ui_story_5037_50371601_11_dialog_content = "Eu vejo. Eu também ajudo!",
  ui_story_5037_50371601_12_dialog_content = "Vamos arrumar tudo o mais rápido possível!",
  ui_story_5037_50371601_13_dialog_content = "Sim!",
  ui_story_5037_50371601_14_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50371601_15_dialog_content = "Onde devo colocar esta cópia de \"Formando bons hábitos: um guia para iniciantes\"?",
  ui_story_5037_50371601_16_dialog_content = "Aqui, me dê.",
  ui_story_5037_50371601_17_dialog_content = "A policial Vivian teve a gentileza de nos emprestar. Ela disse que seria perfeito para o seu treinamento!",
  ui_story_5037_50371601_18_dialog_content = "Ela mesma aprendeu a administrar melhor o tempo depois de lê-lo.",
  ui_story_5037_50371601_19_dialog_content = "Ela está certa, havia toneladas de informações úteis nele!",
  ui_story_5037_50371601_20_dialog_content = "PlayerName? Você poderia me passar aquela cópia de \"300 habilidades essenciais para coro\" ao seu lado?",
  ui_story_5037_50371601_21_dialog_content = "Claro, aqui está.",
  ui_story_5037_50371601_22_dialog_content = "Deixe-me adivinhar... Keating nos emprestou aquele livro, não foi?",
  ui_story_5037_50371601_23_dialog_content = "Como você sabia?",
  ui_story_5037_50371601_24_dialog_content = "Porque mesmo que a capa pareça perfeitamente limpa... Há todo tipo de rabiscos e desenhos em cada número de página.",
  ui_story_5037_50371601_25_dialog_content = "Tem até um desenho tosco meu em uma das páginas, onde eles desenharam essas olheiras grandes e escuras ao redor dos meus olhos!",
  ui_story_5037_50371601_26_dialog_content = "... Pfft.",
  ui_story_5037_50371601_27_dialog_content = "Isso soa como algo que eles fariam, sim.",
  ui_story_5037_50371601_28_dialog_content = "Se isso realmente incomoda você, vou pedir para que apaguem todos os desenhos deste livro.",
  ui_story_5037_50371601_29_dialog_content = "Isso não é realmente necessário...",
  ui_story_5037_50371601_30_dialog_content = "Se você os obrigar a fazer isso, tenho certeza de que encontrarão uma maneira ainda pior de zombar de mim.",
  ui_story_5037_50371601_31_dialog_content = "Apenas deixe estar.",
  ui_story_5037_50371601_32_dialog_content = "Essas crianças realmente sabem como irritar todo mundo.",
  ui_story_5037_50371601_33_dialog_content = "Parece que estamos quase terminando aqui, certo?",
  ui_story_5037_50371601_34_dialog_content = "Sim! Tudo está em ordem!",
  ui_story_5037_50371601_35_dialog_content = "Além de todos os livros que usamos, há também uma enorme pilha de anotações.",
  ui_story_5037_50371601_36_dialog_content = "Acumulamos todas essas notas nos últimos dias.",
  ui_story_5037_50371601_37_dialog_content = "É isso mesmo, cada página coberta de notas é uma prova de todo o nosso trabalho árduo!",
  ui_story_5037_50371601_38_dialog_content = "É realmente uma grande pilha, hein?",
  ui_story_5037_50371601_39_dialog_content = "Não parecia enquanto estávamos levando-os...",
  ui_story_5037_50371601_40_dialog_content = "mas não acredito que fizemos tantas anotações!",
  ui_story_5037_50371601_41_dialog_content = "Este é o fruto do seu conhecimento adquirido.",
  ui_story_5037_50371601_42_dialog_content = "Devo dizer que faz muito tempo desde que escrevi tantas notas... Parecia muito com o nosso tempo na academia!",
  ui_story_5037_50371601_43_dialog_content = "Indo para a aula, anotando, almoçando juntos... Foram dias tão tranquilos, né, Carleen?",
  ui_story_5037_50371601_44_dialog_content = "Exceto quando tínhamos exames chegando, é claro...",
  ui_story_5037_50371601_45_dialog_content = "Vida de estudante, né? É muito difícil para mim imaginar.",
  ui_story_5037_50371601_46_dialog_content = "Afinal, nunca frequentei a escola antes, então não sei como é.",
  ui_story_5037_50371601_47_dialog_content = "Soroz sempre foi seu professor, PlayerName?",
  ui_story_5037_50371601_48_dialog_content = "Nesse caso, seria realmente difícil imaginar estudar com outras pessoas.",
  ui_story_5037_50371601_49_dialog_content = "É muito parecido com nossas aventuras juntos. Menos os Eclipsites, é claro.",
  ui_story_5037_50371601_50_dialog_content = "devemos visitar Dawn Academia quando tivermos a chance.",
  ui_story_5037_50371601_51_dialog_content = "Você pode experimentar a vida como estudante lá, assim como experimentou a vida como produtor aqui.",
  ui_story_5037_50371601_52_dialog_content = "Claro, mas... talvez eu possa pular os exames.",
  ui_story_5037_50371601_53_dialog_content = "Temos estado tão ocupados ultimamente, estou começando a me sentir um pouco esgotado...",
  ui_story_5037_50371601_54_dialog_content = "Não quero mais pensar em concursos ou exames. Neste momento, o que mais quero é descansar um pouco!",
  ui_story_5037_50371601_55_option_content = "Mas ainda não posso descansar!",
  ui_story_5037_50371601_56_dialog_content = "Ainda tenho muito trabalho a fazer para o concerto final.",
  ui_story_5037_50371601_57_dialog_content = "Se eu começar a pegar leve agora, não vou conseguir terminar o que comecei!",
  ui_story_5037_50371601_58_dialog_content = "Você sempre encara novas experiências com tanto entusiasmo!",
  ui_story_5037_50371601_59_dialog_content = "Bem, sim... Afinal, passei 17 anos na clandestinidade...",
  ui_story_5037_50371601_60_dialog_content = "Então você deseja experimentar tudo por si mesmo, sim?",
  ui_story_5037_50371601_61_dialog_content = "Isso mesmo!",
  ui_story_5037_50371601_62_option_content = "Eu só quero deitar agora...",
  ui_story_5037_50371601_63_dialog_content = "Tudo parecia tão novo e empolgante quando me tornei produtor, mas aos poucos estou começando a me acostumar.",
  ui_story_5037_50371601_64_dialog_content = "Fazendo exatamente o mesmo trabalho, dia após dia... Fiquei tão familiarizado com o trabalho, mas não consigo deixar de me sentir um pouco entediado às vezes...",
  ui_story_5037_50371601_65_dialog_content = "Eu sei exatamente como você se sente...",
  ui_story_5037_50371601_66_dialog_content = "Mesmo as coisas mais emocionantes se tornam monótonas depois de um tempo.",
  ui_story_5037_50371601_67_dialog_content = "É por isso que devemos sempre encontrar novas maneiras de nos desafiar.",
  ui_story_5037_50371601_68_dialog_content = "Ainda assim, esta foi uma experiência valiosa!",
  ui_story_5037_50371601_69_dialog_content = "eu tenho que ajudar Goldie fazer shows, e pude estudar com vocês dois.",
  ui_story_5037_50371601_70_dialog_content = "Eu não poderia pedir uma maneira melhor de aprender e crescer como pessoa!",
  ui_story_5037_50371601_71_dialog_content = "Você provavelmente poderia fazer um nome para si mesmo se ficar aqui e continuar sendo um produtor.",
  ui_story_5037_50371601_72_dialog_content = "Qual você gosta mais? Ser produtor ou ser aventureiro?",
  ui_story_5037_50371601_73_dialog_content = "Você está brincando comigo? Minha resposta deve ser clara como o dia!",
  ui_story_5037_50371601_74_dialog_content = "!",
  ui_story_5037_50371601_75_dialog_content = "Me aventurar com vocês é o que me deixa mais feliz!",
  ui_story_5037_50371701_1_dialog_content = "Florina? Eu não estava esperando você aqui! Bem-vindo bem vindo!",
  ui_story_5037_50371701_2_dialog_content = "Se você veio ouvir Goldie cantar, receio ter que desapontá-lo. O show é daqui a alguns dias, e ela ainda está no meio do treinamento.",
  ui_story_5037_50371701_3_dialog_content = "Não estou aqui para assistir ao concerto.",
  ui_story_5037_50371701_4_dialog_content = "Hã?",
  ui_story_5037_50371701_5_dialog_content = "Estou aqui para prestar minha ajuda.",
  ui_story_5037_50371701_6_dialog_content = "Ouvi dizer que você está tentando uma nova profissão? Um produtor, eu acredito que eles chamaram isso.",
  ui_story_5037_50371701_7_dialog_content = "Vim como seu amigo para ver como você estava.",
  ui_story_5037_50371701_8_dialog_content = "Diga-me, último celestita... Há algo que eu possa fazer para ajudá-lo?",
  ui_story_5037_50371701_9_dialog_content = "Não consigo pensar em nenhum...",
  ui_story_5037_50371701_10_dialog_content = "Sério?",
  ui_story_5037_50371701_11_dialog_content = "(Hein? Por que Florine parece tão desapontada?)",
  ui_story_5037_50371701_12_dialog_content = "(É porque não preciso da ajuda dela agora...?)",
  ui_story_5037_50371701_13_dialog_content = "E-espere! Há algo que eu poderia usar uma mão com!",
  ui_story_5037_50371701_14_dialog_content = "O que foi?",
  ui_story_5037_50371701_15_dialog_content = "(O que devo dizer a ela?)",
  ui_story_5037_50371701_16_dialog_content = "(não quero desapontá-la, mas também não quero incomodá-la...)",
  ui_story_5037_50371701_17_dialog_content = "(Espere, ela não disse que costumava ser presidente do conselho estudantil? Nesse caso...)",
  ui_story_5037_50371701_18_option_content = "Peça ajuda com a música",
  ui_story_5037_50371701_19_dialog_content = "Goldie está escrevendo uma nova música, mas ainda falta o acompanhamento. Talvez você possa ajudá-la com isso?",
  ui_story_5037_50371701_20_dialog_content = "Acompanhamento musical? Desculpe, mas não sou muito familiarizado com o assunto...",
  ui_story_5037_50371701_21_dialog_content = "Embora eu seja um fã de ópera, sei apenas um pouco. Eu farei o meu melhor!",
  ui_story_5037_50371701_22_dialog_content = "Ótimo, muito obrigado!",
  ui_story_5037_50371701_23_option_content = "Peça ajuda para estudar",
  ui_story_5037_50371701_24_dialog_content = "Goldie quer que eu faça algumas críticas construtivas sobre suas performances, mas realmente não entendo o que ela está procurando.",
  ui_story_5037_50371701_25_dialog_content = "Preciso aprender o máximo possível sobre música o mais rápido possível, para poder dar a ela o feedback de que ela precisa. Alguma sugestão?",
  ui_story_5037_50371701_26_dialog_content = "Você veio para a pessoa certa! Sei tudo o que há para saber sobre o autoestudo sistematizado e estou mais do que disposto a compartilhar meu conhecimento com você!",
  ui_story_5037_50371701_27_dialog_content = "Excelente! Estou contando com você!",
  ui_story_5037_50371701_28_dialog_content = "<color=#828282>Algum tempo depois</color>",
  ui_story_5037_50371701_29_dialog_content = "... Lá! Compartilhei tudo o que sei com você.",
  ui_story_5037_50371701_30_dialog_content = "E-espere, eu ainda não entendi tudo.",
  ui_story_5037_50371701_31_dialog_content = "Deixe-me verificar minhas anotações...",
  ui_story_5037_50371701_32_dialog_content = "Você escreve notas muito detalhadas, não é? Esse é um hábito muito bom.",
  ui_story_5037_50371701_33_dialog_content = "Eu sempre esqueço as coisas, então faço muitas anotações quando estou estudando.",
  ui_story_5037_50371701_34_dialog_content = "É por isso que mantenho um diário. Nunca quero esquecer todas as coisas importantes que acontecem na minha vida, então também as escrevo.",
  ui_story_5037_50371701_35_dialog_content = "Acho que para mim, um bom caderno vale mais que mil lembranças.",
  ui_story_5037_50371701_36_dialog_content = "Então, desejo-lhe boa sorte, último celestita.",
  ui_story_5037_50371701_37_dialog_content = "Seu trabalho árduo e dedicação abrirão o caminho para o seu sucesso.",
  ui_story_5037_50371701_38_dialog_content = "Obrigado pelas palavras de incentivo, Florine!",
  ui_story_5037_50371701_39_dialog_content = "Estas não são simplesmente palavras de encorajamento.",
  ui_story_5037_50371701_40_dialog_content = "Eles não são...?",
  ui_story_5037_50371701_41_dialog_content = "Eles são o culminar de minhas próprias experiências como estudante também.",
  ui_story_5037_50371701_42_dialog_content = "Trabalho árduo e dedicação são os meios pelos quais uma pessoa comum pode realizar o extraordinário... Portanto, nunca subestime o valor do trabalho árduo.",
  ui_story_5037_50371701_43_dialog_content = "Eu vejo! E eu não vou!",
  ui_story_5037_50371701_44_dialog_content = "De qualquer forma, como é que você ainda está usando todas essas coisas da era antiga? Você não quer mudar isso?",
  ui_story_5037_50371701_45_dialog_content = "Não, na verdade não. É muito leve e confortável. E isso me lembra meus tempos de escola.",
  ui_story_5037_50371701_46_dialog_content = "Vesti-lo significa que sempre me lembro...",
  ui_story_5037_50371701_47_dialog_content = "ser mais como um estudante. Ser humilde e ter integridade. Esforce-se sempre para melhorar e torne-se um indivíduo responsável.",
  ui_story_5037_50371701_48_dialog_content = "Você poderia tentar usá-lo também, PlayerName. Tenho certeza que seria inspirador.",
  ui_story_5037_50371701_49_dialog_content = "Hum... acho que vou passar!",
  ui_story_5037_50371701_50_dialog_content = "Estou muito mais confortável em minhas próprias roupas.",
  ui_story_5037_50371701_51_dialog_content = "Bem, então, como você vai.",
  ui_story_5037_50371701_52_dialog_content = "Você ficará bem, desde que sempre faça o seu melhor e não seja preguiçoso.",
  ui_story_5037_50371701_53_dialog_content = "Tem certeza de que não é muito dura consigo mesma, Florine?",
  ui_story_5037_50371701_54_dialog_content = "Difícil comigo mesmo? Eu não acho.",
  ui_story_5037_50371701_55_dialog_content = "Eu só quero poder ajudar a todos, como a Srta. Hedy.",
  ui_story_5037_50371701_56_dialog_content = "Enquanto eu puder me tornar tão confiável quanto ela, farei o meu melhor, não importa as dificuldades que eu possa enfrentar.",
  ui_story_5037_50371701_57_dialog_content = "Ainda tenho espaço para melhorar.",
  ui_story_5037_50371701_58_dialog_content = "Eu acho que você é incrível do jeito que você é agora!",
  ui_story_5037_50371701_59_dialog_content = "Ser capaz de perseverar com tanta tenacidade o tempo todo é realmente impressionante.",
  ui_story_5037_50371701_60_dialog_content = "Eu adoraria ser mais como você.",
  ui_story_5037_50371701_61_dialog_content = "Bem, vamos trabalhar duro para nos tornarmos quem queremos ser.",
  ui_story_5037_50371701_62_dialog_content = "Negócio!",
  ui_story_5037_50371701_63_dialog_content = "Ah, mais uma coisa. Lembrar Goldie para se manter hidratada e cuidar de si mesma.",
  ui_story_5037_50371701_64_dialog_content = "Cantar por tanto tempo sobrecarrega a garganta, por isso é importante beber muita água para evitar irritações.",
  ui_story_5037_50371701_65_dialog_content = "A dança também é um exercício bastante vigoroso, portanto, a hidratação regular é fundamental.",
  ui_story_5037_50371701_66_dialog_content = "Sem problemas. Vou me certificar de lembrá-la.",
  ui_story_5037_50371701_67_dialog_content = "Não se esqueça de cuidar de você também, último Celestita.",
  ui_story_5037_50371701_68_dialog_content = "Não importa o quão ocupado seja o trabalho, você deve encontrar tempo para cuidar de si mesmo.",
  ui_story_5037_50371701_69_dialog_content = "Tá bom...",
  ui_story_5037_50371701_70_dialog_content = "Que o Deus da Luz os abençoe e alise o caminho de seus empreendimentos futuros.",
  ui_story_5037_50371701_71_dialog_content = "Sim!",
  ui_story_5037_50371801_1_dialog_content = "Ah, eu não posso perder isso! Cellulo, tire uma boa foto de Goldie, PlayerName, e eu!",
  ui_story_5037_50371801_2_dialog_content = "3... 2... 1... Ação!",
  ui_story_5037_50371801_3_dialog_content = "Oi, pessoal! É a sua intrépida diretora, Lilica!",
  ui_story_5037_50371801_4_dialog_content = "Hoje estou assumindo o papel de mentor em colaboração com Goldie e seu produtor PlayerName.",
  ui_story_5037_50371801_5_dialog_content = "Nós vamos passar por algum treinamento de artes cênicas!",
  ui_story_5037_50371801_6_dialog_content = "Diga oi para o pessoal que está assistindo em casa, Goldie, PlayerName!",
  ui_story_5037_50371801_7_dialog_content = "Olá a todos os meus fãs adoráveis por aí!",
  ui_story_5037_50371801_8_dialog_content = "Oi, pessoal...",
  ui_story_5037_50371801_9_dialog_content = "(Saber que minha performance vai ser gravada e assistida por tanta gente é realmente enervante...)",
  ui_story_5037_50371801_10_dialog_content = "Preparei um jogo especial para nos ajudar no treino de hoje!",
  ui_story_5037_50371801_11_dialog_content = "Um jogo? Incrível, adoro jogos!",
  ui_story_5037_50371801_12_dialog_content = "Que tipo de jogo é?",
  ui_story_5037_50371801_13_dialog_content = "Chama-se \"Charadas\".",
  ui_story_5037_50371801_14_dialog_content = "O figurino, a maquiagem, as falas e a expressão de uma pessoa afetam o resultado de sua performance.",
  ui_story_5037_50371801_15_dialog_content = "O que um ator pode fazer é aprofundar sua compreensão do personagem tanto quanto possível e certificar-se de que suas maneiras e suas falas se encaixam!",
  ui_story_5037_50371801_16_dialog_content = "Parece correto!",
  ui_story_5037_50371801_17_dialog_content = "Observei muitos de seus companheiros e escrevi algumas linhas com base em suas características individuais.",
  ui_story_5037_50371801_18_dialog_content = "Durante o jogo, Goldie vai escolher um deles e imitar seus maneirismos.",
  ui_story_5037_50371801_19_dialog_content = "Então, PlayerName, você vai adivinhar quem Goldie está imitando!",
  ui_story_5037_50371801_20_dialog_content = "A performance dela será considerada um sucesso se você acertar!",
  ui_story_5037_50371801_21_dialog_content = "Parece divertido!",
  ui_story_5037_50371801_22_dialog_content = "Entendi!",
  ui_story_5037_50371801_23_dialog_content = "Já que Goldie é uma novata, faremos de múltipla escolha. Você apenas tem que escolher a resposta certa.",
  ui_story_5037_50371801_24_dialog_content = "De qualquer forma, tenho certeza que não será muito difícil, então vamos nos divertir!",
  ui_story_5037_50371801_25_dialog_content = "Vamos!",
  ui_story_5037_50371801_26_dialog_content = "Apenas espere pelo meu desempenho!",
  ui_story_5037_50371801_27_dialog_content = "Goldie, selecione alguém desta lista. Então o palco é seu.",
  ui_story_5037_50371801_28_dialog_content = "Ok... Este!",
  ui_story_5037_50371801_29_dialog_content = "vou começar, PlayerName.",
  ui_story_5037_50371801_30_dialog_content = "\"Ei, garoto!\"",
  ui_story_5037_50371801_31_dialog_content = "(Esse tom soa muito familiar...!)",
  ui_story_5037_50371801_32_dialog_content = "\"Pronto para ir caçar algo comigo?\"",
  ui_story_5037_50371801_33_dialog_content = "Pronto para adivinhar quem Goldie está representando, PlayerName?",
  ui_story_5037_50371801_34_option_content = "Barton?",
  ui_story_5037_50371801_35_dialog_content = "Ohhh, isso está perto, mas não está certo!",
  ui_story_5037_50371801_36_dialog_content = "A resposta correta é... Sinsa!",
  ui_story_5037_50371801_37_dialog_content = "Não acredito que entendi errado.",
  ui_story_5037_50371801_38_dialog_content = "Foi minha atuação? Farei melhor da próxima vez!",
  ui_story_5037_50371801_39_option_content = "Sinsa?",
  ui_story_5037_50371801_40_dialog_content = "Correto!",
  ui_story_5037_50371801_41_dialog_content = "Parece que o desempenho de Goldie foi muito convincente!",
  ui_story_5037_50371801_42_dialog_content = "Realmente foi! Foi totalmente como Sinsa!",
  ui_story_5037_50371801_43_dialog_content = "Eu poderia jurar que você estava prestes a puxar uma grande chave inglesa...",
  ui_story_5037_50371801_44_dialog_content = "Uh... vou levar isso como um elogio?",
  ui_story_5037_50371801_45_option_content = "Cleken?",
  ui_story_5037_50371801_46_dialog_content = "Isso é... totalmente errado!",
  ui_story_5037_50371801_47_dialog_content = "A resposta correta é... Sinsa!",
  ui_story_5037_50371801_48_dialog_content = "Você tem que assistir o desempenho de Goldie com mais cuidado, PlayerName!",
  ui_story_5037_50371801_49_dialog_content = "D-Desculpe...",
  ui_story_5037_50371801_50_dialog_content = "Eu deveria me esforçar mais também!",
  ui_story_5037_50371801_51_dialog_content = "Estamos aumentando a dificuldade para este próximo!",
  ui_story_5037_50371801_52_dialog_content = "Goldie, vamos ver se você imita essa pessoa!",
  ui_story_5037_50371801_53_dialog_content = "Nossa... Eles são bem diferentes de mim, mas vou dar o meu melhor!",
  ui_story_5037_50371801_54_dialog_content = "\"O que você está fazendo, jovem?\"",
  ui_story_5037_50371801_55_dialog_content = "(Quem ela está interpretando desta vez...?)",
  ui_story_5037_50371801_56_dialog_content = "\"Você poderia trazer meu chá para o meu quarto, se você tiver um minuto? Estou com preguiça de ir buscá-lo eu mesmo.\"",
  ui_story_5037_50371801_57_dialog_content = "Dê um palpite, PlayerName!",
  ui_story_5037_50371801_58_option_content = "Migard?",
  ui_story_5037_50371801_59_dialog_content = "Correto!",
  ui_story_5037_50371801_60_dialog_content = "Isso realmente foi muito difícil...",
  ui_story_5037_50371801_61_dialog_content = "Foi difícil para mim também. Seu porte e maneirismos são muito difíceis de expressar.",
  ui_story_5037_50371801_62_dialog_content = "Eu acertei embora! Acho que isso mostra que a performance de Goldie foi um sucesso!",
  ui_story_5037_50371801_63_option_content = "O senhor da cidade?",
  ui_story_5037_50371801_64_dialog_content = "Bem, do ponto de vista da idade, ele certamente poderia chamá-lo de jovem...",
  ui_story_5037_50371801_65_dialog_content = "Mas a resposta correta é Migard!",
  ui_story_5037_50371801_66_dialog_content = "preciso me esforçar mais...",
  ui_story_5037_50371801_67_dialog_content = "Não, talvez eu precise prestar mais atenção...",
  ui_story_5037_50371801_68_option_content = "Tweety?",
  ui_story_5037_50371801_69_dialog_content = "Não! Como pôde Tweety chamá-lo de jovem quando ela ainda é tão jovem?!",
  ui_story_5037_50371801_70_dialog_content = "A resposta correta é Migard!",
  ui_story_5037_50371801_71_dialog_content = "Mesmo sendo uma mulher linda, ela ainda tem muitos maneirismos de um homem velho...",
  ui_story_5037_50371801_72_dialog_content = "Eu-De fato...",
  ui_story_5037_50371801_73_dialog_content = "Eu sempre sinto que estou sendo examinado quando a vejo!",
  ui_story_5037_50371801_74_dialog_content = "Vamos nos esforçar mais para o próximo, PlayerName!",
  ui_story_5037_50371801_75_dialog_content = "Em seguida, nosso desafio final!",
  ui_story_5037_50371801_76_dialog_content = "Goldie, por favor, torne-se esta pessoa!",
  ui_story_5037_50371801_77_dialog_content = "Huh?! I-está tudo bem?",
  ui_story_5037_50371801_78_dialog_content = "É claro! Você é livre para agir como achar melhor!",
  ui_story_5037_50371801_79_dialog_content = "Tudo bem... Aqui vou eu!",
  ui_story_5037_50371801_80_dialog_content = "\"PlayerName...\"",
  ui_story_5037_50371801_81_dialog_content = "(Ela já começou?!)",
  ui_story_5037_50371801_82_dialog_content = "\"Vamos dar tudo de nós hoje também!\"",
  ui_story_5037_50371801_83_dialog_content = "Tudo bem, PlayerName. Qual é o seu palpite?",
  ui_story_5037_50371801_84_option_content = "Lili?",
  ui_story_5037_50371801_85_dialog_content = "Ele se parecia Lilica! Mas não é ela.",
  ui_story_5037_50371801_86_dialog_content = "Não é? Sério?",
  ui_story_5037_50371801_87_dialog_content = "A resposta está bem diante dos seus olhos, PlayerName!",
  ui_story_5037_50371801_88_dialog_content = "Você estava... agindo sozinho?!",
  ui_story_5037_50371801_89_dialog_content = "Correto!",
  ui_story_5037_50371801_90_option_content = "Goldie?",
  ui_story_5037_50371801_91_dialog_content = "Bingo!",
  ui_story_5037_50371801_92_dialog_content = "Eu realmente não esperava que você acertasse!",
  ui_story_5037_50371801_93_dialog_content = "Parecia tão enérgico, como você costuma ser.",
  ui_story_5037_50371801_94_dialog_content = "Estou apenas um pouco confuso por que você a usou?",
  ui_story_5037_50371801_95_dialog_content = "A própria percepção do produtor sobre o desempenho de seu ator influenciará seu treinamento.",
  ui_story_5037_50371801_96_dialog_content = "Além de entender os papéis, os melhores produtores também têm outra habilidade...",
  ui_story_5037_50371801_97_dialog_content = "Eles conhecem as características e pontos fortes de seus próprios atores!",
  ui_story_5037_50371801_98_dialog_content = "Só isso permite um treinamento personalizado e direcionado.",
  ui_story_5037_50371801_99_dialog_content = "Portanto, esse desafio final foi realmente um teste para você!",
  ui_story_5037_50371801_100_dialog_content = "Então era disso que se tratava! Eu entendo agora.",
  ui_story_5037_50371801_101_dialog_content = "Eu aprendi muito também!",
  ui_story_5037_50371801_102_dialog_content = "Existem tantas diferenças entre cada função. Tenho que continuar trabalhando duro!",
  ui_story_5037_50371801_103_dialog_content = "É isso no treino de hoje! Desejamos a ambos o melhor!",
  ui_story_5037_50371801_104_dialog_content = "Não se esqueça de colocar em prática o que aprendeu hoje!",
  ui_story_5037_50371801_105_dialog_content = "Sim!",
  ui_story_5037_50371801_106_dialog_content = "Sim, Diretora Lilica!",
  ui_story_5037_50371901_1_dialog_content = "Então, como é exatamente uma sacerdotisa da Ilha das Nuvens?",
  ui_story_5037_50371901_2_dialog_content = "Ouvi dizer que as sacerdotisas são dançarinas incríveis, graciosas e misteriosas, e também altamente habilidosas em Luminatics.",
  ui_story_5037_50371901_3_dialog_content = "Minha imaginação está apenas correndo solta!",
  ui_story_5037_50371901_4_dialog_content = "Você verá por si mesmo muito em breve!",
  ui_story_5037_50371901_5_dialog_content = "Consegui arranjar um tempo para vir ao seu Colosso só para esta reunião!",
  ui_story_5037_50371901_6_dialog_content = "Meu coração disparou no segundo em que soube que tinha a chance de pedir dicas de dança a uma sacerdotisa de verdade!",
  ui_story_5037_50371901_7_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_8_dialog_content = "Minhas desculpas por fazer vocês dois esperarem.",
  ui_story_5037_50371901_9_dialog_content = "De jeito nenhum! Estou muito grato por você ter vindo de Cloud Island para nos treinar!",
  ui_story_5037_50371901_10_dialog_content = "Você deve ser Goldie, certo?",
  ui_story_5037_50371901_11_dialog_content = "Sim! Olá Rinne, Eu sou Goldie, um ídolo.",
  ui_story_5037_50371901_12_dialog_content = "Olá, Goldie. Sou Rinne, uma sacerdotisa de Cloud Island.",
  ui_story_5037_50371901_13_dialog_content = "Um ídolo é o mesmo que um cantor?",
  ui_story_5037_50371901_14_dialog_content = "Existem algumas diferenças. Além de cantar, também preciso aprender outras habilidades, como dançar e atuar!",
  ui_story_5037_50371901_15_dialog_content = "Eu vejo. E é por isso que você deseja aprender a dança kagura?",
  ui_story_5037_50371901_16_dialog_content = "Sim! Você pode me ensinar, Rinne?",
  ui_story_5037_50371901_17_dialog_content = "É claro! Por que não danço para você agora, como uma pequena demonstração?",
  ui_story_5037_50371901_18_dialog_content = "Realmente?! Oh sim! Eu não posso acreditar que realmente testemunhei uma sacerdotisa fazendo uma dança kagura!",
  ui_story_5037_50371901_19_dialog_content = "Hehe...",
  ui_story_5037_50371901_20_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_21_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_22_dialog_content = "Esplêndido...",
  ui_story_5037_50371901_23_dialog_content = "O som dos sinos e a visão da dança de Rinne me enchem de serenidade...",
  ui_story_5037_50371901_24_dialog_content = "Estes são apenas alguns dos passos básicos do kagura. Você gostaria de dar uma chance, Goldie?",
  ui_story_5037_50371901_25_dialog_content = "Sim!",
  ui_story_5037_50371901_26_dialog_content = "Isto está certo?",
  ui_story_5037_50371901_27_dialog_content = "Bom trabalho. Você tem os movimentos perfeitos!",
  ui_story_5037_50371901_28_dialog_content = "Estou bastante confiante em minhas habilidades de espelhamento!",
  ui_story_5037_50371901_29_dialog_content = "Mas ainda assim, não posso deixar de sentir que meu kagura está perdendo alguma coisa...",
  ui_story_5037_50371901_30_dialog_content = "É verdade que não dá a mesma sensação calmante que a de Rinne.",
  ui_story_5037_50371901_31_dialog_content = "Perder Rinne, você usa algum tipo de Luminatics especial quando dança?",
  ui_story_5037_50371901_32_dialog_content = "De jeito nenhum. Não estou usando nenhum Luminatics. É só dança, nada mais.",
  ui_story_5037_50371901_33_dialog_content = "Então, o que exatamente estou fazendo de diferente?",
  ui_story_5037_50371901_34_dialog_content = "May Eu pergunto o que você estava pensando enquanto dançava?",
  ui_story_5037_50371901_35_dialog_content = "O que eu estava pensando...?",
  ui_story_5037_50371901_36_dialog_content = "Muitas coisas, como se meus movimentos estivessem certos e o que vem a seguir...",
  ui_story_5037_50371901_37_dialog_content = "Foi a minha primeira vez dançando kagura, então eu estava preocupada em acertar.",
  ui_story_5037_50371901_38_dialog_content = "Ahh... Talvez seja essa a origem do problema.",
  ui_story_5037_50371901_39_dialog_content = "Kagura é uma dança para os deuses. Quando você se move, seus pensamentos devem estar apenas com o divino.",
  ui_story_5037_50371901_40_dialog_content = "Só então seu coração pode ser expresso através da dança.",
  ui_story_5037_50371901_41_dialog_content = "Oh...! Tudo bem, acho que entendi!",
  ui_story_5037_50371901_42_dialog_content = "Que rápido!",
  ui_story_5037_50371901_43_dialog_content = "É meio parecido com o que eu costumo fazer!",
  ui_story_5037_50371901_44_dialog_content = "Meus fãs são as únicas coisas em que penso quando estou cantando ou dançando, e o quanto espero estar trazendo alegria para eles.",
  ui_story_5037_50371901_45_dialog_content = "Quando estou na zona assim, meus vocais e movimentos parecem fluir quase sem esforço.",
  ui_story_5037_50371901_46_dialog_content = "As danças podem ser diferentes, mas algumas coisas são as mesmas.",
  ui_story_5037_50371901_47_dialog_content = "Você tentaria a dança novamente, tendo tudo isso em mente?",
  ui_story_5037_50371901_48_dialog_content = "Sim!",
  ui_story_5037_50371901_49_dialog_content = "Pense apenas nos meus fãs...",
  ui_story_5037_50371901_50_dialog_content = "(Isso é incrível! É uma vibração totalmente diferente em comparação com a primeira vez!)",
  ui_story_5037_50371901_51_dialog_content = "(Mas ainda parece haver algumas diferenças entre a dança de Goldie e a de Rinne.)",
  ui_story_5037_50371901_52_dialog_content = "O que você acha, Rinne? PlayerName?",
  ui_story_5037_50371901_53_option_content = "É muito mais parecido com o de Rinne!",
  ui_story_5037_50371901_54_dialog_content = "Sério? Que ótimo!",
  ui_story_5037_50371901_55_dialog_content = "Hmm... Ainda existem algumas diferenças.",
  ui_story_5037_50371901_56_dialog_content = "Ah?",
  ui_story_5037_50371901_57_option_content = "Sua versão da dança tem seu próprio charme!",
  ui_story_5037_50371901_58_dialog_content = "Ah?",
  ui_story_5037_50371901_59_dialog_content = "Sua dança parecia um pouco mais animada, um pouco mais leve.",
  ui_story_5037_50371901_60_dialog_content = "Goldie e eu estou dançando para pessoas diferentes, afinal.",
  ui_story_5037_50371901_61_dialog_content = "A dança de Goldie é para um público entusiasmado e apaixonado.",
  ui_story_5037_50371901_62_dialog_content = "Movimentos idênticos podem transmitir emoções muito diferentes de acordo com cada indivíduo.",
  ui_story_5037_50371901_63_dialog_content = "Isso não é uma coisa ruim e é totalmente natural, então não há necessidade de se preocupar com isso.",
  ui_story_5037_50371901_64_dialog_content = "Sua mente e seus movimentos são apenas seus.",
  ui_story_5037_50371901_65_dialog_content = "Beleza!",
  ui_story_5037_50371901_66_dialog_content = "Obrigado por sua orientação!",
  ui_story_5037_50372001_1_dialog_content = "Já que estamos em outro lugar hoje, preciso começar a filmar. Cuidado com suas expressões, pessoal.",
  ui_story_5037_50372001_2_dialog_content = "3... 2... 1... Ação!",
  ui_story_5037_50372001_3_dialog_content = "Estamos rolando? *Tosse*...",
  ui_story_5037_50372001_4_dialog_content = "Minha aula de canto começa agora.",
  ui_story_5037_50372001_5_dialog_content = "Olá, Niña!",
  ui_story_5037_50372001_6_dialog_content = "Estou um pouco confuso...",
  ui_story_5037_50372001_7_dialog_content = "Não deveríamos ter treinamento vocal agora? O que estamos fazendo na sala de concertos?",
  ui_story_5037_50372001_8_dialog_content = "Uma excelente pergunta, PlayerName.",
  ui_story_5037_50372001_9_dialog_content = "Esta lição não será ativa, mas passiva. Hoje estamos ouvindo.",
  ui_story_5037_50372001_10_dialog_content = "Ouvindo...?",
  ui_story_5037_50372001_11_dialog_content = "Ouvir as músicas de outros artistas é uma parte importante do treinamento de um ídolo!",
  ui_story_5037_50372001_12_dialog_content = "Precisamos saber do que os fãs gostam atualmente se quisermos fazer música que as pessoas queiram ouvir.",
  ui_story_5037_50372001_13_dialog_content = "Sim! Conheça a tendência, siga a tendência e lidere a tendência. Esta é a força vital da indústria!",
  ui_story_5037_50372001_14_dialog_content = "Então, hoje vamos ouvir um musical chamado \"Fantasma do Teatro\".",
  ui_story_5037_50372001_15_dialog_content = "Conta a história de um ator de teatro imortal.",
  ui_story_5037_50372001_16_dialog_content = "As jogadas de mudança executadas fornecem uma linha mestra que une cada era de Umbraton.",
  ui_story_5037_50372001_17_dialog_content = "Isso é incrível!",
  ui_story_5037_50372001_18_dialog_content = "Afinal, a cultura popular é um reflexo do zeitgeist!",
  ui_story_5037_50372001_19_dialog_content = "Excelente, dez pontos para Goldie.",
  ui_story_5037_50372001_20_dialog_content = "Distribua o material, por favor, Minos.",
  ui_story_5037_50372001_21_dialog_content = "Sim senhorita.",
  ui_story_5037_50372001_22_dialog_content = "O que é isso...?",
  ui_story_5037_50372001_23_dialog_content = "A senhorita preparou isso especialmente ela mesma. Ele lista todas as canções e óperas populares de Umbraton na última década.",
  ui_story_5037_50372001_24_dialog_content = "Certifique-se de cuidar dele.",
  ui_story_5037_50372001_25_dialog_content = "T-Tá...",
  ui_story_5037_50372001_26_dialog_content = "Nesta aula, você aprenderá sobre cada uma dessas canções, bem como as tendências em Umbraton nos últimos dez anos.",
  ui_story_5037_50372001_27_dialog_content = "Isso deve refinar seu gosto e ajudá-lo a gravar mais músicas da moda.",
  ui_story_5037_50372001_28_dialog_content = "Nina, agradeço seus esforços, mas...",
  ui_story_5037_50372001_29_dialog_content = "Certamente isso é demais?!",
  ui_story_5037_50372001_30_dialog_content = "Você não pode esperar que nós os leiamos todos hoje?",
  ui_story_5037_50372001_31_dialog_content = "Ler todos eles? Não, claro que não! Eu nunca definiria uma tarefa tão impossível. Dificilmente seria razoável.",
  ui_story_5037_50372001_32_dialog_content = "Cada uma dessas músicas será referenciada no que estamos assistindo hoje.",
  ui_story_5037_50372001_33_dialog_content = "Você pode consultar a lista abrangente que montei para obter uma compreensão mais profunda de como a cultura pop diferia entre as épocas.",
  ui_story_5037_50372001_34_dialog_content = "Muito obrigado!",
  ui_story_5037_50372001_35_dialog_content = "Vamos estudá-lo de perto!",
  ui_story_5037_50372001_36_dialog_content = "A apresentação está prestes a começar, então devemos nos apressar e nos sentar.",
  ui_story_5037_50372001_37_dialog_content = "Por aqui, todos.",
  ui_story_5037_50372001_38_dialog_content = "A senhorita gentilmente providenciou assentos VIP para você.",
  ui_story_5037_50372001_39_dialog_content = "Uau, tão perto do palco! Provavelmente temos a melhor visão da performance em todo o lugar!",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>...</color>",
  ui_story_5037_50372001_41_dialog_content = "\"Tempos felizes, música bonita... Todos são passageiros.\"",
  ui_story_5037_50372001_42_dialog_content = "\"Bela senhora, você poderia me dar a honra de uma dança?\"",
  ui_story_5037_50372001_43_dialog_content = "Esta é \"Kleo e Jessica\", uma das primeiras peças de Umbraton.",
  ui_story_5037_50372001_44_dialog_content = "Eu conheço este! Ouvi a história quando era criança, adaptada da peça!",
  ui_story_5037_50372001_45_dialog_content = "Conta a trágica história de dois aurorianos de famílias rivais que se apaixonam.",
  ui_story_5037_50372001_46_dialog_content = "Isso mesmo. Como você pode ver, durante este tempo, a cultura Umbraton foi fortemente influenciada por Lumopolis.",
  ui_story_5037_50372001_47_dialog_content = "Podemos aprender muito sobre a vida e os hábitos dos Nobres Lumo contemporâneos com isso, como...",
  ui_story_5037_50372001_48_dialog_content = "(Nina e Goldie estão realmente se dando bem.)",
  ui_story_5037_50372001_49_dialog_content = "(A peça é boa, mas não sei muito sobre a história de Lumopolis ou Umbraton...)",
  ui_story_5037_50372001_50_dialog_content = "(estou com sono... não consigo evitar, assistir algo que realmente não entendo só me faz bocejar...)",
  ui_story_5037_50372001_51_dialog_content = "(Mas Nina se deu ao trabalho de arranjar tudo isso...)",
  ui_story_5037_50372001_52_option_content = "Não ceda ao cansaço.",
  ui_story_5037_50372001_53_dialog_content = "(Não, não consigo dormir. Tenho que ver isso até o fim!)",
  ui_story_5037_50372001_54_dialog_content = "(Este é um material de referência inestimável!)",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>Depois de ficar meticulosamente acordado até o final da apresentação</color>",
  ui_story_5037_50372001_56_dialog_content = "Eu não tinha absolutamente nenhuma ideia de quão complicado era o desenvolvimento cultural de Umbraton até agora!",
  ui_story_5037_50372001_57_dialog_content = "Eu aprendi muito também!",
  ui_story_5037_50372001_58_dialog_content = "Mesmo que eu não estivesse familiarizado com o conteúdo...",
  ui_story_5037_50372001_59_dialog_content = "Não se preocupe! Já destaquei os pontos pertinentes no material.",
  ui_story_5037_50372001_60_dialog_content = "Você pode folhear para atualizar suas memórias sempre que quiser.",
  ui_story_5037_50372001_61_dialog_content = "Uau, obrigado novamente por reservar um tempo para fazer isso por nós, Nina!",
  ui_story_5037_50372001_62_option_content = "Entregue-se ao sono.",
  ui_story_5037_50372001_63_dialog_content = "(Tenho que ficar acordado... Tenho que ficar... Zzzz...)",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>Quem sabe quanto tempo depois...</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName? PlayerName!",
  ui_story_5037_50372001_66_dialog_content = "Deixe-me tentar, Srta. Goldie.",
  ui_story_5037_50372001_67_dialog_content = "Por favor, acorde, PlayerName!",
  ui_story_5037_50372001_68_dialog_content = "Eh?!",
  ui_story_5037_50372001_69_dialog_content = "Por que você está dormindo? O show já acabou.",
  ui_story_5037_50372001_70_dialog_content = "O que? Acabou?!",
  ui_story_5037_50372001_71_dialog_content = "Eu estava muito absorto em explicar as coisas para Goldie que eu nem percebi que você tinha adormecido...",
  ui_story_5037_50372001_72_dialog_content = "É terrivelmente ofensivo desprezar a gentileza da senhorita...",
  ui_story_5037_50372001_73_dialog_content = "Eu sinto Muito!",
  ui_story_5037_50372001_74_dialog_content = "Foi erro meu...",
  ui_story_5037_50372001_75_dialog_content = "Está tudo bem.",
  ui_story_5037_50372001_76_dialog_content = "É uma pena que você tenha perdido a chance de aumentar seus conhecimentos enquanto desfruta de uma apresentação.",
  ui_story_5037_50372001_77_dialog_content = "Mas, para sua sorte, já destaquei os pontos pertinentes no material.",
  ui_story_5037_50372001_78_dialog_content = "Você pegará algumas coisas, desde que realmente as revise.",
  ui_story_5037_50372001_79_dialog_content = "Vou ler tudo com super atenção! E não vai adormecer!",
  ui_story_5037_50372001_80_dialog_content = "Espero que todos tenham ganhado algo com essa performance.",
  ui_story_5037_50372001_81_dialog_content = "Saber o que o público quer é a chave da cultura popular. Você não pode simplesmente enterrar a cabeça na areia e ignorá-la.",
  ui_story_5037_50372001_82_dialog_content = "Esta é toda a ajuda que posso oferecer a você. A partir daqui, cabe a vocês dois se esforçarem.",
  ui_story_5037_50372001_83_dialog_content = "Obrigado, Dona Nina, Minos!",
  ui_story_5037_50372001_84_dialog_content = "Sim, obrigado!",
  ui_story_5037_50372101_1_dialog_content = "Fleur, obrigado por orientar Goldie e eu—",
  ui_story_5037_50372101_2_dialog_content = "Shhh!",
  ui_story_5037_50372101_3_dialog_content = "Eh? Por que você está encostada na porta, Fleur?",
  ui_story_5037_50372101_4_dialog_content = "Por favor, PlayerName, Goldie... Devo incomodá-lo para ficar quieto por um segundo ...",
  ui_story_5037_50372101_5_dialog_content = "...",
  ui_story_5037_50372101_6_dialog_content = "...",
  ui_story_5037_50372101_7_dialog_content = "Ufa... Parece que aqueles caras sumiram.",
  ui_story_5037_50372101_8_dialog_content = "Não me diga que você se meteu em encrenca de novo?",
  ui_story_5037_50372101_9_dialog_content = "Bom...",
  ui_story_5037_50372101_10_dialog_content = "Quero dizer, no caminho para cá, eu disse oi para algumas pessoas que já ajudei...",
  ui_story_5037_50372101_11_dialog_content = "Olá.",
  ui_story_5037_50372101_12_dialog_content = "Huh? Ora, se não é Fleur! Muito obrigado pela ajuda no outro dia!",
  ui_story_5037_50372101_13_dialog_content = "Mas então, depois de ouvir meu nome, mais e mais pessoas vieram...",
  ui_story_5037_50372101_14_dialog_content = "O que? Fleur está aqui? Eu realmente te devo uma pela última vez!",
  ui_story_5037_50372101_15_dialog_content = "flor!! sou muito fã!!!",
  ui_story_5037_50372101_16_dialog_content = "Levei séculos para escapar da multidão de fãs adoráveis. Eu até tive que pegar o caminho mais longo só para ter certeza de que ninguém estava me seguindo...",
  ui_story_5037_50372101_17_dialog_content = "Às vezes é um incômodo ser tão popular...",
  ui_story_5037_50372101_18_dialog_content = "Estou com tanto ciúme, gostaria de ser tão popular quanto você!",
  ui_story_5037_50372101_19_dialog_content = "É realmente muito desgastante.",
  ui_story_5037_50372101_20_dialog_content = "Isso não me incomodaria em nada!",
  ui_story_5037_50372101_21_dialog_content = "Seria incrível atrair mais fãs para curtir minha dança e canto!",
  ui_story_5037_50372101_22_dialog_content = "Se é isso que você quer, não tenho objeções.",
  ui_story_5037_50372101_23_dialog_content = "É que só sou popular graças à minha constituição especial.",
  ui_story_5037_50372101_24_dialog_content = "Não é apenas algo que pode ser ensinado...",
  ui_story_5037_50372101_25_dialog_content = "Sério?",
  ui_story_5037_50372101_26_dialog_content = "E, para ser sincero, também não sei exatamente como alguém se torna popular.",
  ui_story_5037_50372101_27_dialog_content = "Graças à minha peculiaridade, passo a maior parte do tempo estudando como passar despercebido ou até mesmo antipático.",
  ui_story_5037_50372101_28_dialog_content = "Não acredito...",
  ui_story_5037_50372101_29_dialog_content = "O que nós devemos fazer então?",
  ui_story_5037_50372101_30_dialog_content = "Eu sei!",
  ui_story_5037_50372101_31_dialog_content = "Você veio com alguma coisa?",
  ui_story_5037_50372101_32_dialog_content = "Bem, já que Fleur já pensou muito sobre como se tornar impopular, por que não fazemos o contrário?",
  ui_story_5037_50372101_33_dialog_content = "Você quer dizer, fazer com que Fleur lhe ensine suas táticas e depois invertê-las?",
  ui_story_5037_50372101_34_dialog_content = "Então transformar o método de impopularidade em um método de popularidade?",
  ui_story_5037_50372101_35_dialog_content = "Correto! É por isso que você é meu produtor, você entende tão rápido!",
  ui_story_5037_50372101_36_dialog_content = "Você realmente acha que isso vai funcionar?",
  ui_story_5037_50372101_37_dialog_content = "Nunca saberemos se não tentarmos, certo? Você me ensinaria, Fleur? Por favor?",
  ui_story_5037_50372101_38_dialog_content = "Ok... Vocês querem aprender como ser discretos ou como ser odiados ativamente?",
  ui_story_5037_50372101_39_dialog_content = "O que você acha, PlayerName?",
  ui_story_5037_50372101_40_dialog_content = "(Já que estaremos invertendo isso, com certeza quanto mais as pessoas não gostarem de você, mais elas vão gostar de você quando invertido?)",
  ui_story_5037_50372101_41_option_content = "Como ser discreto",
  ui_story_5037_50372101_42_dialog_content = "Tornar-se discreto é bastante simples: o truque é apenas ser como as outras pessoas.",
  ui_story_5037_50372101_43_dialog_content = "Tudo o que você precisa fazer é agir como os outros enquanto esconde quaisquer características distintivas que o destaquem, e é isso!",
  ui_story_5037_50372101_44_dialog_content = "Você faz parecer fácil!",
  ui_story_5037_50372101_45_dialog_content = "Você geralmente não chamará a atenção se usar roupas comuns e chatas e andar de cabeça baixa.",
  ui_story_5037_50372101_46_dialog_content = "Algumas pessoas até usam chapéus, o que pode ajudar a esconder o rosto!",
  ui_story_5037_50372101_47_dialog_content = "Então o contrário disso seria... Andar de cabeça erguida, me exibindo cantando e dançando?",
  ui_story_5037_50372101_48_dialog_content = "Parece um pouco estranho, mas como você canta e dança muito bem...",
  ui_story_5037_50372101_49_dialog_content = "Deve ser o suficiente, certo?",
  ui_story_5037_50372101_50_option_content = "Como não gostar",
  ui_story_5037_50372101_51_dialog_content = "É um pouco complicado fazer com que as pessoas não gostem de você.",
  ui_story_5037_50372101_52_dialog_content = "Eu tentei muitas coisas diferentes, como me esgueirar de forma suspeita, vestir-me com trapos ou sujar meu rosto.",
  ui_story_5037_50372101_53_dialog_content = "Tive algum sucesso, embora tenha sido confundido com um ladrão algumas vezes...",
  ui_story_5037_50372101_54_dialog_content = "Mas por causa do meu problema particular, uma vez que as pessoas vissem quem eu realmente era, nenhum subterfúgio funcionaria.",
  ui_story_5037_50372101_55_dialog_content = "Eu entendi.",
  ui_story_5037_50372101_56_dialog_content = "Então o oposto seria ter uma postura digna, vestir-se bem e ficar bem, certo?",
  ui_story_5037_50372101_57_dialog_content = "E sempre sendo positivo e exibindo um sorriso de ídolo onde quer que eu vá!",
  ui_story_5037_50372101_58_dialog_content = "Isso tem que funcionar!",
  ui_story_5037_50372101_59_dialog_content = "Não se esqueça de que seu rumo é um fator importante em qualquer método que você usar.",
  ui_story_5037_50372101_60_dialog_content = "Você é uma excelente dançarina, Goldie, então já deveria saber disso.",
  ui_story_5037_50372101_61_dialog_content = "Totalmente! O porte e a postura são cruciais ao dançar. A diferença entre ficar de pé e ter as costas curvadas quando você dança é extrema.",
  ui_story_5037_50372101_62_dialog_content = "De qualquer forma, muito obrigado, Fleur!",
  ui_story_5037_50372101_63_dialog_content = "O prazer é meu. Se houver mais alguma coisa em que eu possa ajudar, não hesite em me avisar.",
  ui_story_5037_50372101_64_dialog_content = "Aposto que parte do motivo pelo qual você é tão popular é que está sempre disposto a ajudar as pessoas.",
  ui_story_5037_50372101_65_dialog_content = "V-você acha??",
  ui_story_5037_50372101_66_dialog_content = "Mas não posso simplesmente ignorar as pessoas que precisam de ajuda...",
  ui_story_5037_50372101_67_dialog_content = "E isso é ótimo, definitivamente não mude isso!",
  ui_story_5037_50372101_68_dialog_content = "Tudo bem, entendi.",
  ui_story_5037_50372101_69_dialog_content = "Obrigada, PlayerName.",
  ui_story_5037_50372101_70_dialog_content = "As pessoas sempre gostam de quem ajuda os outros e faz boas ações!",
  ui_story_5037_50372101_71_dialog_content = "PlayerName, devemos ir experimentar o que aprendemos!",
  ui_story_5037_50372101_72_dialog_content = "Agora?!",
  ui_story_5037_50372101_73_dialog_content = "Devemos atacar enquanto o ferro está quente! Vamos-",
  ui_story_5037_50372101_74_dialog_content = "Espere um minuto, Goldie! Não abra a porta ainda!",
  ui_story_5037_50372101_75_dialog_content = "Ah?",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>Ranger-</color>",
  ui_story_5037_50372101_77_dialog_content = "(Tem muita gente lá fora!)",
  ui_story_5037_50372101_78_dialog_content = "Onde está Fleur?",
  ui_story_5037_50372101_79_dialog_content = "Achei que tinha acabado de ouvir alguém gritando o nome dele!",
  ui_story_5037_50372101_80_dialog_content = "Fleuurrrr! Por que voce esta correndo?!",
  ui_story_5037_50372101_81_dialog_content = "Por favor, todos, acalmem-se...",
  ui_story_5037_50372101_82_dialog_content = "NÓS TE AMAMOS!!",
  ui_story_5037_50372101_83_dialog_content = "Uau! Você realmente os atrai!",
  ui_story_5037_50372101_84_dialog_content = "A popularidade parece que pode ser um aborrecimento...",
  ui_story_5037_50372201_1_dialog_content = "\"É solitário no topo.\"",
  ui_story_5037_50372201_2_dialog_content = "\"Comer, beber e dormir sozinho... Esta é a fonte de sua arte.\"",
  ui_story_5037_50372201_3_dialog_content = "\"Sabendo disso, saiba também que a solidão não é um inimigo, mas um amigo, um companheiro constante!\"",
  ui_story_5037_50372201_4_dialog_content = "Surpreendente!",
  ui_story_5037_50372201_5_dialog_content = "Não é uma frase de \"Entrevista com os famosos\"?",
  ui_story_5037_50372201_6_dialog_content = "Obrigado, jovem. O fato de você gostar da minha performance diz muito sobre seus gostos artísticos.",
  ui_story_5037_50372201_7_dialog_content = "Espere, Caronte. Você poderia explicar algo...?",
  ui_story_5037_50372201_8_dialog_content = "Como todo um conjunto de Eraveil apareceu aqui em apenas dez minutos?",
  ui_story_5037_50372201_9_dialog_content = "Você não deveria estar tão surpreso, meu amigo. Os engenheiros da Illumina são os melhores do Astra.",
  ui_story_5037_50372201_10_dialog_content = "Eu não acho que é para isso que você deveria usar engenheiros...",
  ui_story_5037_50372201_11_dialog_content = "Este é um conjunto realmente incrível! Quando entrei, pensei que de alguma forma tinha sido transportado para Eraveil!",
  ui_story_5037_50372201_12_dialog_content = "Por favor, acreditem em mim, amigos. Tudo o que faço é para promover os talentos de atuação dessa jovem.",
  ui_story_5037_50372201_13_dialog_content = "Sério?",
  ui_story_5037_50372201_14_dialog_content = "O verdadeiro conhecimento é adquirido através da prática. É preciso experimentar a atuação, para ganhar experiência na atuação.",
  ui_story_5037_50372201_15_dialog_content = "Preparei o cenário e o roteiro na esperança de que vocês dois pudessem experimentar a beleza da performance.",
  ui_story_5037_50372201_16_dialog_content = "Incrível! Às vezes, os ídolos também precisam atuar em peças.",
  ui_story_5037_50372201_17_dialog_content = "Minhas habilidades de atuação definitivamente melhorariam com a ajuda de um profissional qualificado!",
  ui_story_5037_50372201_18_dialog_content = "Nesse caso, comecemos imediatamente.",
  ui_story_5037_50372201_19_dialog_content = "Aqui está o roteiro que preparei.",
  ui_story_5037_50372201_20_dialog_content = "É...",
  ui_story_5037_50372201_21_dialog_content = "Isso não é apenas \"Ada e o Colosso\", mas com algumas falas alteradas?",
  ui_story_5037_50372201_22_dialog_content = "Isso mesmo. Escolhi intencionalmente uma peça adaptada de um conto de fadas.",
  ui_story_5037_50372201_23_dialog_content = "Os contos de fadas são relativamente simples, fáceis de entender e apresentam poucos desafios para atores novatos.",
  ui_story_5037_50372201_24_dialog_content = "Você pensou em tudo!",
  ui_story_5037_50372201_25_dialog_content = "Mas é claro. Eu sei como é crescer de um ator novato para o ator talentoso que sou hoje!",
  ui_story_5037_50372201_26_dialog_content = "Devemos atribuir papéis, PlayerName?",
  ui_story_5037_50372201_27_dialog_content = "OK. Como estou familiarizado com Colossi, posso assumir o papel de Kaz.",
  ui_story_5037_50372201_28_dialog_content = "Eu vou jogar Ada então!",
  ui_story_5037_50372201_29_dialog_content = "Ela é uma personagem adorável, curiosa sobre tudo e cheia de energia.",
  ui_story_5037_50372201_30_dialog_content = "Assumirei o papel de narrador e outras pequenas partes.",
  ui_story_5037_50372201_31_dialog_content = "Já que está tudo decidido, podemos começar.",
  ui_story_5037_50372201_32_dialog_content = "\"Na pacífica Eraveil jaz, um Colossus chamado Kaz.\"",
  ui_story_5037_50372201_33_dialog_content = "\"Ele anseia pelo céu aberto, mas permanece preso no chão sem um navegador.\"",
  ui_story_5037_50372201_34_dialog_content = "\"No entanto, os Colossos nasceram para os céus!\"",
  ui_story_5037_50372201_35_dialog_content = "\"Pode haver modelos adaptados para terra e mar, mas o céu continua sendo seu verdadeiro lar!\"",
  ui_story_5037_50372201_36_dialog_content = "\"Imagino como é ter um navegador... Como deve ser bom...\"",
  ui_story_5037_50372201_37_dialog_content = "\"Ter um navegador deve ser como ter um melhor amigo...\"",
  ui_story_5037_50372201_38_dialog_content = "\"Huh? Quem vai lá? Como você pode falar comigo...?\"",
  ui_story_5037_50372201_39_dialog_content = "\"É um fantasma? Afinal, nenhum Celestita estaria vagando por este velho Colosso enferrujado...\"",
  ui_story_5037_50372201_40_dialog_content = "\"E, no entanto, aqui diante de você está um celestita!\"",
  ui_story_5037_50372201_41_dialog_content = "\"Ada se aproxima de Kaz, observando como as flores crescem em sua cabeça e estende a mão para tocá-la.\"",
  ui_story_5037_50372201_42_dialog_content = "(Espera aí, ela toca a cabeça dele? Isso não está no meu roteiro...)",
  ui_story_5037_50372201_43_dialog_content = "(O que devo fazer? Apenas continue?)",
  ui_story_5037_50372201_44_option_content = "Continuar o desempenho",
  ui_story_5037_50372201_45_dialog_content = "\"Eu toco...\"",
  ui_story_5037_50372201_46_dialog_content = "\"Heeeey! Você acha que está tudo bem para os caelestitas bisbilhotar os pensamentos privados de alguém, então apenas se aproximar e tocá-los?\"",
  ui_story_5037_50372201_47_dialog_content = "\"Minha linda cabeça não pode ser tocada por qualquer um!\"",
  ui_story_5037_50372201_48_dialog_content = "\"Mas é realmente lindo e adornado com pequenas flores fofas!\"",
  ui_story_5037_50372201_48X1_dialog_content = "Corte!",
  ui_story_5037_50372201_49_dialog_content = "Bem feito, PlayerName!",
  ui_story_5037_50372201_50_dialog_content = "Hã?",
  ui_story_5037_50372201_51_option_content = "Faça uma pergunta",
  ui_story_5037_50372201_52_dialog_content = "Espere um minuto, isso não está no roteiro.",
  ui_story_5037_50372201_52X1_dialog_content = "Corte!",
  ui_story_5037_50372201_53_dialog_content = "Exatamente.",
  ui_story_5037_50372201_54_dialog_content = "O meu também não tem...",
  ui_story_5037_50372201_55_dialog_content = "O que há com isso, Caronte?",
  ui_story_5037_50372201_56_dialog_content = "As apresentações podem precisar de roteiros, mas as pessoas interpretam os papéis.",
  ui_story_5037_50372201_57_dialog_content = "Eventos inesperados podem acontecer durante uma performance. O roteiro nem sempre será seguido à risca.",
  ui_story_5037_50372201_58_dialog_content = "Um ator excepcional deve, portanto, ser capaz de se adaptar e improvisar diante das mudanças das circunstâncias!",
  ui_story_5037_50372201_59_dialog_content = "Entendi!",
  ui_story_5037_50372201_60_dialog_content = "De fato! Já vi algumas peças em que as falas faladas no palco eram diferentes do que estava escrito no roteiro.",
  ui_story_5037_50372201_61_dialog_content = "No entanto, a improvisação do ator foi tão natural que ninguém percebeu!",
  ui_story_5037_50372201_62_dialog_content = "A improvisação é uma habilidade importante para os atores.",
  ui_story_5037_50372201_63_dialog_content = "É preciso primeiro entender o próprio caráter e depois se tornar eles. Só então você pode expressá-los com mais naturalidade.",
  ui_story_5037_50372201_64_dialog_content = "Entendo!",
  ui_story_5037_50372201_65_dialog_content = "Vou trabalhar duro nisso e refinar ainda mais minhas habilidades de atuação!",
  ui_story_5037_50379901_1_dialog_content = "Isso é estranho...",
  ui_story_5037_50379901_2_dialog_content = "Isso é muito estranho!",
  ui_story_5037_50379901_3_dialog_content = "Por que Vice e Carleen têm me evitado nos últimos dias?",
  ui_story_5037_50379901_4_dialog_content = "Eu disse algo que os ofendeu?",
  ui_story_5037_50379901_5_dialog_content = "Não me diga que tem algo a ver com o que aconteceu...",
  ui_story_5037_50379901_6_option_content = "Na ponte",
  ui_story_5037_50379901_7_dialog_content = "Nossa, faz tempo que não uso essa roupa. Pelo menos ainda cabe!",
  ui_story_5037_50379901_8_dialog_content = "O que você acha, PlayerName? Entre este e meu uniforme Illumina habitual, qual você acha que fica melhor?",
  ui_story_5037_50379901_9_dialog_content = "Huh? Não sei.",
  ui_story_5037_50379901_10_dialog_content = "...",
  ui_story_5037_50379901_11_dialog_content = "Eu deveria ter dito que ambos pareciam bons!",
  ui_story_5037_50379901_12_option_content = "no salão",
  ui_story_5037_50379901_13_dialog_content = "PlayerName?!",
  ui_story_5037_50379901_14_dialog_content = "O-O que você está fazendo aqui?! Inversão de marcha! Não olhe!",
  ui_story_5037_50379901_15_dialog_content = "Eu só vim buscar algo para beber...",
  ui_story_5037_50379901_16_dialog_content = "O que você viu agora há pouco...?",
  ui_story_5037_50379901_17_dialog_content = "Huh? Bem, eu vi você de pijama, se olhando feliz no espelho...",
  ui_story_5037_50379901_18_dialog_content = "Você não viu nada!!!",
  ui_story_5037_50379901_19_dialog_content = "Argh! Eu deveria ter ficado na cama naquela noite!",
  ui_story_5037_50379901_20_dialog_content = "Ainda assim, não acho que essas besteiras foram suficientes para fazê-los me ignorar assim...",
  ui_story_5037_50379901_21_dialog_content = "Aaaaah! O que exatamente eu fiz de errado? Está me deixando louco!!",
  ui_story_5037_50379901_22_dialog_content = "Estamos quase no final do ano também! Não podemos entrar no ano novo com esse tipo de estranheza entre nós!",
  ui_story_5037_50379901_23_dialog_content = "M-Talvez eu deva perguntar diretamente a eles?",
  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_5037_50379901_25_dialog_content = "Vício? Carleen? Você aí...?",
  ui_story_5037_50379901_26_dialog_content = "<size=33>Huh? eu-é PlayerName! Ugh... O que ele está fazendo aqui agora?!</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>Pressa...!</size>",
  ui_story_5037_50379901_28_dialog_content = "Ei, PlayerName! Você veio bem na hora!",
  ui_story_5037_50379901_29_dialog_content = "Carleen e eu estávamos prestes a ir procurá-lo. Entre!",
  ui_story_5037_50379901_30_dialog_content = "Huh? Mas vocês dois estão me evitando há dias! O que há com a mudança repentina de atitude?",
  ui_story_5037_50379901_31_dialog_content = "Você saberá assim que entrar!",
  ui_story_5037_50379901_32_dialog_content = "Uh... Por que todas as luzes estão apagadas? Está tão escuro aqui... É meio assustador.",
  ui_story_5037_50379901_33_dialog_content = "Você só experimenta o efeito completo se as luzes estiverem apagadas.",
  ui_story_5037_50379901_34_dialog_content = "Th-O efeito total de quê?!",
  ui_story_5037_50379901_35_dialog_content = "Mantenha os olhos à frente, está começando.",
  ui_story_5037_50379901_36_dialog_content = "Hã?",
  ui_story_5037_50379901_38_dialog_content = "Uau... O tempo voa, não é?",
  ui_story_5037_50379901_39_dialog_content = "Sem perceber, mais um ano já se passou!",
  ui_story_5037_50379901_40_dialog_content = "Mas o fato de parecer tão rápido é uma coisa boa.",
  ui_story_5037_50379901_41_dialog_content = "Significa que tivemos um ano muito significativo.",
  ui_story_5037_50379901_42_dialog_content = "Haha, desde que começamos a nos aventurar com PlayerName, todos os dias parecem significativos!",
  ui_story_5037_50379901_43_dialog_content = "É assim mesmo? Então vamos relembrar, certo?",
  ui_story_5037_50379901_44_dialog_content = "Você ainda se lembra de todos os lugares para onde viajamos no ano passado?",
  ui_story_5037_50379901_45_dialog_content = "Hehe, claro!",
  ui_story_5037_50379901_46_dialog_content = "No ano passado, resistimos a uma forte tempestade antes de finalmente chegarmos a Northland...",
  ui_story_5037_50379901_47_dialog_content = "Essa foi a primeira vez que vi a aurora sobre o Palácio de Inverno com meus próprios olhos!",
  ui_story_5037_50379901_48_dialog_content = "Também foi a primeira vez que experimentei as almôndegas fritas de Northland com molho de morango. Não fazia ideia que os dois combinavam tão perfeitamente!",
  ui_story_5037_50379901_49_dialog_content = "PlayerName passou muito tempo no Lake Mirror durante aquela viagem. Ele disse que viu o passado da rainha na água...",
  ui_story_5037_50379901_50_dialog_content = "Eu me pergunto que tipos de visões se revelaram a ele?",
  ui_story_5037_50379901_51_dialog_content = "Então decoramos a árvore de brilho e fizemos uma contagem regressiva para o ano novo!",
  ui_story_5037_50379901_52_dialog_content = "Ah, isso realmente traz de volta memórias...",
  ui_story_5037_50379901_53_dialog_content = "De quê, almôndegas fritas?",
  ui_story_5037_50379901_54_dialog_content = "Ehehehe...",
  ui_story_5037_50379901_55_dialog_content = "No caminho de volta de Northland, pousamos acidentalmente nas ruínas de uma antiga cidade subterrânea.",
  ui_story_5037_50379901_56_dialog_content = "Para evitar sermos atacados pelos andróides da cidade, tínhamos que vestir as roupas das pessoas que viveram lá.",
  ui_story_5037_50379901_57_dialog_content = "Hahaha! Ainda me lembro da cara do PlayerName quando ele teve que usar aquele vestido!",
  ui_story_5037_50379901_58_dialog_content = "Depois, encontramos um grupo de amigos que também estava preso na cidade.",
  ui_story_5037_50379901_59_dialog_content = "No início, nossas diferenças não causavam nada além de brigas constantes...",
  ui_story_5037_50379901_60_dialog_content = "Mas quando todos trabalharam juntos, finalmente conseguimos convencer aquelas duas garotas que vivem na cidade antiga...",
  ui_story_5037_50379901_61_dialog_content = "E assim todos nós saímos da cidade com segurança antes que ela fosse completamente destruída.",
  ui_story_5037_50379901_62_dialog_content = "PlayerName até recebemos uma mensagem da cidade depois que voltamos!",
  ui_story_5037_50379901_63_dialog_content = "Talvez tenhamos a chance de visitá-lo novamente algum dia.",
  ui_story_5037_50379901_64_dialog_content = "Sim... Mas isso vai ter que esperar! Ainda temos coisas para fazer!",
  ui_story_5037_50379901_65_dialog_content = "Escolha uma flor vermelha para a senhora...",
  ui_story_5037_50379901_66_dialog_content = "Petals fall like snow on a piece of jade.",
  ui_story_5037_50379901_67_dialog_content = "Depois de chegar a Koufu-jou para trabalhar, conhecemos a sacerdotisa da cidade.",
  ui_story_5037_50379901_68_dialog_content = "Também aconteceu o Festival Kasuga na época, então toda a cidade estava coberta de flores de cerejeira rosa brilhante!",
  ui_story_5037_50379901_69_dialog_content = "Mas nenhum de nós sabia que sob a bela aparência de Koufu-jou...",
  ui_story_5037_50379901_70_dialog_content = "Um plano de assassinato estava em andamento.",
  ui_story_5037_50379901_71_dialog_content = "Uma vingança ardente colocou a paz e a prosperidade do passado em chamas.",
  ui_story_5037_50379901_72_dialog_content = "Que canções de tristeza...",
  ui_story_5037_50379901_73_dialog_content = "esperar a cidade?",
  ui_story_5037_50379901_74_dialog_content = "Eu não estava lá, então não tenho como responder a essa pergunta...",
  ui_story_5037_50379901_75_dialog_content = "Ei, sim! Você não estava em Lumopolis na época?",
  ui_story_5037_50379901_76_dialog_content = "N-Próxima vez, Carleen! Prometo que nos lembraremos de convidá-lo da próxima vez!",
  ui_story_5037_50379901_77_dialog_content = "Ei... Espere um segundo! É por isso que você não me pediu para vir quando você convidou PlayerName ver aquele show no Lumópolis?!",
  ui_story_5037_50379901_78_dialog_content = "Já te disse, era só para procurar a Gretel.",
  ui_story_5037_50379901_79_dialog_content = "Seguimos as pistas até a Mansão da Verdade.",
  ui_story_5037_50379901_80_dialog_content = "Ironicamente, estava cheio de tolos completamente irracionais.",
  ui_story_5037_50379901_81_dialog_content = "Confie em mim...",
  ui_story_5037_50379901_82_dialog_content = "Você deve se considerar sortudo por não ter que assistir a essa apresentação.",
  ui_story_5037_50379901_83_dialog_content = "Hmm, isso só me deixa ainda mais curioso!",
  ui_story_5037_50379901_84_dialog_content = "Enfim, não parece que esquecemos alguma coisa?",
  ui_story_5037_50379901_85_dialog_content = "Você quer dizer aquele momento em que PlayerName foi para o Deserto de Rediesel? Você estava lá também, não estava?",
  ui_story_5037_50379901_86_dialog_content = "Ah, sim, o Blazing Rally! eu realmente pensei PlayerName havia sido sequestrado por Sinsa na época.",
  ui_story_5037_50379901_87_dialog_content = "Infelizmente, só consegui alcançá-lo no final do rali.",
  ui_story_5037_50379901_88_dialog_content = "Quanto a PlayerName, não fazia ideia de como ele acabou no banco do carona daquele carro...",
  ui_story_5037_50379901_89_dialog_content = "Ou que tipo de histórias do passado de Azure ela contou a ele, agora que penso nisso...",
  ui_story_5037_50379901_90_dialog_content = "Eu não tenho nenhum dos detalhes.",
  ui_story_5037_50379901_91_dialog_content = "Mas uma coisa eu tenho certeza é que o churrasco Rediesel Desert é absolutamente delicioso!",
  ui_story_5037_50379901_92_dialog_content = "Entendo... Parece que este ano foi cheio de experiências culinárias muito robustas para você, Vice.",
  ui_story_5037_50379901_93_dialog_content = "Você também acha, Carleen?",
  ui_story_5037_50379901_94_dialog_content = "Eu sabia que tinha um talento especial para cozinhar!",
  ui_story_5037_50379901_95_dialog_content = "PlayerName, é só esperar pelos novos pratos que vou preparar!",
  ui_story_5037_50379901_96_dialog_content = "Sabe, ouvi dizer que ele contratou um mordomo profissional quando não estávamos por perto.",
  ui_story_5037_50379901_97_dialog_content = "Durante o período...",
  ui_story_5037_50379901_98_dialog_content = "PlayerName provavelmente comeu muita comida deliciosa.",
  ui_story_5037_50379901_99_dialog_content = "Sim... no começo eu me perguntei como ele iria sobreviver sem nós ao seu lado.",
  ui_story_5037_50379901_100_dialog_content = "Mas ele é totalmente capaz de se alimentar sozinho!",
  ui_story_5037_50379901_101_dialog_content = "Ele até hospeda convidados agora em Cloud Gardens,",
  ui_story_5037_50379901_102_dialog_content = "que é gerido tão meticulosamente bem!",
  ui_story_5037_50379901_103_dialog_content = "Suas habilidades de gerenciamento realmente melhoraram muito.",
  ui_story_5037_50379901_104_dialog_content = "Mas se você me perguntar, ele ainda precisa muito de pessoas ao seu lado.",
  ui_story_5037_50379901_105_dialog_content = "Afinal, ele é do tipo que ajuda seus próprios sequestradores a contar o dinheiro do resgate.",
  ui_story_5037_50379901_106_dialog_content = "Felizmente para ele, o único sequestrador que ele encontrou era apenas um maravilhoso treinador de feras.",
  ui_story_5037_50379901_107_dialog_content = "Quanto ao que exatamente aconteceu durante aquela pequena escapada...",
  ui_story_5037_50379901_108_dialog_content = "Só podemos ler sobre isso em \"As Aventuras do Extrozoologista\" agora.",
  ui_story_5037_50379901_109_dialog_content = "Na verdade, Fia me contou tudo sobre sua aventura. Muitas vezes, na verdade.",
  ui_story_5037_50379901_110_dialog_content = "Huh? Quando?!",
  ui_story_5037_50379901_111_dialog_content = "Encontramos Fia em Harbor City, lembra?",
  ui_story_5037_50379901_112_dialog_content = "Oh! Então foi quando ela te contou sobre isso!",
  ui_story_5037_50379901_113_dialog_content = "Eu me lembro agora... O carnaval no Emerald foi muito divertido!",
  ui_story_5037_50379901_114_dialog_content = "De fato, mas quem poderia imaginar...",
  ui_story_5037_50379901_115_dialog_content = "que por trás de toda a diversão e festividade, Lord Elvis estava tramando algo tão perigoso.",
  ui_story_5037_50379901_116_dialog_content = "Apesar de perceber a extensão de seu sofrimento depois...",
  ui_story_5037_50379901_117_dialog_content = "Como um senhor da cidade, existem certas ações que nunca se deve tomar.",
  ui_story_5037_50379901_118_dialog_content = "Mas no final, Elvis se sacrificou para salvar Harbour City da destruição certa.",
  ui_story_5037_50379901_119_dialog_content = "Naquele dia, ficou muito claro para mim que não podemos definir uma pessoa como totalmente boa ou má.",
  ui_story_5037_50379901_120_dialog_content = "Eu me pergunto se Jeno já encontrou uma maneira de despertar Elvis de seu coma?",
  ui_story_5037_50379901_121_dialog_content = "Se Elvis acordasse do coma, eu o acompanharia pessoalmente de volta a Lumopolis para ser julgado.",
  ui_story_5037_50379901_122_dialog_content = "Ah, uh... Certo...",
  ui_story_5037_50379901_123_dialog_content = "Depois de voltar de Harbour City, PlayerName encontrou Corax, que estava no meio de uma caçada a um assassino em série.",
  ui_story_5037_50379901_124_dialog_content = "Eles seguiram o rastro do assassino até uma pequena cidade chamada Euphoria.",
  ui_story_5037_50379901_125_dialog_content = "Mesmo que as pessoas o conhecessem como o País das Maravilhas, Euphoria agora está completamente atolada no crime organizado e na violência de gangues.",
  ui_story_5037_50379901_126_dialog_content = "Todos os dias, você ouve sobre todos os tipos de assassinatos, roubos e lutas internas nas gangues locais.",
  ui_story_5037_50379901_127_dialog_content = "Mas mesmo em um lugar tão sujo e perigoso quanto Euphoria, lindas hortênsias ainda florescem por toda parte.",
  ui_story_5037_50379901_128_dialog_content = "Acredito que Euphoria se tornará um verdadeiro País das Maravilhas novamente em breve.",
  ui_story_5037_50379901_129_dialog_content = "Enfim, não muito depois dessa aventura...",
  ui_story_5037_50379901_130_dialog_content = "PlayerName e fui conferir a inauguração da Andersen Haunted House!",
  ui_story_5037_50379901_131_dialog_content = "Por total coincidência, acabamos fazendo parte de um vídeo de investigação sobrenatural.",
  ui_story_5037_50379901_132_dialog_content = "Nós só queríamos nos divertir... Quem diria que havia atividade paranormal real acontecendo lá?!",
  ui_story_5037_50379901_133_dialog_content = "Os gritos que ouvimos dentro da casa assombrada eram completamente reais!",
  ui_story_5037_50379901_134_dialog_content = "E meu diretor de filmes de terror favorito... Ele sempre usou Eclipsites em suas cenas!",
  ui_story_5037_50379901_135_dialog_content = "Graças a Deus eu tinha outros negócios na época...",
  ui_story_5037_50379901_136_dialog_content = "Não me diga que o todo-poderoso Carleen tem medo de casas assombradas?",
  ui_story_5037_50379901_137_dialog_content = "Hmph. Eu só estava preocupado que eu teria assustado aquele fantasma feminino até a morte... Por assim dizer.",
  ui_story_5037_50379901_138_dialog_content = "Hahahaha! Você realmente acha que é tão assustador?",
  ui_story_5037_50379901_139_dialog_content = "...",
  ui_story_5037_50379901_140_dialog_content = "<size=45>Ah—fantasma!!!</size>",
  ui_story_5037_50379901_141_dialog_content = "Ver? Foi isso que eu quis dizer.",
  ui_story_5037_50379901_142_dialog_content = "E-foi você, Carleen?! Não me diga... Você também é um fantasma?!",
