  ui_story_5037_50379901_144_dialog_content = "S-Sim, você está certo...",
  ui_story_5037_50379901_145_dialog_content = "Aham! Mas chega disso! De volta ao verdadeiro motivo de estarmos aqui!",
  ui_story_5037_50379901_146_dialog_content = "O ano está acabando logo, PlayerName.",
  ui_story_5037_50379901_147_dialog_content = "Preparamos este vídeo para ajudar você a se lembrar de tudo o que fizemos este ano!",
  ui_story_5037_50379901_148_dialog_content = "No próximo ano você deve se lembrar...",
