  ui_story_5037_50379901_160_dialog_content = "E algumas coisas são muito difíceis de dizer pessoalmente...",
  ui_story_5037_50379901_161_dialog_content = "A menos que... você não goste da nossa surpresa em vídeo?",
  ui_story_5037_50379901_162_option_content = "Gostei!",
